INSERT INTO "problems" ("id", "title", "slug", "difficulty", "description", "inputFormat", "outputFormat", "constraints", "examples", "explanation", "leetcodeUrl", "youtubeUrl", "apnaYoutubeUrl", "isFree", "price", "order", "isPublished", "categoryId", "createdAt", "updatedAt") VALUES ('cmwolljxo00plo76vd6vfnq2a', 'Find Pairs with Given Sum in Doubly Linked List', 'find-pairs-with-given-sum-in-doubly-linked-list', 'MEDIUM', 'Given a sorted doubly linked list of positive distinct integers, find all pairs of numbers in the list that sum up to a given value `target`. Solve in O(N) time and O(1) extra space using two pointers (`left` starting at head and `right` starting at tail).', 'The `head` of a sorted DLL and integer `target`.', 'Return a list of pairs `[first, second]` summing to `target`.', '1 <= nodes <= 10^5
