INSERT INTO "problems" ("id", "title", "slug", "difficulty", "description", "inputFormat", "outputFormat", "constraints", "examples", "explanation", "leetcodeUrl", "youtubeUrl", "apnaYoutubeUrl", "isFree", "price", "order", "isPublished", "categoryId", "createdAt", "updatedAt") VALUES ('cmwolljyn00slo76v809x1xe6', 'Candy', 'candy', 'HARD', 'There are `n` children standing in a line. Each child is assigned a rating value given in the integer array `ratings`. You must give each child at least one candy. Children with a higher rating get more candies than their immediate neighbors. Return the minimum number of candies you need to have to distribute the candies to the children. Solve in O(N) time with O(N) space using left and right passes.', 'An integer array `ratings` of length `n`.', 'Return the minimum total candies needed.', 'n == ratings.length
1 <= n <= 2 * 10^4
0 <= ratings[i] <= 2 * 10^4', '[{"input":"ratings = [1, 0, 2]","output":"5","explanation":"You can allocate to the first, second and third child with 2, 1, 2 candies respectively."},{"input":"ratings = [1, 2, 2]","output":"4","explanation":"You can allocate 1, 2, 1 candies. The third child gets 1 candy because it satisfies the above two conditions."}]'::jsonb, NULL, 'https://leetcode.com/problems/candy/', 'https://youtu.be/IIqVFvKE6RY?si=EjmuXZJNLQLUkEd7', NULL, true, 0, 13, true, 'cmwn97dlj000fo4zikohcyv0n', '2026-11-20T06:28:30.672Z', '2026-11-24T08:12:40.227Z') ON CONFLICT DO NOTHING;
INSERT INTO "problems" ("id", "title", "slug", "difficulty", "description", "inputFormat", "outputFormat", "constraints", "examples", "explanation", "leetcodeUrl", "youtubeUrl", "apnaYoutubeUrl", "isFree", "price", "order", "isPublished", "categoryId", "createdAt", "updatedAt") VALUES ('cmwolljzl00w5o76vlchc2vp2', 'Sum of Subarray Minimums', 'sum-of-subarray-minimums', 'MEDIUM', 'Given an array of integers `arr`, find the sum of `min(b)`, where `b` ranges over every (contiguous) subarray of `arr`. Since the answer may be large, return the answer modulo `10^9 + 7`. Solve in O(N) time by finding Previous Less Element (PLE) and Next Less Element (NLE) for each element using monotonic stacks.', 'An integer array `arr`.', 'Return sum of subarray minimums modulo 10^9 + 7.', '1 <= arr.length <= 3 * 10^4
1 <= arr[i] <= 3 * 10^4', '[{"input":"arr = [3, 1, 2, 4]","output":"17","explanation":"Subarrays: [3] min 3; [1] min 1; [2] min 2; [4] min 4; [3, 1] min 1; [1, 2] min 1; [2, 4] min 2; [3, 1, 2] min 1; [1, 2, 4] min 1; [3, 1, 2, 4] min 1. Sum = 17."},{"input":"arr = [11, 81, 94, 43, 3]","output":"444","explanation":"Sum of all subarray minimums modulo 10^9 + 7 is 444."}]'::jsonb, NULL, 'https://leetcode.com/problems/sum-of-subarray-minimums/', 'https://youtu.be/v0e8p9JCgRc?si=XAU7ekECgS5nboRw', NULL, true, 0, 18, true, 'cmwnkk8sm000ajqrho65tpyxj', '2026-11-20T06:28:30.706Z', '2026-11-24T08:12:43.715Z') ON CONFLICT DO NOTHING;
INSERT INTO "problems" ("id", "title", "slug", "difficulty", "description", "inputFormat", "outputFormat", "constraints", "examples", "explanation", "leetcodeUrl", "youtubeUrl", "apnaYoutubeUrl", "isFree", "price", "order", "isPublished", "categoryId", "createdAt", "updatedAt") VALUES ('cmwollk0t00zxo76vabsoojb2', 'Lowest Common Ancestor in BT', 'lca-in-bt', 'HARD', 'Given a binary tree, find the Lowest Common Ancestor (LCA) of two given nodes `p` and `q`. The lowest common ancestor is defined between two nodes `p` and `q` as the lowest node in `T` that has both `p` and `q` as descendants. Solve in O(N) time with postorder recursion.', 'The `root` of a binary tree and two nodes `p` and `q`.', 'Return the LCA node.', 'The number of nodes in the tree is in the range [2, 10^5].
-10^9 <= Node.val <= 10^9
All Node.val are unique.
p != q and both p and q exist in the tree.', '[{"input":"root = [3, 5, 1, 6, 2, 0, 8, null, null, 7, 4], p = 5, q = 1","output":"3","explanation":"The LCA of nodes 5 and 1 is 3."},{"input":"root = [3, 5, 1, 6, 2, 0, 8, null, null, 7, 4], p = 5, q = 4","output":"5","explanation":"The LCA of nodes 5 and 4 is 5, since a node can be a descendant of itself."}]'::jsonb, NULL, 'https://leetcode.com/problems/lowest-common-ancestor-of-a-binary-tree/', 'https://youtu.be/_-QHfMDde90', 'https://www.youtube.com/watch?v=oX5D0uKOMck', true, 0, 21, true, 'cmwn97dlg0009o4zir36epbdz', '2026-11-20T06:28:30.749Z', '2026-11-24T08:12:49.445Z') ON CONFLICT DO NOTHING;
