INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwn97dlq000no4ziekfdi3iw', 'cmwn97dll000lo4zi9yry1x2b', 'BRUTE_FORCE', 'Quick Sort Solution', '', 'public class QuickSort {
    private static int partition(int[] arr, int low, int high) {
        int pivot = arr[low];
        int i = low;
        int j = high;

        while (i < j) {
            while (arr[i] <= pivot && i <= high - 1) {
                i++;
            }
            while (arr[j] > pivot && j >= low + 1) {
                j--;
            }
            if (i < j) {
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
        int temp = arr[low];
        arr[low] = arr[j];
        arr[j] = temp;
        return j;
    }

    public static void quickSort(int[] arr, int low, int high) {
        if (low < high) {
            int pIndex = partition(arr, low, high);
            quickSort(arr, low, pIndex - 1);
            quickSort(arr, pIndex + 1, high);
        }
    }
}', 'O(N log N)', 'O(1)', '2026-11-19T07:53:47.678Z', '2026-11-20T05:26:42.703Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljqs000io76vpjkg3hmp', 'cmwolljqs000ho76vrsgiukxp', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findMax(int a, int b, int c) {
        if (a >= b && a >= c) return a;
        else if (b >= a && b >= c) return b;
        else return c;
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.388Z', '2026-11-20T06:28:30.388Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljqs000jo76vhpahaqri', 'cmwolljqs000ho76vrsgiukxp', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findMax(int a, int b, int c) {
        return Math.max(a, Math.max(b, c));
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.388Z', '2026-11-20T06:28:30.388Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljqu000mo76v66dn4wnr', 'cmwolljqu000lo76v165l1w6o', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int safeDivide(int a, int b) {
        // Check edge cases: zero division
        if (b == 0) return -1;
        return a / b;
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.390Z', '2026-11-20T06:28:30.390Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwn97dm1001bo4zigcckky0g', 'cmwn97dm00019o4zi6ztbp2yo', 'BRUTE_FORCE', 'Bubble Sort Solution', '', 'public class BubbleSort {
    public static void bubbleSort(int[] arr) {
        int n = arr.length;
        for (int i = n - 1; i >= 1; i--) {
            boolean didSwap = false;
            for (int j = 0; j <= i - 1; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                    didSwap = true;
                }
            }
            if (!didSwap) break;
        }
    }
}', 'O(N²)', 'O(1)', '2026-11-19T07:53:47.689Z', '2026-11-20T05:26:42.696Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwn97dm1001do4zifialscrx', 'cmwn97dm00019o4zi6ztbp2yo', 'OPTIMAL', 'Bubble Sort Solution', '', 'public class BubbleSort {
    public static void bubbleSort(int[] arr) {
        int n = arr.length;
        for (int i = n - 1; i >= 1; i--) {
