INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwn97dm7001to4ziwl5pkdt1', 'cmwn97dm6001po4zimaulkps1', 'OPTIMAL', 'Insertion Sort Solution', '', 'public class InsertionSort {
    public static void insertionSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i <= n - 1; i++) {
            int j = i;
            while (j > 0 && arr[j - 1] > arr[j]) {
                int temp = arr[j - 1];
                arr[j - 1] = arr[j];
                arr[j] = temp;
                j--;
            }
        }
    }
}', 'O(N²)', 'O(1)', '2026-11-19T07:53:47.695Z', '2026-11-20T05:26:42.699Z') ON CONFLICT DO NOTHING;
