INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwn97dm4001lo4ziz4xms8t6', 'cmwn97dm3001ho4zidgu5v6qg', 'OPTIMAL', 'Selection Sort Solution', '', 'public class SelectionSort {
    public static void selectionSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] < arr[minIdx]) {
                    minIdx = j;
                }
            }
            int temp = arr[minIdx];
            arr[minIdx] = arr[i];
            arr[i] = temp;
        }
    }
}', 'O(N²)', 'O(1)', '2026-11-19T07:53:47.693Z', '2026-11-20T05:26:42.694Z') ON CONFLICT DO NOTHING;
