INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwn97dm4001jo4ziadydes1s', 'cmwn97dm3001ho4zidgu5v6qg', 'BRUTE_FORCE', 'Selection Sort Solution', '', 'public class SelectionSort {
    public static void selectionSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] < arr[minIdx]) {
                    minIdx = j;
                }
            }
            int temp = arr[minIdx];
            arr[minIdx] = arr[i];
            arr[i] = temp;
        }
    }
}', 'O(N²)', 'O(1)', '2026-11-19T07:53:47.692Z', '2026-11-20T05:26:42.693Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwnkk8t2001kjqrhgdp8t7m0', 'cmwnkk8t1001ijqrhfqg7fe5n', 'BRUTE_FORCE', 'Recursive Bubble Sort Solution', '', 'public class RecursiveBubbleSort {
    public static void bubbleSort(int[] arr, int n) {
        if (n == 1) return;

        boolean didSwap = false;
        for (int j = 0; j <= n - 2; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                didSwap = true;
            }
        }

        if (!didSwap) return;

        bubbleSort(arr, n - 1);
    }
}', 'O(N²)', 'O(N)', '2026-11-19T13:11:43.767Z', '2026-11-20T05:26:42.704Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwnkk8t3001mjqrhqtirt35i', 'cmwnkk8t1001ijqrhfqg7fe5n', 'OPTIMAL', 'Recursive Bubble Sort Solution', '', 'public class RecursiveBubbleSort {
    public static void bubbleSort(int[] arr, int n) {
