INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwnkk8t5001sjqrhfxbv0g48', 'cmwnkk8t4001qjqrh96vw10wg', 'BRUTE_FORCE', 'Recursive Insertion Sort Solution', '', 'public class RecursiveInsertionSort {
    public static void insertionSort(int[] arr, int i, int n) {
        if (i == n) return;

        int j = i;
        while (j > 0 && arr[j - 1] > arr[j]) {
            int temp = arr[j - 1];
            arr[j - 1] = arr[j];
            arr[j] = temp;
            j--;
        }

        insertionSort(arr, i + 1, n);
    }
}', 'O(N²)', 'O(N)', '2026-11-19T13:11:43.769Z', '2026-11-20T05:26:42.706Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwnkk8t5001ujqrheu9xw5k0', 'cmwnkk8t4001qjqrh96vw10wg', 'OPTIMAL', 'Recursive Insertion Sort Solution', '', 'public class RecursiveInsertionSort {
    public static void insertionSort(int[] arr, int i, int n) {
        if (i == n) return;

        int j = i;
        while (j > 0 && arr[j - 1] > arr[j]) {
