INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljqp000ao76vg03w7492', 'cmwolljqp0009o76vujo7hysh', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    // Problem decomposition: break down big problem into sub-problems
    public static int solve(int n) {
        int total = 0;
        for (int i = 1; i <= n; i++) {
