INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljrd002ao76vtszzt85j', 'cmwolljrd0029o76v78ypgu40', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void pattern9(int n) {
        // Upper pyramid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - i - 1; j++) System.out.print(" ");
            for (int j = 0; j < 2 * i + 1; j++) System.out.print("*");
            System.out.println();
        }
        // Inverted pyramid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) System.out.print(" ");
            for (int j = 0; j < 2 * (n - i) - 1; j++) System.out.print("*");
            System.out.println();
        }
    }
}', 'O(N^2)', 'O(1)', '2026-11-20T06:28:30.410Z', '2026-11-20T06:28:30.410Z') ON CONFLICT DO NOTHING;
