INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljrf002eo76vbc8tl6sf', 'cmwolljrf002do76v6yj19ewo', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void pattern10(int n) {
        for (int i = 1; i <= 2 * n - 1; i++) {
