INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljrg002io76vj0x7v9a4', 'cmwolljrg002ho76vx6vzh55n', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void pattern11(int n) {
        int start = 1;
        for (int i = 0; i < n; i++) {
            start = (i % 2 == 0) ? 1 : 0;
            for (int j = 0; j <= i; j++) {
                System.out.print(start + " ");
                start = 1 - start;
            }
            System.out.println();
        }
    }
}', 'O(N^2)', 'O(1)', '2026-11-20T06:28:30.412Z', '2026-11-20T06:28:30.412Z') ON CONFLICT DO NOTHING;
