INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljrh002mo76vnrhkmc48', 'cmwolljrh002lo76vhp8cj7zs', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void pattern12(int n) {
        int spaces = 2 * (n - 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) System.out.print(j);
            for (int j = 1; j <= spaces; j++) System.out.print(" ");
            for (int j = i; j >= 1; j--) System.out.print(j);
            System.out.println();
            spaces -= 2;
        }
    }
}', 'O(N^2)', 'O(1)', '2026-11-20T06:28:30.414Z', '2026-11-20T06:28:30.414Z') ON CONFLICT DO NOTHING;
