INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljrp003ao76vmlitkyue', 'cmwolljrp0039o76vkpac0aop', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void pattern18(int n) {
        for (int i = 0; i < n; i++) {
            for (char ch = (char) (''A'' + n - 1); ch >= (char) (''A'' + n - 1 - i); ch--) {
                System.out.print(ch + " ");
