INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljrr003io76v570q8d06', 'cmwolljrr003ho76v6cndc838', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void pattern20(int n) {
        int spaces = 2 * n - 2;
        for (int i = 1; i <= 2 * n - 1; i++) {
            int stars = i <= n ? i : 2 * n - i;
            for (int j = 1; j <= stars; j++) System.out.print("*");
            for (int j = 1; j <= spaces; j++) System.out.print(" ");
            for (int j = 1; j <= stars; j++) System.out.print("*");
            System.out.println();
            if (i < n) spaces -= 2;
            else spaces += 2;
        }
    }
}', 'O(N^2)', 'O(1)', '2026-11-20T06:28:30.424Z', '2026-11-20T06:28:30.424Z') ON CONFLICT DO NOTHING;
