INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs4004mo76v3tt5e1oz', 'cmwolljs4004lo76vaqfc5g8x', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
public class Solution {
    public static void frequency(int[] arr) {
        HashMap<Integer, Integer> map = new HashMap<>();
        for (int x : arr) map.put(x, map.getOrDefault(x, 0) + 1);
        System.out.println(map);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.436Z', '2026-11-20T06:28:30.436Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs4004no76vpfsz5648', 'cmwolljs4004lo76vaqfc5g8x', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void frequency(int[] arr) {
        int max = 0;
        for (int x : arr) max = Math.max(max, x);
        int[] hash = new int[max + 1];
        for (int x : arr) hash[x]++;
    }
}', 'O(N + maxVal)', 'O(maxVal)', '2026-11-20T06:28:30.436Z', '2026-11-20T06:28:30.436Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs5004qo76vqj3m9xvy', 'cmwolljs5004po76v7m02bgh2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isPalindrome(String s) {
        String rev = "";
        for (int i = s.length() - 1; i >= 0; i--) rev += s.charAt(i);
        return s.equals(rev);
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.437Z', '2026-11-20T06:28:30.437Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs5004ro76vxis9u9rz', 'cmwolljs5004po76v7m02bgh2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left++) != s.charAt(right--)) return false;
        }
        return true;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.437Z', '2026-11-20T06:28:30.437Z') ON CONFLICT DO NOTHING;
