INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs7004yo76vgxx34bat', 'cmwolljs7004xo76vb8u28o5p', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int countOddDigits(int n) {
        int cnt = 0;
        while (n > 0) {
            int digit = n % 10;
            if (digit % 2 != 0) cnt++;
            n /= 10;
        }
        return cnt;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.440Z', '2026-11-20T06:28:30.440Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs7004zo76v1w8f7q19', 'cmwolljs7004xo76vb8u28o5p', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countOddDigits(int n) {
        int cnt = 0;
        while (n > 0) {
            if ((n % 10) % 2 != 0) cnt++;
            n /= 10;
        }
        return cnt;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.440Z', '2026-11-20T06:28:30.440Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs90052o76vnqye4xbo', 'cmwolljs90051o76vi9ryl4of', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int reverse(int x) {
        long rev = 0;
        while (x != 0) {
            rev = rev * 10 + x % 10;
            x /= 10;
        }
        if (rev > Integer.MAX_VALUE || rev < Integer.MIN_VALUE) return 0;
        return (int) rev;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.441Z', '2026-11-20T06:28:30.441Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljs90053o76v1372lmjd', 'cmwolljs90051o76vi9ryl4of', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int reverse(int x) {
        int rev = 0;
        while (x != 0) {
            int pop = x % 10;
            x /= 10;
            if (rev > Integer.MAX_VALUE / 10 || (rev == Integer.MAX_VALUE / 10 && pop > 7)) return 0;
            if (rev < Integer.MIN_VALUE / 10 || (rev == Integer.MIN_VALUE / 10 && pop < -8)) return 0;
            rev = rev * 10 + pop;
        }
        return rev;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.441Z', '2026-11-20T06:28:30.441Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsa0056o76vpnwl6ebv', 'cmwolljsa0055o76v6oe8t55k', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public boolean isPalindrome(int x) {
        if (x < 0) return false;
        String s = Integer.toString(x);
        String rev = new StringBuilder(s).reverse().toString();
        return s.equals(rev);
    }
}', 'O(log10 N)', 'O(log10 N)', '2026-11-20T06:28:30.443Z', '2026-11-20T06:28:30.443Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsa0057o76vyt1r6h5r', 'cmwolljsa0055o76v6oe8t55k', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public boolean isPalindrome(int x) {
        if (x < 0 || (x % 10 == 0 && x != 0)) return false;
        int revertedNumber = 0;
        while (x > revertedNumber) {
            revertedNumber = revertedNumber * 10 + x % 10;
            x /= 10;
        }
        return x == revertedNumber || x == revertedNumber / 10;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.443Z', '2026-11-20T06:28:30.443Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsb005ao76vge9risxh', 'cmwolljsb0059o76v0lr69gs9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int largestDigit(int n) {
        int maxD = 0;
        while (n > 0) {
            maxD = Math.max(maxD, n % 10);
            n /= 10;
        }
        return maxD;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.444Z', '2026-11-20T06:28:30.444Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsb005bo76v2l9y2pt9', 'cmwolljsb0059o76v0lr69gs9', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int largestDigit(int n) {
        int maxD = 0;
        while (n > 0) {
            int d = n % 10;
            if (d == 9) return 9;
            if (d > maxD) maxD = d;
            n /= 10;
        }
        return maxD;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.444Z', '2026-11-20T06:28:30.444Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsc005eo76vzwarwbqf', 'cmwolljsc005do76v62tucety', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long factorial(int n) {
        long ans = 1;
        for (int i = 1; i <= n; i++) ans *= i;
        return ans;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.445Z', '2026-11-20T06:28:30.445Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsc005fo76v04vxx11n', 'cmwolljsc005do76v62tucety', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long factorial(int n) {
        if (n <= 1) return 1;
        return n * factorial(n - 1);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.445Z', '2026-11-20T06:28:30.445Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljse005io76vx8z7c4xo', 'cmwolljse005ho76v7gx35c0u', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean checkArmstrong(int n) {
        int temp = n, sum = 0, k = String.valueOf(n).length();
        while (temp > 0) {
            int ld = temp % 10;
            sum += Math.pow(ld, k);
            temp /= 10;
        }
        return sum == n;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.446Z', '2026-11-20T06:28:30.446Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljse005jo76v64a0j66d', 'cmwolljse005ho76v7gx35c0u', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean checkArmstrong(int n) {
        int count = 0, temp = n;
        while (temp > 0) { count++; temp /= 10; }
        temp = n;
        int sum = 0;
        while (temp > 0) {
            int ld = temp % 10;
            int pow = 1;
            for (int i = 0; i < count; i++) pow *= ld;
            sum += pow;
            temp /= 10;
        }
        return sum == n;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.446Z', '2026-11-20T06:28:30.446Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsf005mo76vxbeolwuu', 'cmwolljsf005lo76vbikrr79w', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public boolean checkPerfectNumber(int num) {
        if (num <= 1) return false;
        int sum = 0;
        for (int i = 1; i < num; i++) {
            if (num % i == 0) sum += i;
        }
        return sum == num;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.448Z', '2026-11-20T06:28:30.448Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsf005no76vhlu8ifku', 'cmwolljsf005lo76vbikrr79w', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public boolean checkPerfectNumber(int num) {
        if (num <= 1) return false;
        int sum = 1;
        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                sum += i;
                if (i * i != num) sum += num / i;
            }
        }
        return sum == num;
    }
}', 'O(sqrt(N))', 'O(1)', '2026-11-20T06:28:30.448Z', '2026-11-20T06:28:30.448Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsg005qo76v8kjf2r95', 'cmwolljsg005po76vl16i9q90', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i < n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.449Z', '2026-11-20T06:28:30.449Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsg005ro76vtbzh3lcj', 'cmwolljsg005po76vl16i9q90', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
