INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsh005uo76vpr0taocn', 'cmwolljsh005to76v6bcan6fa', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int countPrimes(int n) {
        int cnt = 0;
        for (int i = 2; i < n; i++) {
            if (isPrime(i)) cnt++;
        }
        return cnt;
    }
    private boolean isPrime(int x) {
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) return false;
        }
        return true;
    }
}', 'O(N * sqrt(N))', 'O(1)', '2026-11-20T06:28:30.450Z', '2026-11-20T06:28:30.450Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsh005vo76vdyrwpv3n', 'cmwolljsh005to76v6bcan6fa', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;
public class Solution {
    public int countPrimes(int n) {
        if (n <= 2) return 0;
        boolean[] isPrime = new boolean[n];
        Arrays.fill(isPrime, true);
        int cnt = 0;
        for (int p = 2; p * p < n; p++) {
            if (isPrime[p]) {
                for (int i = p * p; i < n; i += p) isPrime[i] = false;
            }
        }
        for (int i = 2; i < n; i++) if (isPrime[i]) cnt++;
        return cnt;
    }
}', 'O(N log log N)', 'O(N)', '2026-11-20T06:28:30.450Z', '2026-11-20T06:28:30.450Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsj005yo76vg40jaged', 'cmwolljsj005xo76vopazkmra', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int gcd(int a, int b) {
        int ans = 1;
        for (int i = 1; i <= Math.min(a, b); i++) {
            if (a % i == 0 && b % i == 0) ans = i;
        }
        return ans;
    }
}', 'O(min(A, B))', 'O(1)', '2026-11-20T06:28:30.451Z', '2026-11-20T06:28:30.451Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsj005zo76v5xfvd0nd', 'cmwolljsj005xo76vopazkmra', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int gcd(int a, int b) {
        while (a > 0 && b > 0) {
            if (a > b) a = a % b;
            else b = b % a;
        }
        return (a == 0) ? b : a;
    }
}', 'O(log(min(A, B)))', 'O(1)', '2026-11-20T06:28:30.451Z', '2026-11-20T06:28:30.451Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsk0062o76vcezm90oj', 'cmwolljsk0061o76v5aqzv6k5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long lcm(long a, long b) {
        long max = Math.max(a, b);
        while (true) {
            if (max % a == 0 && max % b == 0) return max;
            max++;
        }
    }
}', 'O(A * B)', 'O(1)', '2026-11-20T06:28:30.452Z', '2026-11-20T06:28:30.452Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsk0063o76vdc0urckv', 'cmwolljsk0061o76v5aqzv6k5', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long lcm(long a, long b) {
        return (a / gcd(a, b)) * b;
    }
    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}', 'O(log(min(A, B)))', 'O(1)', '2026-11-20T06:28:30.452Z', '2026-11-20T06:28:30.452Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsl0066o76v0vkcm6cp', 'cmwolljsl0065o76vovkusu2o', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public static List<Integer> printDivisors(int n) {
        List<Integer> list = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (n % i == 0) list.add(i);
        }
        return list;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.454Z', '2026-11-20T06:28:30.454Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsl0067o76v20zwcgno', 'cmwolljsl0065o76vovkusu2o', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public static List<Integer> printDivisors(int n) {
        List<Integer> list = new ArrayList<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                list.add(i);
                if (i * i != n) list.add(n / i);
            }
        }
        Collections.sort(list);
        return list;
    }
}', 'O(sqrt(N))', 'O(sqrt(N))', '2026-11-20T06:28:30.454Z', '2026-11-20T06:28:30.454Z') ON CONFLICT DO NOTHING;
