INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsp006io76vam13qilx', 'cmwolljsp006ho76v2mkv17vc', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isSorted(int n, int []a) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (a[j] < a[i]) return false;
            }
        }
        return true;
