}', 'O(N^2)', 'O(1)', '2026-11-20T06:28:30.457Z', '2026-11-20T06:28:30.457Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsp006jo76v2w4t28zd', 'cmwolljsp006ho76v2mkv17vc', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
