INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsq006mo76vxlufr2yf', 'cmwolljsq006lo76v3xehpe5h', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void reverseArray(int arr[]) {
        int n = arr.length;
        int[] temp = new int[n];
        for (int i = 0; i < n; i++) temp[i] = arr[n - 1 - i];
        for (int i = 0; i < n; i++) arr[i] = temp[i];
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.459Z', '2026-11-20T06:28:30.459Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsq006no76vqf32kr58', 'cmwolljsq006lo76v3xehpe5h', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void reverseArray(int arr[]) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++; right--;
        }
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.459Z', '2026-11-20T06:28:30.459Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsr006qo76vekyymijg', 'cmwolljsr006po76v1uwdknt0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int mostFrequentElement(int[] nums) {
        int maxFreq = 0, ans = nums[0];
        for (int i = 0; i < nums.length; i++) {
            int count = 0;
            for (int j = 0; j < nums.length; j++) {
                if (nums[j] == nums[i]) count++;
            }
            if (count > maxFreq) {
                maxFreq = count;
                ans = nums[i];
            }
        }
        return ans;
    }
}', 'O(N^2)', 'O(1)', '2026-11-20T06:28:30.460Z', '2026-11-20T06:28:30.460Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsr006ro76v3zpufpls', 'cmwolljsr006po76v1uwdknt0', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public static int mostFrequentElement(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        int maxFreq = 0, ans = nums[0];
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() > maxFreq || (entry.getValue() == maxFreq && entry.getKey() < ans)) {
                maxFreq = entry.getValue();
                ans = entry.getKey();
            }
        }
        return ans;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.460Z', '2026-11-20T06:28:30.460Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljst006uo76v1p4aq05p', 'cmwolljst006to76vd3zgnzau', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public static int secondMostFrequentElement(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        int maxF = 0, secondMaxF = 0;
        for (int freq : map.values()) {
            if (freq > maxF) { secondMaxF = maxF; maxF = freq; }
            else if (freq > secondMaxF && freq < maxF) secondMaxF = freq;
        }
        int ans = -1;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() == secondMaxF) {
                if (ans == -1 || entry.getKey() < ans) ans = entry.getKey();
            }
        }
        return ans;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.461Z', '2026-11-20T06:28:30.461Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljst006vo76vh2jvmxy7', 'cmwolljst006to76vd3zgnzau', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public static int secondMostFrequentElement(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        int maxF = 0, secondMaxF = 0;
        for (int freq : map.values()) {
            if (freq > maxF) { secondMaxF = maxF; maxF = freq; }
            else if (freq > secondMaxF && freq < maxF) secondMaxF = freq;
        }
        int ans = -1;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() == secondMaxF) {
                if (ans == -1 || entry.getKey() < ans) ans = entry.getKey();
            }
        }
        return ans;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.461Z', '2026-11-20T06:28:30.461Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsu006yo76vbcmsjn9q', 'cmwolljsu006xo76v1ae3fmju', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public static int sumHighestAndLowestFreq(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        int maxF = 0, minF = Integer.MAX_VALUE;
        for (int freq : map.values()) {
            maxF = Math.max(maxF, freq);
            minF = Math.min(minF, freq);
        }
        return maxF + minF;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.462Z', '2026-11-20T06:28:30.462Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsu006zo76v8r1arsib', 'cmwolljsu006xo76v1ae3fmju', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public static int sumHighestAndLowestFreq(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
