INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsv0072o76vryuv95c7', 'cmwolljsv0071o76vyaujhbys', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public String reverseStr(String s, int k) {
        char[] a = s.toCharArray();
        for (int start = 0; start < a.length; start += 2 * k) {
            int i = start, j = Math.min(start + k - 1, a.length - 1);
            while (i < j) {
                char tmp = a[i];
                a[i++] = a[j];
                a[j--] = tmp;
            }
        }
        return new String(a);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.464Z', '2026-11-20T06:28:30.464Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsv0073o76v0np1gzl8', 'cmwolljsv0071o76vyaujhbys', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public String reverseStr(String s, int k) {
        char[] a = s.toCharArray();
        for (int start = 0; start < a.length; start += 2 * k) {
            int i = start, j = Math.min(start + k - 1, a.length - 1);
            while (i < j) {
                char tmp = a[i];
                a[i++] = a[j];
                a[j--] = tmp;
            }
        }
        return new String(a);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.464Z', '2026-11-20T06:28:30.464Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsx0076o76vkiydepm2', 'cmwolljsx0075o76vkkcfinx8', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public boolean isPalindrome(String s) {
        StringBuilder filtered = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (Character.isLetterOrDigit(ch)) filtered.append(Character.toLowerCase(ch));
        }
        String orig = filtered.toString();
        String rev = filtered.reverse().toString();
        return orig.equals(rev);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.465Z', '2026-11-20T06:28:30.465Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsx0077o76v1uj2if8y', 'cmwolljsx0075o76vkkcfinx8', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public boolean isPalindrome(String s) {
        int i = 0, j = s.length() - 1;
        while (i < j) {
            while (i < j && !Character.isLetterOrDigit(s.charAt(i))) i++;
            while (i < j && !Character.isLetterOrDigit(s.charAt(j))) j--;
            if (Character.toLowerCase(s.charAt(i)) != Character.toLowerCase(s.charAt(j))) return false;
            i++; j--;
        }
        return true;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.465Z', '2026-11-20T06:28:30.465Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsy007ao76v47u2u875', 'cmwolljsy0079o76vuccbly7u', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public String largestOddNumber(String num) {
        for (int i = num.length() - 1; i >= 0; i--) {
            int d = num.charAt(i) - ''0'';
            if (d % 2 != 0) return num.substring(0, i + 1);
        }
        return "";
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.466Z', '2026-11-20T06:28:30.466Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsy007bo76vmpotwyix', 'cmwolljsy0079o76vuccbly7u', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public String largestOddNumber(String num) {
        for (int i = num.length() - 1; i >= 0; i--) {
            if ((num.charAt(i) - ''0'') % 2 != 0) {
                return num.substring(0, i + 1);
            }
        }
        return "";
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.466Z', '2026-11-20T06:28:30.466Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsz007eo76vf5nrdcr2', 'cmwolljsz007do76vo4w1qx8o', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public String longestCommonPrefix(String[] strs) {
        if (strs == null || strs.length == 0) return "";
        String prefix = strs[0];
        for (int i = 1; i < strs.length; i++) {
            while (strs[i].indexOf(prefix) != 0) {
                prefix = prefix.substring(0, prefix.length() - 1);
                if (prefix.isEmpty()) return "";
            }
        }
        return prefix;
    }
}', 'O(S)', 'O(1)', '2026-11-20T06:28:30.467Z', '2026-11-20T06:28:30.467Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljsz007fo76v1bvuzfjp', 'cmwolljsz007do76vo4w1qx8o', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;
public class Solution {
    public String longestCommonPrefix(String[] strs) {
        if (strs == null || strs.length == 0) return "";
        Arrays.sort(strs);
        String s1 = strs[0], s2 = strs[strs.length - 1];
        int idx = 0;
        while (idx < s1.length() && idx < s2.length() && s1.charAt(idx) == s2.charAt(idx)) {
            idx++;
        }
        return s1.substring(0, idx);
    }
}', 'O(N log N * M)', 'O(1)', '2026-11-20T06:28:30.467Z', '2026-11-20T06:28:30.467Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt0007io76vobllxrj3', 'cmwolljt0007ho76vmroaz0mx', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
public class Solution {
    public boolean isIsomorphic(String s, String t) {
        if (s.length() != t.length()) return false;
        HashMap<Character, Character> m1 = new HashMap<>();
        HashMap<Character, Character> m2 = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char c1 = s.charAt(i), c2 = t.charAt(i);
            if (m1.containsKey(c1) && m1.get(c1) != c2) return false;
            if (m2.containsKey(c2) && m2.get(c2) != c1) return false;
            m1.put(c1, c2);
            m2.put(c2, c1);
        }
        return true;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.469Z', '2026-11-20T06:28:30.469Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt0007jo76vri0o5hh5', 'cmwolljt0007ho76vmroaz0mx', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public boolean isIsomorphic(String s, String t) {
        int[] m1 = new int[256], m2 = new int[256];
        for (int i = 0; i < s.length(); i++) {
            if (m1[s.charAt(i)] != m2[t.charAt(i)]) return false;
            m1[s.charAt(i)] = i + 1;
            m2[t.charAt(i)] = i + 1;
        }
        return true;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.469Z', '2026-11-20T06:28:30.469Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt1007mo76vo1ohb6gw', 'cmwolljt1007lo76vahj8cypq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public boolean rotateString(String s, String goal) {
        if (s.length() != goal.length()) return false;
        for (int i = 0; i < s.length(); i++) {
            String rotated = s.substring(i) + s.substring(0, i);
            if (rotated.equals(goal)) return true;
        }
        return false;
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.470Z', '2026-11-20T06:28:30.470Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt3007qo76vkatw43yj', 'cmwolljt3007po76vfz7d106o', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;
public class Solution {
    public boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) return false;
        char[] sArr = s.toCharArray(), tArr = t.toCharArray();
        Arrays.sort(sArr);
        Arrays.sort(tArr);
        return Arrays.equals(sArr, tArr);
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.471Z', '2026-11-20T06:28:30.471Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt3007ro76vas8qnlu2', 'cmwolljt3007po76vfz7d106o', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) return false;
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) {
            counts[s.charAt(i) - ''a'']++;
            counts[t.charAt(i) - ''a'']--;
        }
        for (int c : counts) if (c != 0) return false;
        return true;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.471Z', '2026-11-20T06:28:30.471Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljth008yo76v8h0ogm38', 'cmwolljth008xo76vly927qr3', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isSorted(int[] arr, int n) {
        for (int i = 1; i < n; i++) {
