}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.485Z', '2026-11-20T06:28:30.485Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt4007uo76vcsw9a5cs', 'cmwolljt4007to76v6a4rbyqy', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public String frequencySort(String s) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : s.toCharArray()) counts.put(c, counts.getOrDefault(c, 0) + 1);
        List<Character> list = new ArrayList<>(counts.keySet());
        list.sort((a, b) -> counts.get(b) - counts.get(a));
        StringBuilder sb = new StringBuilder();
        for (char c : list) {
            int freq = counts.get(c);
            for (int i = 0; i < freq; i++) sb.append(c);
        }
        return sb.toString();
    }
}', 'O(N log K)', 'O(N)', '2026-11-20T06:28:30.472Z', '2026-11-20T06:28:30.472Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt4007vo76vdd559nj4', 'cmwolljt4007to76v6a4rbyqy', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public String frequencySort(String s) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : s.toCharArray()) counts.put(c, counts.getOrDefault(c, 0) + 1);
        List<Character>[] buckets = new List[s.length() + 1];
        for (char c : counts.keySet()) {
            int freq = counts.get(c);
            if (buckets[freq] == null) buckets[freq] = new ArrayList<>();
            buckets[freq].add(c);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = buckets.length - 1; i >= 1; i--) {
            if (buckets[i] != null) {
                for (char c : buckets[i]) {
                    for (int j = 0; j < i; j++) sb.append(c);
                }
            }
        }
        return sb.toString();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.472Z', '2026-11-20T06:28:30.472Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt5007yo76v9peh1hdd', 'cmwolljt5007xo76v5478xboa', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    // Demonstration of base condition and stack unwinding
    public static void print1ToN(int i, int n) {
        if (i > n) return;
        System.out.print(i + " ");
        print1ToN(i + 1, n);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.474Z', '2026-11-20T06:28:30.474Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt5007zo76vti7yrb9x', 'cmwolljt5007xo76v5478xboa', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
