}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.474Z', '2026-11-20T06:28:30.474Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt70082o76v0vwae0jx', 'cmwolljt70081o76vk8vlask5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    // Parameterized recursion
    public static void printSum(int i, int sum) {
        if (i < 1) {
            System.out.println(sum);
            return;
        }
        printSum(i - 1, sum + i);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.475Z', '2026-11-20T06:28:30.475Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt70083o76vgtbbowd1', 'cmwolljt70081o76vk8vlask5', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    // Functional recursion
