INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt80086o76vqgi8mitx', 'cmwolljt80085o76v9tbalxbt', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
