INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt80087o76v44jia2cf', 'cmwolljt80085o76v9tbalxbt', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
