INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt9008ao76v6bmyb45u', 'cmwolljt90089o76vk8ij8eta', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
