INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljt9008bo76v3psuadyb', 'cmwolljt90089o76vk8ij8eta', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
