INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljta008eo76v35wnm2aa', 'cmwolljta008do76vq0a5ln7a', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int arraySum(int[] arr, int n) {
        int s = 0;
        for (int x : arr) s += x;
        return s;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.479Z', '2026-11-20T06:28:30.479Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljta008fo76v9qouqrh5', 'cmwolljta008do76vq0a5ln7a', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int arraySum(int[] arr, int n) {
        return solve(0, arr);
    }
    private static int solve(int i, int[] arr) {
        if (i == arr.length) return 0;
        return arr[i] + solve(i + 1, arr);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.479Z', '2026-11-20T06:28:30.479Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtb008io76v6pjhb3hu', 'cmwolljtb008ho76vp2iv2it7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String reverseString(String s) {
        char[] arr = s.toCharArray();
        int left = 0, right = arr.length - 1;
        while (left < right) {
            char t = arr[left]; arr[left] = arr[right]; arr[right] = t;
            left++; right--;
        }
        return new String(arr);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.480Z', '2026-11-20T06:28:30.480Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtb008jo76vkoa8577f', 'cmwolljtb008ho76vp2iv2it7', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static String reverseString(String s) {
        char[] arr = s.toCharArray();
        rev(0, arr.length - 1, arr);
        return new String(arr);
    }
    private static void rev(int l, int r, char[] arr) {
        if (l >= r) return;
        char t = arr[l]; arr[l] = arr[r]; arr[r] = t;
        rev(l + 1, r - 1, arr);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.480Z', '2026-11-20T06:28:30.480Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtc008mo76vibzun4ys', 'cmwolljtc008lo76vhw2kaiug', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isPalindrome(String s) {
        String rev = new StringBuilder(s).reverse().toString();
        return s.equals(rev);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.481Z', '2026-11-20T06:28:30.481Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtc008no76v6raq83va', 'cmwolljtc008lo76vhw2kaiug', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isPalindrome(String s) {
        return check(0, s);
    }
    private static boolean check(int i, String s) {
        if (i >= s.length() / 2) return true;
        if (s.charAt(i) != s.charAt(s.length() - i - 1)) return false;
        return check(i + 1, s);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.481Z', '2026-11-20T06:28:30.481Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljte008qo76vbdc73jrx', 'cmwolljte008po76vvey7bs0k', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }
}', 'O(sqrt(N))', 'O(1)', '2026-11-20T06:28:30.483Z', '2026-11-20T06:28:30.483Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljte008ro76v89reawnt', 'cmwolljte008po76vvey7bs0k', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        return checkPrime(2, n);
    }
    private static boolean checkPrime(int i, int n) {
        if (i * i > n) return true;
        if (n % i == 0) return false;
        return checkPrime(i + 1, n);
    }
}', 'O(sqrt(N))', 'O(sqrt(N))', '2026-11-20T06:28:30.483Z', '2026-11-20T06:28:30.483Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtf008uo76vkmx4mt90', 'cmwolljtf008to76vw2ihh4l8', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void reverseArray(int[] arr) {
        int l = 0, r = arr.length - 1;
        while (l < r) {
            int t = arr[l]; arr[l] = arr[r]; arr[r] = t;
            l++; r--;
        }
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.484Z', '2026-11-20T06:28:30.484Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtf008vo76v66ba51ch', 'cmwolljtf008to76vw2ihh4l8', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void reverseArray(int[] arr) {
        rev(0, arr.length - 1, arr);
    }
    private static void rev(int l, int r, int[] arr) {
        if (l >= r) return;
        int t = arr[l]; arr[l] = arr[r]; arr[r] = t;
        rev(l + 1, r - 1, arr);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.484Z', '2026-11-20T06:28:30.484Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljth008zo76vd4tg1t96', 'cmwolljth008xo76vly927qr3', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isSorted(int[] arr, int n) {
        return check(0, arr, n);
    }
    private static boolean check(int i, int[] arr, int n) {
        if (i >= n - 1) return true;
        if (arr[i] > arr[i + 1]) return false;
        return check(i + 1, arr, n);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.485Z', '2026-11-20T06:28:30.485Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljti0092o76v5eanrz55', 'cmwolljti0091o76vtrtgiycj', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int sumOfDigits(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}', 'O(log10 N)', 'O(1)', '2026-11-20T06:28:30.487Z', '2026-11-20T06:28:30.487Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljti0093o76vt20dcqku', 'cmwolljti0091o76vtrtgiycj', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int sumOfDigits(int n) {
        if (n == 0) return 0;
        return (n % 10) + sumOfDigits(n / 10);
