}', 'O(log10 N)', 'O(log10 N)', '2026-11-20T06:28:30.487Z', '2026-11-20T06:28:30.487Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtj0096o76v4fjtcw3h', 'cmwolljtj0095o76vq0en0kox', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int fib(int n) {
        if (n <= 1) return n;
        return fib(n - 1) + fib(n - 2);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.488Z', '2026-11-20T06:28:30.488Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtj0097o76vjwg00rse', 'cmwolljtj0095o76vq0en0kox', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int fib(int n) {
        if (n <= 1) return n;
        int a = 0, b = 1;
        for (int i = 2; i <= n; i++) {
            int c = a + b;
            a = b;
            b = c;
        }
        return b;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.488Z', '2026-11-20T06:28:30.488Z') ON CONFLICT DO NOTHING;
