INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtm009fo76vxxidaqix', 'cmwolljtm009do76vc0rv8jhy', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
