INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljto009io76vwba5l7xm', 'cmwolljto009ho76vghz68x7q', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int secondLargest(int[] arr) {
        Arrays.sort(arr);
        int n = arr.length;
        for (int i = n - 2; i >= 0; i--) {
            if (arr[i] != arr[n - 1]) {
                return arr[i];
            }
        }
        return -1;
    }
}', 'O(N log N)', 'O(1)', '2026-11-20T06:28:30.492Z', '2026-11-20T06:28:30.492Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljto009jo76ve7hpbjxh', 'cmwolljto009ho76vghz68x7q', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int secondLargest(int[] arr) {
        int largest = -1;
        int secondLargest = -1;
        for (int x : arr) {
            if (x > largest) {
                secondLargest = largest;
                largest = x;
            } else if (x > secondLargest && x != largest) {
                secondLargest = x;
            }
        }
        return secondLargest;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.492Z', '2026-11-20T06:28:30.492Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtp009mo76vfas03mgc', 'cmwolljtp009lo76vnwn3q5fc', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findMaxConsecutiveOnes(int[] nums) {
        int max = 0;
        for (int i = 0; i < nums.length; i++) {
            int current = 0;
            for (int j = i; j < nums.length; j++) {
                if (nums[j] == 1) current++;
                else break;
            }
            max = Math.max(max, current);
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.493Z', '2026-11-20T06:28:30.493Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtp009no76vdw0o3t0e', 'cmwolljtp009lo76vnwn3q5fc', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findMaxConsecutiveOnes(int[] nums) {
        int maxCount = 0;
        int count = 0;
        for (int num : nums) {
            if (num == 1) {
                count++;
                maxCount = Math.max(maxCount, count);
            } else {
                count = 0;
            }
        }
        return maxCount;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.493Z', '2026-11-20T06:28:30.493Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtq009qo76vlv8e8pjj', 'cmwolljtq009po76v8o534rh7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void rotate(int[] arr) {
        int[] temp = new int[arr.length];
        for (int i = 1; i < arr.length; i++) {
            temp[i - 1] = arr[i];
        }
        temp[arr.length - 1] = arr[0];
        System.arraycopy(temp, 0, arr, 0, arr.length);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.495Z', '2026-11-20T06:28:30.495Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtq009ro76vtoq6153e', 'cmwolljtq009po76v8o534rh7', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void rotate(int[] arr) {
        int temp = arr[0];
        for (int i = 1; i < arr.length; i++) {
            arr[i - 1] = arr[i];
        }
        arr[arr.length - 1] = temp;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.495Z', '2026-11-20T06:28:30.495Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtr009uo76v7ke6tn3y', 'cmwolljtr009to76v010htmw7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void rotate(int[] nums, int k) {
        int n = nums.length;
        k %= n;
        int[] temp = new int[k];
        for (int i = 0; i < k; i++) temp[i] = nums[i];
        for (int i = k; i < n; i++) nums[i - k] = nums[i];
        for (int i = 0; i < k; i++) nums[n - k + i] = temp[i];
    }
}', 'O(N)', 'O(K)', '2026-11-20T06:28:30.496Z', '2026-11-20T06:28:30.496Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtr009vo76v03lkdwen', 'cmwolljtr009to76v010htmw7', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void rotate(int[] nums, int k) {
        int n = nums.length;
        k %= n;
        reverse(nums, 0, k - 1);
        reverse(nums, k, n - 1);
        reverse(nums, 0, n - 1);
    }

    private static void reverse(int[] nums, int start, int end) {
        while (start < end) {
            int temp = nums[start];
            nums[start++] = nums[end];
            nums[end--] = temp;
        }
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.496Z', '2026-11-20T06:28:30.496Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljts009yo76vcce7qkg4', 'cmwolljts009xo76vjvhord1v', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static void moveZeroes(int[] nums) {
        ArrayList<Integer> temp = new ArrayList<>();
        for (int num : nums) {
            if (num != 0) temp.add(num);
        }
        for (int i = 0; i < temp.size(); i++) {
            nums[i] = temp.get(i);
        }
        for (int i = temp.size(); i < nums.length; i++) {
            nums[i] = 0;
        }
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.497Z', '2026-11-20T06:28:30.497Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljts009zo76vqog6xews', 'cmwolljts009xo76vjvhord1v', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void moveZeroes(int[] nums) {
        int j = -1;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 0) {
                j = i;
                break;
            }
        }
        if (j == -1) return;
        for (int i = j + 1; i < nums.length; i++) {
            if (nums[i] != 0) {
                int temp = nums[i];
                nums[i] = nums[j];
                nums[j] = temp;
                j++;
            }
        }
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.497Z', '2026-11-20T06:28:30.497Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtu00a2o76v95p0ahkn', 'cmwolljtu00a1o76vy0ttloda', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;

public class Solution {
    public static int removeDuplicates(int[] nums) {
        HashSet<Integer> set = new HashSet<>();
        for (int num : nums) set.add(num);
        int index = 0;
        for (int num : set) nums[index++] = num;
        return set.size();
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.498Z', '2026-11-20T06:28:30.498Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtu00a3o76v8rpd0nsi', 'cmwolljtu00a1o76vy0ttloda', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int removeDuplicates(int[] nums) {
        if (nums.length == 0) return 0;
        int i = 0;
        for (int j = 1; j < nums.length; j++) {
            if (nums[j] != nums[i]) {
                nums[++i] = nums[j];
            }
        }
        return i + 1;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.498Z', '2026-11-20T06:28:30.498Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtv00a6o76vgnehteud', 'cmwolljtv00a5o76vegkiaahq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int missingNumber(int[] nums) {
        int n = nums.length;
        for (int i = 0; i <= n; i++) {
            boolean found = false;
            for (int num : nums) {
                if (num == i) {
                    found = true;
                    break;
                }
            }
            if (!found) return i;
        }
        return -1;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.499Z', '2026-11-20T06:28:30.499Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtv00a7o76v55u3km2q', 'cmwolljtv00a5o76vegkiaahq', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int missingNumber(int[] nums) {
        int n = nums.length;
        int expectedSum = n * (n + 1) / 2;
        int actualSum = 0;
        for (int num : nums) actualSum += num;
        return expectedSum - actualSum;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.499Z', '2026-11-20T06:28:30.499Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtw00aao76vcui6t23n', 'cmwolljtw00a9o76v8vsih342', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<Integer> findUnion(int[] a, int[] b) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int x : a) set.add(x);
        for (int x : b) set.add(x);
        return new ArrayList<>(set);
    }
}', 'O((M+N) log(M+N))', 'O(M+N)', '2026-11-20T06:28:30.501Z', '2026-11-20T06:28:30.501Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtw00abo76vhsj09hoa', 'cmwolljtw00a9o76v8vsih342', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static ArrayList<Integer> findUnion(int[] a, int[] b) {
        ArrayList<Integer> union = new ArrayList<>();
        int i = 0, j = 0;
        int n = a.length, m = b.length;
        while (i < n && j < m) {
            if (a[i] <= b[j]) {
                if (union.isEmpty() || union.get(union.size() - 1) != a[i]) union.add(a[i]);
                i++;
            } else {
                if (union.isEmpty() || union.get(union.size() - 1) != b[j]) union.add(b[j]);
                j++;
            }
        }
        while (i < n) {
            if (union.isEmpty() || union.get(union.size() - 1) != a[i]) union.add(a[i]);
            i++;
        }
        while (j < m) {
            if (union.isEmpty() || union.get(union.size() - 1) != b[j]) union.add(b[j]);
            j++;
        }
        return union;
    }
}', 'O(N + M)', 'O(N + M)', '2026-11-20T06:28:30.501Z', '2026-11-20T06:28:30.501Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtx00aeo76vx1xnhes3', 'cmwolljtx00ado76vtqgi0vfb', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static ArrayList<Integer> intersection(int[] a, int[] b) {
        ArrayList<Integer> res = new ArrayList<>();
        int[] visited = new int[b.length];
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < b.length; j++) {
                if (a[i] == b[j] && visited[j] == 0) {
                    res.add(a[i]);
                    visited[j] = 1;
                    break;
                }
                if (b[j] > a[i]) break;
            }
        }
        return res;
    }
}', 'O(N * M)', 'O(M)', '2026-11-20T06:28:30.502Z', '2026-11-20T06:28:30.502Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtx00afo76vehqd21w0', 'cmwolljtx00ado76vtqgi0vfb', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static ArrayList<Integer> intersection(int[] a, int[] b) {
        ArrayList<Integer> res = new ArrayList<>();
        int i = 0, j = 0;
        while (i < a.length && j < b.length) {
            if (a[i] < b[j]) {
                i++;
            } else if (b[j] < a[i]) {
                j++;
            } else {
                res.add(a[i]);
                i++;
                j++;
            }
        }
        return res;
    }
}', 'O(N + M)', 'O(1)', '2026-11-20T06:28:30.502Z', '2026-11-20T06:28:30.502Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljtz00aio76v2qft3y3d', 'cmwolljtz00aho76vyu8v89hd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int majorityElement(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (nums[j] == nums[i]) count++;
            }
            if (count > n / 2) return nums[i];
        }
        return -1;
    }
