INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollju300ayo76vhzr4d2qo', 'cmwollju300axo76v7imndenh', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long nCr(int n, int r) {
        long res = 1;
        for (int i = 0; i < r; i++) {
            res = res * (n - i);
            res = res / (i + 1);
        }
        return res;
    }

    public static int pascalElement(int r, int c) {
        return (int) nCr(r - 1, c - 1);
    }
}', 'O(C)', 'O(1)', '2026-11-20T06:28:30.508Z', '2026-11-20T06:28:30.508Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollju300azo76vl2rfte4l', 'cmwollju300axo76v7imndenh', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long pascalElement(int r, int c) {
        long res = 1;
        for (int i = 0; i < c - 1; i++) {
            res = res * (r - 1 - i);
            res = res / (i + 1);
        }
        return res;
