}', 'O(C)', 'O(1)', '2026-11-20T06:28:30.508Z', '2026-11-20T06:28:30.508Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollju400b2o76v7dqpg6yv', 'cmwollju400b1o76vyifbp4g6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        for (int c = 0; c <= rowIndex; c++) {
            long val = 1;
            for (int i = 0; i < c; i++) {
                val = val * (rowIndex - i) / (i + 1);
            }
            row.add((int) val);
        }
        return row;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.509Z', '2026-11-20T06:28:30.509Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollju400b3o76v2exi6y64', 'cmwollju400b1o76vyifbp4g6', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

