}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.517Z', '2026-11-20T06:28:30.517Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuc00bzo76v8hlf8aws', 'cmwolljuc00bxo76vce5v9q16', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int maxSubArray(int[] nums) {
