}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.518Z', '2026-11-20T06:28:30.518Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljue00c6o76vymvxjngf', 'cmwolljue00c5o76vyf23hitl', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<Integer> majorityElement(int[] nums) {
        List<Integer> res = new ArrayList<>();
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            if (res.contains(nums[i])) continue;
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (nums[j] == nums[i]) count++;
            }
            if (count > n / 3) res.add(nums[i]);
        }
        return res;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.519Z', '2026-11-20T06:28:30.519Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljue00c7o76ve8hu7onp', 'cmwolljue00c5o76vyf23hitl', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<Integer> majorityElement(int[] nums) {
        int count1 = 0, count2 = 0;
        int candidate1 = 0, candidate2 = 1;
        for (int num : nums) {
            if (num == candidate1) count1++;
            else if (num == candidate2) count2++;
            else if (count1 == 0) { candidate1 = num; count1 = 1; }
            else if (count2 == 0) { candidate2 = num; count2 = 1; }
            else { count1--; count2--; }
        }
        count1 = 0; count2 = 0;
        for (int num : nums) {
            if (num == candidate1) count1++;
            else if (num == candidate2) count2++;
        }
        List<Integer> res = new ArrayList<>();
        int n = nums.length;
        if (count1 > n / 3) res.add(candidate1);
        if (count2 > n / 3) res.add(candidate2);
        return res;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.519Z', '2026-11-20T06:28:30.519Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljug00cao76varrn94vy', 'cmwolljug00c9o76v5fpkb3v0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] findTwoElement(int[] arr) {
        int n = arr.length;
        int repeating = -1, missing = -1;
        for (int i = 1; i <= n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (arr[j] == i) count++;
            }
            if (count == 2) repeating = i;
            else if (count == 0) missing = i;
        }
        return new int[]{repeating, missing};
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.520Z', '2026-11-20T06:28:30.520Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljug00cbo76vxnxw8cyl', 'cmwolljug00c9o76v5fpkb3v0', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int[] findTwoElement(int[] arr) {
        long n = arr.length;
        long SN = n * (n + 1) / 2;
        long S2N = n * (n + 1) * (2 * n + 1) / 6;
        long S = 0, S2 = 0;
        for (int x : arr) {
            S += x;
            S2 += (long) x * x;
        }
        long val1 = S - SN; // x - y
        long val2 = S2 - S2N;
        val2 = val2 / val1; // x + y
        long x = (val1 + val2) / 2;
        long y = x - val1;
        return new int[]{(int) x, (int) y};
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.520Z', '2026-11-20T06:28:30.520Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuh00cfo76vp07beh4f', 'cmwolljuh00cdo76vvfck9stb', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long inversionCount(long[] arr) {
        return mergeSort(arr, 0, arr.length - 1);
    }

    private static long mergeSort(long[] arr, int low, int high) {
        long count = 0;
        if (low < high) {
            int mid = (low + high) / 2;
            count += mergeSort(arr, low, mid);
            count += mergeSort(arr, mid + 1, high);
            count += merge(arr, low, mid, high);
        }
        return count;
    }

    private static long merge(long[] arr, int low, int mid, int high) {
        long[] temp = new long[high - low + 1];
        int left = low, right = mid + 1, k = 0;
        long count = 0;
        while (left <= mid && right <= high) {
            if (arr[left] <= arr[right]) {
                temp[k++] = arr[left++];
            } else {
                temp[k++] = arr[right++];
                count += (mid - left + 1);
            }
        }
        while (left <= mid) temp[k++] = arr[left++];
        while (right <= high) temp[k++] = arr[right++];
        System.arraycopy(temp, 0, arr, low, temp.length);
        return count;
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.521Z', '2026-11-20T06:28:30.521Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljui00cio76vjfl3vfr0', 'cmwolljui00cho76vd54yn5le', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int reversePairs(int[] nums) {
        int count = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if ((long) nums[i] > 2L * nums[j]) count++;
            }
        }
        return count;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.522Z', '2026-11-20T06:28:30.522Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuw00e2o76v2kvtbk0r', 'cmwolljuw00e1o76ve4dqlm2j', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] searchRange(int[] nums, int target) {
        int first = -1, last = -1;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == target) {
                if (first == -1) first = i;
                last = i;
            }
        }
        return new int[]{first, last};
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.537Z', '2026-11-20T06:28:30.537Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljui00cjo76vb4rmb4ac', 'cmwolljui00cho76vd54yn5le', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int reversePairs(int[] nums) {
        return mergeSort(nums, 0, nums.length - 1);
    }

    private static int mergeSort(int[] nums, int low, int high) {
        if (low >= high) return 0;
        int mid = (low + high) / 2;
        int count = mergeSort(nums, low, mid) + mergeSort(nums, mid + 1, high);
        int j = mid + 1;
        for (int i = low; i <= mid; i++) {
            while (j <= high && (long) nums[i] > 2L * nums[j]) j++;
            count += (j - (mid + 1));
        }
        merge(nums, low, mid, high);
        return count;
    }

    private static void merge(int[] nums, int low, int mid, int high) {
        int[] temp = new int[high - low + 1];
        int left = low, right = mid + 1, k = 0;
        while (left <= mid && right <= high) {
            if (nums[left] <= nums[right]) temp[k++] = nums[left++];
            else temp[k++] = nums[right++];
        }
        while (left <= mid) temp[k++] = nums[left++];
        while (right <= high) temp[k++] = nums[right++];
        System.arraycopy(temp, 0, nums, low, temp.length);
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.522Z', '2026-11-20T06:28:30.522Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuj00cmo76vo453l9k1', 'cmwolljuj00clo76vyl5nq7wr', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int maxProduct(int[] nums) {
        int max = nums[0];
        for (int i = 0; i < nums.length; i++) {
            int prod = 1;
            for (int j = i; j < nums.length; j++) {
                prod *= nums[j];
                max = Math.max(max, prod);
            }
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.523Z', '2026-11-20T06:28:30.523Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuj00cno76v3i18dscq', 'cmwolljuj00clo76vyl5nq7wr', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int maxProduct(int[] nums) {
        int max = nums[0];
        int prefix = 1, suffix = 1;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            if (prefix == 0) prefix = 1;
            if (suffix == 0) suffix = 1;
            prefix *= nums[i];
            suffix *= nums[n - 1 - i];
            max = Math.max(max, Math.max(prefix, suffix));
        }
        return max;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.523Z', '2026-11-20T06:28:30.523Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuk00cqo76vbdf42am7', 'cmwolljuk00cpo76vwh7cka25', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static void merge(long[] a, long[] b) {
        int n = a.length, m = b.length;
        long[] c = new long[n + m];
        System.arraycopy(a, 0, c, 0, n);
        System.arraycopy(b, 0, c, n, m);
        Arrays.sort(c);
        System.arraycopy(c, 0, a, 0, n);
        System.arraycopy(c, n, b, 0, m);
    }
}', 'O((N+M) log(N+M))', 'O(N+M)', '2026-11-20T06:28:30.524Z', '2026-11-20T06:28:30.524Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuk00cro76vbace7xjx', 'cmwolljuk00cpo76vwh7cka25', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;

public class Solution {
    public static void merge(long[] a, long[] b) {
        int n = a.length, m = b.length;
        int left = n - 1, right = 0;
        while (left >= 0 && right < m) {
            if (a[left] > b[right]) {
                long temp = a[left];
                a[left] = b[right];
                b[right] = temp;
                left--;
                right++;
            } else {
                break;
            }
        }
        Arrays.sort(a);
        Arrays.sort(b);
    }
}', 'O(min(N, M) + N log N + M log M)', 'O(1)', '2026-11-20T06:28:30.524Z', '2026-11-20T06:28:30.524Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljul00cuo76vaj07stly', 'cmwolljul00cto76v8n5jgesv', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;

public class Solution {
    public static void frequencyCount(int[] arr) {
        // Brute force: count frequency using nested loops
        int n = arr.length;
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            int count = 1;
            for (int j = i + 1; j < n; j++) {
                if (arr[i] == arr[j]) {
                    visited[j] = true;
                    count++;
                }
            }
            System.out.println(arr[i] + " occurs " + count + " times");
        }
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.526Z', '2026-11-20T06:28:30.526Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljul00cvo76vmt4hq1ed', 'cmwolljul00cto76v8n5jgesv', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static void frequencyCount(int[] arr) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : arr) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            System.out.println(entry.getKey() + " occurs " + entry.getValue() + " times");
        }
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.526Z', '2026-11-20T06:28:30.526Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljum00cyo76vu9ye9956', 'cmwolljum00cxo76vbgd6kx5f', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int longestConsecutive(int[] nums) {
        if (nums.length == 0) return 0;
        Arrays.sort(nums);
        int longest = 1, current = 1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] == nums[i - 1]) continue;
            if (nums[i] == nums[i - 1] + 1) {
                current++;
            } else {
                longest = Math.max(longest, current);
                current = 1;
            }
        }
        return Math.max(longest, current);
    }
}', 'O(N log N)', 'O(1)', '2026-11-20T06:28:30.527Z', '2026-11-20T06:28:30.527Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljum00czo76vsabq1dim', 'cmwolljum00cxo76vbgd6kx5f', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) set.add(num);
        int longest = 0;
        for (int num : set) {
            if (!set.contains(num - 1)) {
                int currentNum = num;
                int currentStreak = 1;
                while (set.contains(currentNum + 1)) {
                    currentNum++;
                    currentStreak++;
                }
                longest = Math.max(longest, currentStreak);
            }
        }
        return longest;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.527Z', '2026-11-20T06:28:30.527Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljun00d3o76vitg56y8r', 'cmwolljun00d1o76vfebefnze', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int longestSubarray(int[] nums, int k) {
        Map<Long, Integer> map = new HashMap<>();
        long sum = 0;
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            if (sum == k) {
                maxLen = i + 1;
            }
            long rem = sum - k;
            if (map.containsKey(rem)) {
                maxLen = Math.max(maxLen, i - map.get(rem));
            }
            if (!map.containsKey(sum)) {
                map.put(sum, i);
            }
        }
        return maxLen;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.528Z', '2026-11-20T06:28:30.528Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuo00d6o76v5cs1797i', 'cmwolljuo00d5o76ve7cw4vl5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int maxLen(int[] arr, int n) {
        int max = 0;
        for (int i = 0; i < n; i++) {
            int sum = 0;
            for (int j = i; j < n; j++) {
                sum += arr[j];
                if (sum == 0) {
                    max = Math.max(max, j - i + 1);
                }
            }
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.529Z', '2026-11-20T06:28:30.529Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv200euo76vgq7caohk', 'cmwolljv200eto76vzqkq3vx3', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long floorSqrt(long n) {
        long ans = 1;
        for (long i = 1; i * i <= n; i++) {
            ans = i;
        }
        return ans;
    }
}', 'O(sqrt(N))', 'O(1)', '2026-11-20T06:28:30.543Z', '2026-11-20T06:28:30.543Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuo00d7o76vyi5jwhgl', 'cmwolljuo00d5o76ve7cw4vl5', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;

public class Solution {
    public static int maxLen(int[] arr, int n) {
        HashMap<Integer, Integer> map = new HashMap<>();
        int max = 0, sum = 0;
        for (int i = 0; i < n; i++) {
            sum += arr[i];
            if (sum == 0) {
                max = i + 1;
            } else if (map.containsKey(sum)) {
                max = Math.max(max, i - map.get(sum));
            } else {
                map.put(sum, i);
            }
        }
        return max;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.529Z', '2026-11-20T06:28:30.529Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljup00dao76vrk3f6oxl', 'cmwolljup00d9o76vo0if8bev', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int subarraySum(int[] nums, int k) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int sum = 0;
            for (int j = i; j < nums.length; j++) {
                sum += nums[j];
                if (sum == k) count++;
            }
        }
        return count;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.530Z', '2026-11-20T06:28:30.530Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljup00dbo76vjfkjc3wa', 'cmwolljup00d9o76vo0if8bev', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;

public class Solution {
    public static int subarraySum(int[] nums, int k) {
        HashMap<Integer, Integer> map = new HashMap<>();
        map.put(0, 1);
        int count = 0, sum = 0;
        for (int num : nums) {
            sum += num;
            if (map.containsKey(sum - k)) {
                count += map.get(sum - k);
            }
            map.put(sum, map.getOrDefault(sum, 0) + 1);
        }
        return count;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.530Z', '2026-11-20T06:28:30.530Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuq00deo76vh3dgdpu8', 'cmwolljuq00ddo76v286lwnr2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int solve(int[] A, int B) {
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            int xor = 0;
            for (int j = i; j < A.length; j++) {
                xor ^= A[j];
                if (xor == B) count++;
            }
        }
        return count;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.531Z', '2026-11-20T06:28:30.531Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuq00dfo76vu8tlrsjt', 'cmwolljuq00ddo76v286lwnr2', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;

public class Solution {
    public static int solve(int[] A, int B) {
        HashMap<Integer, Integer> map = new HashMap<>();
        int xr = 0, count = 0;
        map.put(0, 1);
        for (int x : A) {
            xr ^= x;
            int target = xr ^ B;
            if (map.containsKey(target)) {
                count += map.get(target);
            }
            map.put(xr, map.getOrDefault(xr, 0) + 1);
        }
        return count;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.531Z', '2026-11-20T06:28:30.531Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljus00dio76v7zzu73c7', 'cmwolljus00dho76v2dg0yppw', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int search(int[] nums, int target) {
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == target) return i;
        }
        return -1;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.532Z', '2026-11-20T06:28:30.532Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljus00djo76voc00s05m', 'cmwolljus00dho76v2dg0yppw', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int search(int[] nums, int target) {
        int low = 0, high = nums.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) return mid;
            else if (nums[mid] < target) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.532Z', '2026-11-20T06:28:30.532Z') ON CONFLICT DO NOTHING;
