INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuv00dyo76vorax15x0', 'cmwolljuv00dxo76vxqnt5oap', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] getFloorAndCeil(int[] a, int n, int x) {
        int floor = -1, ceil = -1;
        for (int i = 0; i < n; i++) {
            if (a[i] <= x) floor = a[i];
            if (a[i] >= x && ceil == -1) ceil = a[i];
        }
        return new int[]{floor, ceil};
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.536Z', '2026-11-20T06:28:30.536Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuv00dzo76vxrtuzgj6', 'cmwolljuv00dxo76vxqnt5oap', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int[] getFloorAndCeil(int[] a, int n, int x) {
        int low = 0, high = n - 1;
        int floor = -1, ceil = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (a[mid] <= x) {
                floor = a[mid];
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        low = 0; high = n - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (a[mid] >= x) {
                ceil = a[mid];
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return new int[]{floor, ceil};
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.536Z', '2026-11-20T06:28:30.536Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwm00l6o76vwlzbqaxn', 'cmwolljwm00l5o76v7xv2922h', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node insertHead(Node head, int val) {
        Node newNode = new Node(val);
        newNode.next = head;
        return newNode;
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.599Z', '2026-11-20T06:28:30.599Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuw00e3o76vw30p570m', 'cmwolljuw00e1o76ve4dqlm2j', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int[] searchRange(int[] nums, int target) {
        return new int[]{findBound(nums, target, true), findBound(nums, target, false)};
    }

    private static int findBound(int[] nums, int target, boolean isFirst) {
        int low = 0, high = nums.length - 1, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) {
                ans = mid;
                if (isFirst) high = mid - 1;
                else low = mid + 1;
            } else if (nums[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.537Z', '2026-11-20T06:28:30.537Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljux00e6o76vq84tanzy', 'cmwolljux00e5o76vdpyx44fc', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int search(int[] nums, int target) {
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == target) return i;
        }
        return -1;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.537Z', '2026-11-20T06:28:30.537Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljux00e7o76v22uqmkx4', 'cmwolljux00e5o76vdpyx44fc', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int search(int[] nums, int target) {
        int low = 0, high = nums.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) return mid;
            if (nums[low] <= nums[mid]) {
                if (nums[low] <= target && target < nums[mid]) high = mid - 1;
                else low = mid + 1;
            } else {
                if (nums[mid] < target && target <= nums[high]) low = mid + 1;
                else high = mid - 1;
            }
        }
        return -1;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.537Z', '2026-11-20T06:28:30.537Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuy00eao76vbxgwd724', 'cmwolljuy00e9o76v7mpmmqof', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean search(int[] nums, int target) {
        for (int num : nums) {
            if (num == target) return true;
        }
        return false;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.538Z', '2026-11-20T06:28:30.538Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuy00ebo76vsrxvnh10', 'cmwolljuy00e9o76v7mpmmqof', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean search(int[] nums, int target) {
        int low = 0, high = nums.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) return true;
            if (nums[low] == nums[mid] && nums[mid] == nums[high]) {
                low++;
                high--;
                continue;
            }
            if (nums[low] <= nums[mid]) {
                if (nums[low] <= target && target < nums[mid]) high = mid - 1;
                else low = mid + 1;
            } else {
                if (nums[mid] < target && target <= nums[high]) low = mid + 1;
                else high = mid - 1;
            }
        }
        return false;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.538Z', '2026-11-20T06:28:30.538Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuz00eeo76v8hys7b86', 'cmwolljuz00edo76vkvpr9m9u', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findMin(int[] nums) {
        int min = nums[0];
        for (int num : nums) min = Math.min(min, num);
        return min;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.539Z', '2026-11-20T06:28:30.539Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuz00efo76vg7x8t77u', 'cmwolljuz00edo76vkvpr9m9u', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findMin(int[] nums) {
        int low = 0, high = nums.length - 1;
        int ans = Integer.MAX_VALUE;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[low] <= nums[high]) {
                ans = Math.min(ans, nums[low]);
                break;
            }
            if (nums[low] <= nums[mid]) {
                ans = Math.min(ans, nums[low]);
                low = mid + 1;
            } else {
                ans = Math.min(ans, nums[mid]);
                high = mid - 1;
            }
        }
        return ans;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.539Z', '2026-11-20T06:28:30.539Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuz00eio76vbetjzqvd', 'cmwolljuz00eho76vre5th2qg', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findKRotation(int[] arr, int n) {
        int min = arr[0], minIdx = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] < min) {
                min = arr[i];
                minIdx = i;
            }
        }
        return minIdx;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.540Z', '2026-11-20T06:28:30.540Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljuz00ejo76v3q80hdn0', 'cmwolljuz00eho76vre5th2qg', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findKRotation(int[] arr, int n) {
        int low = 0, high = n - 1;
        int ans = Integer.MAX_VALUE, index = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[low] <= arr[high]) {
                if (arr[low] < ans) {
                    ans = arr[low];
                    index = low;
                }
                break;
            }
            if (arr[low] <= arr[mid]) {
                if (arr[low] < ans) {
                    ans = arr[low];
                    index = low;
                }
                low = mid + 1;
            } else {
                if (arr[mid] < ans) {
                    ans = arr[mid];
                    index = mid;
                }
                high = mid - 1;
            }
        }
        return index;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.540Z', '2026-11-20T06:28:30.540Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv000emo76v2vyzyjlr', 'cmwolljv000elo76v2ak1q0ln', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int singleNonDuplicate(int[] nums) {
        int xor = 0;
        for (int num : nums) xor ^= num;
        return xor;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.541Z', '2026-11-20T06:28:30.541Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv000eno76vll7c11ql', 'cmwolljv000elo76v2ak1q0ln', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int singleNonDuplicate(int[] nums) {
        int low = 0, high = nums.length - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (mid % 2 == 1) mid--;
            if (nums[mid] == nums[mid + 1]) {
                low = mid + 2;
            } else {
                high = mid;
            }
        }
        return nums[low];
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.541Z', '2026-11-20T06:28:30.541Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv100eqo76vo5m41fid', 'cmwolljv100epo76v2ds9rt8x', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int count(int[] arr, int n, int x) {
        int c = 0;
        for (int num : arr) {
            if (num == x) c++;
        }
        return c;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.542Z', '2026-11-20T06:28:30.542Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv100ero76vhn6qf5x2', 'cmwolljv100epo76v2ds9rt8x', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int count(int[] arr, int n, int x) {
        int first = findFirst(arr, n, x);
        if (first == -1) return 0;
        int last = findLast(arr, n, x);
        return last - first + 1;
    }

    private static int findFirst(int[] arr, int n, int x) {
        int low = 0, high = n - 1, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == x) { ans = mid; high = mid - 1; }
            else if (arr[mid] < x) low = mid + 1;
            else high = mid - 1;
        }
        return ans;
    }

    private static int findLast(int[] arr, int n, int x) {
        int low = 0, high = n - 1, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == x) { ans = mid; low = mid + 1; }
            else if (arr[mid] < x) low = mid + 1;
            else high = mid - 1;
        }
        return ans;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.542Z', '2026-11-20T06:28:30.542Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv200evo76veodku7y7', 'cmwolljv200eto76vzqkq3vx3', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long floorSqrt(long n) {
        long low = 1, high = n, ans = 0;
        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (mid * mid <= n) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.543Z', '2026-11-20T06:28:30.543Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv300eyo76vokqtsyei', 'cmwolljv300exo76vnxqt0tac', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int NthRoot(int n, int m) {
        for (int i = 1; i <= m; i++) {
            long val = 1;
            for (int j = 0; j < n; j++) {
                val *= i;
                if (val > m) break;
            }
            if (val == m) return i;
            if (val > m) break;
        }
        return -1;
    }
}', 'O(M)', 'O(1)', '2026-11-20T06:28:30.543Z', '2026-11-20T06:28:30.543Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv300ezo76v49635cbn', 'cmwolljv300exo76vnxqt0tac', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int NthRoot(int n, int m) {
        int low = 1, high = m;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int midN = check(mid, n, m);
            if (midN == 1) return mid;
            else if (midN == 0) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }

    private static int check(int mid, int n, int m) {
        long ans = 1;
        for (int i = 1; i <= n; i++) {
            ans *= mid;
            if (ans > m) return 2;
        }
        if (ans == m) return 1;
        return 0;
    }
}', 'O(N log M)', 'O(1)', '2026-11-20T06:28:30.543Z', '2026-11-20T06:28:30.543Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv400f2o76veai5ogjn', 'cmwolljv400f1o76vbtc9w4px', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int smallestDivisor(int[] nums, int threshold) {
        int max = 0;
        for (int x : nums) max = Math.max(max, x);
        for (int d = 1; d <= max; d++) {
            int sum = 0;
            for (int x : nums) sum += (x + d - 1) / d;
            if (sum <= threshold) return d;
        }
        return max;
    }
}', 'O(max * N)', 'O(1)', '2026-11-20T06:28:30.544Z', '2026-11-20T06:28:30.544Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv400f3o76vdjvy50kl', 'cmwolljv400f1o76vbtc9w4px', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int smallestDivisor(int[] nums, int threshold) {
        int low = 1, high = 0;
        for (int x : nums) high = Math.max(high, x);
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int sum = 0;
            for (int x : nums) sum += (x + mid - 1) / mid;
            if (sum <= threshold) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}', 'O(N log(max))', 'O(1)', '2026-11-20T06:28:30.544Z', '2026-11-20T06:28:30.544Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv500f6o76vadmj14ni', 'cmwolljv500f5o76v8um8qzhy', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int minEatingSpeed(int[] piles, int h) {
        int max = 0;
        for (int p : piles) max = Math.max(max, p);
        for (int speed = 1; speed <= max; speed++) {
            long hours = 0;
            for (int p : piles) hours += (p + speed - 1) / speed;
            if (hours <= h) return speed;
        }
        return max;
    }
}', 'O(max * N)', 'O(1)', '2026-11-20T06:28:30.545Z', '2026-11-20T06:28:30.545Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv500f7o76vs5khp7go', 'cmwolljv500f5o76v8um8qzhy', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int minEatingSpeed(int[] piles, int h) {
        int low = 1, high = 0;
        for (int p : piles) high = Math.max(high, p);
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            long hours = 0;
            for (int p : piles) hours += (p + mid - 1) / mid;
            if (hours <= h) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}', 'O(N log(max))', 'O(1)', '2026-11-20T06:28:30.545Z', '2026-11-20T06:28:30.545Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv600fao76vhn6uwlc8', 'cmwolljv600f9o76vntkssyo2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) return -1;
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        for (int val : bloomDay) {
            min = Math.min(min, val);
            max = Math.max(max, val);
        }
        for (int d = min; d <= max; d++) {
            if (canMake(bloomDay, m, k, d)) return d;
        }
        return -1;
    }

    private static boolean canMake(int[] bloomDay, int m, int k, int day) {
        int count = 0, bouquets = 0;
        for (int b : bloomDay) {
            if (b <= day) {
                count++;
                if (count == k) {
                    bouquets++;
                    count = 0;
                }
            } else {
                count = 0;
            }
        }
        return bouquets >= m;
    }
}', 'O((max - min) * N)', 'O(1)', '2026-11-20T06:28:30.546Z', '2026-11-20T06:28:30.546Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvi00gyo76vqfgho15n', 'cmwolljvi00gxo76vuumo5d8c', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int findMedian(int[][] matrix) {
        List<Integer> list = new ArrayList<>();
        for (int[] row : matrix) {
            for (int val : row) list.add(val);
        }
        Collections.sort(list);
        return list.get(list.size() / 2);
    }
}', 'O(M * N log(M * N))', 'O(M * N)', '2026-11-20T06:28:30.559Z', '2026-11-20T06:28:30.559Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv600fbo76v72rsuo6m', 'cmwolljv600f9o76vntkssyo2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) return -1;
        int low = Integer.MAX_VALUE, high = Integer.MIN_VALUE;
        for (int val : bloomDay) {
            low = Math.min(low, val);
            high = Math.max(high, val);
        }
        int ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canMake(bloomDay, m, k, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private static boolean canMake(int[] bloomDay, int m, int k, int day) {
        int count = 0, bouquets = 0;
        for (int b : bloomDay) {
            if (b <= day) {
                count++;
                if (count == k) {
                    bouquets++;
                    count = 0;
                }
            } else {
                count = 0;
            }
        }
        return bouquets >= m;
    }
}', 'O(N log(max - min))', 'O(1)', '2026-11-20T06:28:30.546Z', '2026-11-20T06:28:30.546Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv700feo76vrou2q88d', 'cmwolljv700fdo76vi1o57l1v', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int shipWithinDays(int[] weights, int days) {
        int max = 0, sum = 0;
        for (int w : weights) {
            max = Math.max(max, w);
            sum += w;
        }
        for (int cap = max; cap <= sum; cap++) {
            if (daysNeeded(weights, cap) <= days) return cap;
        }
        return sum;
    }

    private static int daysNeeded(int[] weights, int cap) {
        int d = 1, current = 0;
        for (int w : weights) {
            if (current + w > cap) {
                d++;
                current = w;
            } else {
                current += w;
            }
        }
        return d;
    }
}', 'O((sum - max) * N)', 'O(1)', '2026-11-20T06:28:30.547Z', '2026-11-20T06:28:30.547Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwm00l7o76vcl6j225v', 'cmwolljwm00l5o76v7xv2922h', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
