INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv700ffo76v6d0xlhoa', 'cmwolljv700fdo76vi1o57l1v', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
