INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv700fio76van7m492p', 'cmwolljv700fho76vu5t0fo3n', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findKthPositive(int[] arr, int k) {
        for (int num : arr) {
