INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv700fjo76vrwbvu0tt', 'cmwolljv700fho76vu5t0fo3n', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findKthPositive(int[] arr, int k) {
        int low = 0, high = arr.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int missing = arr[mid] - (mid + 1);
            if (missing < k) low = mid + 1;
            else high = mid - 1;
        }
        return low + k;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.548Z', '2026-11-20T06:28:30.548Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv800fmo76v059ni1my', 'cmwolljv800flo76vzr1jtz7e', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static int findLargestMinDistance(ArrayList<Integer> boards, int k) {
        int max = 0, sum = 0;
        for (int b : boards) { max = Math.max(max, b); sum += b; }
        for (int time = max; time <= sum; time++) {
            if (countPainters(boards, time) <= k) return time;
        }
        return sum;
    }

    private static int countPainters(ArrayList<Integer> boards, int time) {
        int painters = 1, current = 0;
        for (int b : boards) {
            if (current + b <= time) current += b;
            else { painters++; current = b; }
        }
        return painters;
    }
}', 'O((sum - max) * N)', 'O(1)', '2026-11-20T06:28:30.549Z', '2026-11-20T06:28:30.549Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv800fno76vz1kmcl91', 'cmwolljv800flo76vzr1jtz7e', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static int findLargestMinDistance(ArrayList<Integer> boards, int k) {
        int low = 0, high = 0;
        for (int b : boards) { low = Math.max(low, b); high += b; }
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (countPainters(boards, mid) <= k) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private static int countPainters(ArrayList<Integer> boards, int time) {
        int painters = 1, current = 0;
        for (int b : boards) {
            if (current + b <= time) current += b;
            else { painters++; current = b; }
        }
        return painters;
    }
}', 'O(N log(sum - max))', 'O(1)', '2026-11-20T06:28:30.549Z', '2026-11-20T06:28:30.549Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv900fqo76vzftpa834', 'cmwolljv900fpo76vu0ve92it', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int aggressiveCows(int[] stalls, int k) {
        Arrays.sort(stalls);
        int maxDist = stalls[stalls.length - 1] - stalls[0];
        for (int d = 1; d <= maxDist; d++) {
            if (!canPlace(stalls, d, k)) return d - 1;
        }
        return maxDist;
    }

    private static boolean canPlace(int[] stalls, int dist, int cows) {
        int count = 1, last = stalls[0];
        for (int i = 1; i < stalls.length; i++) {
            if (stalls[i] - last >= dist) {
                count++;
                last = stalls[i];
            }
            if (count >= cows) return true;
        }
        return false;
    }
}', 'O(N log N + (max - min) * N)', 'O(1)', '2026-11-20T06:28:30.550Z', '2026-11-20T06:28:30.550Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljv900fro76v9ygzz6a7', 'cmwolljv900fpo76vu0ve92it', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int aggressiveCows(int[] stalls, int k) {
        Arrays.sort(stalls);
        int low = 1, high = stalls[stalls.length - 1] - stalls[0];
        int ans = 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canPlace(stalls, mid, k)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }

    private static boolean canPlace(int[] stalls, int dist, int cows) {
        int count = 1, last = stalls[0];
        for (int i = 1; i < stalls.length; i++) {
            if (stalls[i] - last >= dist) {
                count++;
                last = stalls[i];
            }
            if (count >= cows) return true;
        }
        return false;
    }
}', 'O(N log N + N log(max - min))', 'O(1)', '2026-11-20T06:28:30.550Z', '2026-11-20T06:28:30.550Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwi00kro76vz8jjlz2c', 'cmwolljwi00kpo76v4r7wgaoz', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
