INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljva00fuo76vv6mpwo9d', 'cmwolljva00fto76v2danoy5r', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static int findPages(ArrayList<Integer> arr, int n, int m) {
        if (m > n) return -1;
        int max = 0, sum = 0;
        for (int x : arr) { max = Math.max(max, x); sum += x; }
        for (int pages = max; pages <= sum; pages++) {
            if (countStudents(arr, pages) <= m) return pages;
        }
        return -1;
    }

    private static int countStudents(ArrayList<Integer> arr, int pages) {
        int students = 1, current = 0;
        for (int x : arr) {
            if (current + x <= pages) current += x;
            else { students++; current = x; }
        }
        return students;
    }
}', 'O((sum - max) * N)', 'O(1)', '2026-11-20T06:28:30.550Z', '2026-11-20T06:28:30.550Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljva00fvo76vzz6mpqle', 'cmwolljva00fto76v2danoy5r', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static int findPages(ArrayList<Integer> arr, int n, int m) {
        if (m > n) return -1;
        int low = 0, high = 0;
        for (int x : arr) { low = Math.max(low, x); high += x; }
        int ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (countStudents(arr, mid) <= m) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private static int countStudents(ArrayList<Integer> arr, int pages) {
        int students = 1, current = 0;
        for (int x : arr) {
            if (current + x <= pages) current += x;
            else { students++; current = x; }
        }
        return students;
    }
}', 'O(N log(sum - max))', 'O(1)', '2026-11-20T06:28:30.550Z', '2026-11-20T06:28:30.550Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvb00fyo76v1ua6rlqx', 'cmwolljvb00fxo76vwk9ynrw0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findPeakElement(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            if ((i == 0 || nums[i] > nums[i - 1]) && (i == n - 1 || nums[i] > nums[i + 1])) {
                return i;
            }
        }
        return 0;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.551Z', '2026-11-20T06:28:30.551Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvb00fzo76va8t77zgd', 'cmwolljvb00fxo76vwk9ynrw0', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findPeakElement(int[] nums) {
        int n = nums.length;
        if (n == 1) return 0;
        if (nums[0] > nums[1]) return 0;
        if (nums[n - 1] > nums[n - 2]) return n - 1;
        int low = 1, high = n - 2;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] > nums[mid - 1] && nums[mid] > nums[mid + 1]) return mid;
            if (nums[mid] > nums[mid - 1]) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.551Z', '2026-11-20T06:28:30.551Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvc00g2o76veqoedk1o', 'cmwolljvc00g1o76vqsqn7c5h', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int n1 = nums1.length, n2 = nums2.length;
        int[] arr = new int[n1 + n2];
        int i = 0, j = 0, k = 0;
        while (i < n1 && j < n2) {
            if (nums1[i] <= nums2[j]) arr[k++] = nums1[i++];
            else arr[k++] = nums2[j++];
        }
        while (i < n1) arr[k++] = nums1[i++];
        while (j < n2) arr[k++] = nums2[j++];
        int n = n1 + n2;
        if (n % 2 == 1) return arr[n / 2];
        return ((double) arr[n / 2] + arr[n / 2 - 1]) / 2.0;
    }
}', 'O(N1 + N2)', 'O(N1 + N2)', '2026-11-20T06:28:30.552Z', '2026-11-20T06:28:30.552Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvc00g3o76vac83qet9', 'cmwolljvc00g1o76vqsqn7c5h', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int n1 = nums1.length, n2 = nums2.length;
        if (n1 > n2) return findMedianSortedArrays(nums2, nums1);
        int low = 0, high = n1, left = (n1 + n2 + 1) / 2;
        int n = n1 + n2;
        while (low <= high) {
            int mid1 = (low + high) / 2;
            int mid2 = left - mid1;
            int l1 = mid1 > 0 ? nums1[mid1 - 1] : Integer.MIN_VALUE;
            int l2 = mid2 > 0 ? nums2[mid2 - 1] : Integer.MIN_VALUE;
            int r1 = mid1 < n1 ? nums1[mid1] : Integer.MAX_VALUE;
            int r2 = mid2 < n2 ? nums2[mid2] : Integer.MAX_VALUE;

            if (l1 <= r2 && l2 <= r1) {
                if (n % 2 == 1) return Math.max(l1, l2);
                return ((double) Math.max(l1, l2) + Math.min(r1, r2)) / 2.0;
            } else if (l1 > r2) {
                high = mid1 - 1;
            } else {
                low = mid1 + 1;
            }
        }
        return 0.0;
    }
}', 'O(log(min(N1, N2)))', 'O(1)', '2026-11-20T06:28:30.552Z', '2026-11-20T06:28:30.552Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvd00g6o76v2v7pi14e', 'cmwolljvd00g5o76vywf6893b', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long kthElement(int[] arr1, int[] arr2, int n, int m, int k) {
        int i = 0, j = 0, count = 0;
        while (i < n && j < m) {
            if (arr1[i] <= arr2[j]) {
                if (++count == k) return arr1[i];
                i++;
            } else {
                if (++count == k) return arr2[j];
                j++;
            }
        }
        while (i < n) {
            if (++count == k) return arr1[i];
            i++;
        }
        while (j < m) {
            if (++count == k) return arr2[j];
            j++;
        }
        return -1;
    }
}', 'O(K)', 'O(1)', '2026-11-20T06:28:30.553Z', '2026-11-20T06:28:30.553Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvd00g7o76vd4e0b81y', 'cmwolljvd00g5o76vywf6893b', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long kthElement(int[] arr1, int[] arr2, int n, int m, int k) {
        if (n > m) return kthElement(arr2, arr1, m, n, k);
        int low = Math.max(0, k - m), high = Math.min(k, n);
        while (low <= high) {
            int cut1 = (low + high) / 2;
            int cut2 = k - cut1;
            int l1 = cut1 == 0 ? Integer.MIN_VALUE : arr1[cut1 - 1];
            int l2 = cut2 == 0 ? Integer.MIN_VALUE : arr2[cut2 - 1];
            int r1 = cut1 == n ? Integer.MAX_VALUE : arr1[cut1];
            int r2 = cut2 == m ? Integer.MAX_VALUE : arr2[cut2];

            if (l1 <= r2 && l2 <= r1) {
                return Math.max(l1, l2);
            } else if (l1 > r2) {
                high = cut1 - 1;
            } else {
                low = cut1 + 1;
            }
        }
        return -1;
    }
}', 'O(log(min(N, M)))', 'O(1)', '2026-11-20T06:28:30.553Z', '2026-11-20T06:28:30.553Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvd00gao76vvgmfcqk0', 'cmwolljvd00g9o76v5qnrh2oe', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static double findSmallestMaxDist(int[] stations, int K) {
        int n = stations.length;
        int[] howMany = new int[n - 1];
        for (int gas = 1; gas <= K; gas++) {
            double maxSection = -1;
            int maxIdx = -1;
            for (int i = 0; i < n - 1; i++) {
                double diff = stations[i + 1] - stations[i];
                double sectionLen = diff / (double) (howMany[i] + 1);
                if (sectionLen > maxSection) {
                    maxSection = sectionLen;
                    maxIdx = i;
                }
            }
            howMany[maxIdx]++;
        }
        double maxAns = -1;
        for (int i = 0; i < n - 1; i++) {
            double diff = stations[i + 1] - stations[i];
            maxAns = Math.max(maxAns, diff / (double) (howMany[i] + 1));
        }
        return maxAns;
    }
}', 'O(K * N)', 'O(N)', '2026-11-20T06:28:30.554Z', '2026-11-20T06:28:30.554Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwj00kuo76va05tdikz', 'cmwolljwj00kto76vidum266h', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node deleteTail(Node head) {
        if (head == null || head.next == null) return null;
        Node curr = head;
        while (curr.next.next != null) curr = curr.next;
        curr.next = null;
        return head;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.595Z', '2026-11-20T06:28:30.595Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvd00gbo76v2vbq2fda', 'cmwolljvd00g9o76v5qnrh2oe', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static double findSmallestMaxDist(int[] stations, int K) {
        int n = stations.length;
        double low = 0, high = 0;
        for (int i = 0; i < n - 1; i++) high = Math.max(high, stations[i + 1] - stations[i]);
        double diff = 1e-6;
        while (high - low > diff) {
            double mid = (low + high) / 2.0;
            if (countStations(stations, mid) <= K) high = mid;
            else low = mid;
        }
        return high;
    }

    private static int countStations(int[] stations, double dist) {
        int count = 0;
        for (int i = 1; i < stations.length; i++) {
            int numInBetween = (int) ((stations[i] - stations[i - 1]) / dist);
            if ((stations[i] - stations[i - 1]) == numInBetween * dist) numInBetween--;
            count += numInBetween;
        }
        return count;
    }
}', 'O(N log(dist / 10^-6))', 'O(1)', '2026-11-20T06:28:30.554Z', '2026-11-20T06:28:30.554Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljve00geo76vqdq72kkh', 'cmwolljve00gdo76vejsq4y3m', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int splitArray(int[] nums, int k) {
        int low = 0, high = 0;
        for (int x : nums) { low = Math.max(low, x); high += x; }
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canSplit(nums, mid, k)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private static boolean canSplit(int[] nums, int maxSum, int k) {
        int pieces = 1, current = 0;
        for (int x : nums) {
            if (current + x <= maxSum) current += x;
            else { pieces++; current = x; }
        }
        return pieces <= k;
    }
}', 'O(N log(sum - max))', 'O(1)', '2026-11-20T06:28:30.555Z', '2026-11-20T06:28:30.555Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljve00gfo76virxe6gj7', 'cmwolljve00gdo76vejsq4y3m', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int splitArray(int[] nums, int k) {
        int low = 0, high = 0;
        for (int x : nums) { low = Math.max(low, x); high += x; }
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canSplit(nums, mid, k)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private static boolean canSplit(int[] nums, int maxSum, int k) {
        int pieces = 1, current = 0;
        for (int x : nums) {
            if (current + x <= maxSum) current += x;
            else { pieces++; current = x; }
        }
        return pieces <= k;
    }
}', 'O(N log(sum - max))', 'O(1)', '2026-11-20T06:28:30.555Z', '2026-11-20T06:28:30.555Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvf00gio76v76o34mve', 'cmwolljvf00gho76vnrx8jac3', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int rowWithMax1s(int[][] arr, int n, int m) {
        int maxCount = 0, maxRow = -1;
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < m; j++) {
                if (arr[i][j] == 1) count++;
            }
            if (count > maxCount) {
                maxCount = count;
                maxRow = i;
            }
        }
        return maxRow;
    }
}', 'O(N * M)', 'O(1)', '2026-11-20T06:28:30.555Z', '2026-11-20T06:28:30.555Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvf00gjo76vwrma0o0p', 'cmwolljvf00gho76vnrx8jac3', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int rowWithMax1s(int[][] arr, int n, int m) {
        int maxCount = 0, maxRow = -1;
        for (int i = 0; i < n; i++) {
            int first1 = lowerBound(arr[i], m, 1);
            int count = m - first1;
            if (count > maxCount) {
                maxCount = count;
                maxRow = i;
            }
        }
        return maxRow;
    }

    private static int lowerBound(int[] row, int m, int target) {
        int low = 0, high = m - 1, ans = m;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (row[mid] >= target) { ans = mid; high = mid - 1; }
            else low = mid + 1;
        }
        return ans;
    }
}', 'O(N log M)', 'O(1)', '2026-11-20T06:28:30.555Z', '2026-11-20T06:28:30.555Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvg00gmo76vw4f6v63q', 'cmwolljvg00glo76vlmokcs9n', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean searchMatrix(int[][] matrix, int target) {
        int m = matrix.length, n = matrix[0].length;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == target) return true;
            }
        }
        return false;
    }
}', 'O(M * N)', 'O(1)', '2026-11-20T06:28:30.556Z', '2026-11-20T06:28:30.556Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvg00gno76v0iqs29pm', 'cmwolljvg00glo76vlmokcs9n', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean searchMatrix(int[][] matrix, int target) {
        int m = matrix.length, n = matrix[0].length;
        int low = 0, high = m * n - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int r = mid / n, c = mid % n;
            if (matrix[r][c] == target) return true;
            else if (matrix[r][c] < target) low = mid + 1;
            else high = mid - 1;
        }
        return false;
    }
}', 'O(log(M * N))', 'O(1)', '2026-11-20T06:28:30.556Z', '2026-11-20T06:28:30.556Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvh00gqo76vlg60f7x3', 'cmwolljvh00gpo76vect8l4ie', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean searchMatrix(int[][] matrix, int target) {
        for (int[] row : matrix) {
            for (int val : row) {
                if (val == target) return true;
            }
        }
        return false;
    }
}', 'O(M * N)', 'O(1)', '2026-11-20T06:28:30.557Z', '2026-11-20T06:28:30.557Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvh00gro76vjflfrtc0', 'cmwolljvh00gpo76vect8l4ie', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean searchMatrix(int[][] matrix, int target) {
        int row = 0, col = matrix[0].length - 1;
        while (row < matrix.length && col >= 0) {
            if (matrix[row][col] == target) return true;
            else if (matrix[row][col] > target) col--;
            else row++;
        }
        return false;
    }
}', 'O(M + N)', 'O(1)', '2026-11-20T06:28:30.557Z', '2026-11-20T06:28:30.557Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvh00guo76v71s6qfx8', 'cmwolljvh00gto76vsohs5mh1', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] findPeakGrid(int[][] mat) {
        int max = Integer.MIN_VALUE, maxR = 0, maxC = 0;
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[0].length; j++) {
                if (mat[i][j] > max) {
                    max = mat[i][j];
                    maxR = i;
                    maxC = j;
                }
            }
        }
        return new int[]{maxR, maxC};
    }
}', 'O(M * N)', 'O(1)', '2026-11-20T06:28:30.558Z', '2026-11-20T06:28:30.558Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvh00gvo76v0mk0cauz', 'cmwolljvh00gto76vsohs5mh1', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int[] findPeakGrid(int[][] mat) {
        int low = 0, high = mat[0].length - 1;
        while (low <= high) {
            int midCol = low + (high - low) / 2;
            int maxRow = 0;
            for (int i = 0; i < mat.length; i++) {
                if (mat[i][midCol] > mat[maxRow][midCol]) maxRow = i;
            }
            int left = midCol > 0 ? mat[maxRow][midCol - 1] : -1;
            int right = midCol < mat[0].length - 1 ? mat[maxRow][midCol + 1] : -1;
            if (mat[maxRow][midCol] > left && mat[maxRow][midCol] > right) {
                return new int[]{maxRow, midCol};
            } else if (left > mat[maxRow][midCol]) {
                high = midCol - 1;
            } else {
                low = midCol + 1;
            }
        }
        return new int[]{-1, -1};
    }
}', 'O(M log N)', 'O(1)', '2026-11-20T06:28:30.558Z', '2026-11-20T06:28:30.558Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvi00gzo76vai95mp3e', 'cmwolljvi00gxo76vuumo5d8c', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findMedian(int[][] matrix) {
        int low = Integer.MAX_VALUE, high = Integer.MIN_VALUE;
        int R = matrix.length, C = matrix[0].length;
        for (int i = 0; i < R; i++) {
            low = Math.min(low, matrix[i][0]);
            high = Math.max(high, matrix[i][C - 1]);
        }
        int desired = (R * C + 1) / 2;
        while (low < high) {
            int mid = low + (high - low) / 2;
            int count = 0;
            for (int i = 0; i < R; i++) {
                count += upperBound(matrix[i], mid);
            }
            if (count < desired) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    private static int upperBound(int[] row, int target) {
        int l = 0, r = row.length;
        while (l < r) {
            int m = (l + r) / 2;
            if (row[m] <= target) l = m + 1;
            else r = m;
        }
        return l;
    }
}', 'O(32 * R log C)', 'O(1)', '2026-11-20T06:28:30.559Z', '2026-11-20T06:28:30.559Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvj00h2o76va985kii3', 'cmwolljvj00h1o76va294iw50', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static String removeOuterParentheses(String s) {
        StringBuilder sb = new StringBuilder();
        Stack<Character> stack = new Stack<>();
        for (char c : s.toCharArray()) {
            if (c == ''('') {
                if (!stack.isEmpty()) sb.append(c);
                stack.push(c);
            } else {
                stack.pop();
                if (!stack.isEmpty()) sb.append(c);
            }
        }
        return sb.toString();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.560Z', '2026-11-20T06:28:30.560Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvj00h3o76vyianr7xn', 'cmwolljvj00h1o76va294iw50', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static String removeOuterParentheses(String s) {
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == ''('' && count++ > 0) sb.append(c);
            if (c == '')'' && --count > 0) sb.append(c);
        }
        return sb.toString();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.560Z', '2026-11-20T06:28:30.560Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvk00h6o76vnsgwtgvc', 'cmwolljvk00h5o76vl9mtd6ui', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static int maxDepth(String s) {
        int max = 0;
        Stack<Character> stack = new Stack<>();
        for (char c : s.toCharArray()) {
            if (c == ''('') {
                stack.push(c);
                max = Math.max(max, stack.size());
            } else if (c == '')'') {
                if (!stack.isEmpty()) stack.pop();
            }
        }
        return max;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.560Z', '2026-11-20T06:28:30.560Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvk00h7o76vhvffgtg3', 'cmwolljvk00h5o76vl9mtd6ui', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int maxDepth(String s) {
        int max = 0, current = 0;
        for (char c : s.toCharArray()) {
            if (c == ''('') {
                current++;
                max = Math.max(max, current);
            } else if (c == '')'') {
                current--;
            }
        }
        return max;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.560Z', '2026-11-20T06:28:30.560Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvl00hao76v4ktxlq4i', 'cmwolljvl00h9o76v4p8uh1lr', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int romanToInt(String s) {
        Map<Character, Integer> map = new HashMap<>();
        map.put(''I'', 1); map.put(''V'', 5); map.put(''X'', 10);
        map.put(''L'', 50); map.put(''C'', 100); map.put(''D'', 500); map.put(''M'', 100);
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            int current = map.get(s.charAt(i));
            if (i + 1 < s.length() && current < map.get(s.charAt(i + 1))) {
                total -= current;
            } else {
                total += current;
            }
        }
        return total;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.561Z', '2026-11-20T06:28:30.561Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvl00hbo76v8xxartao', 'cmwolljvl00h9o76v4p8uh1lr', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int romanToInt(String s) {
        int total = 0, prev = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            int curr = switch (s.charAt(i)) {
                case ''I'' -> 1;
                case ''V'' -> 5;
                case ''X'' -> 10;
                case ''L'' -> 50;
                case ''C'' -> 100;
                case ''D'' -> 500;
                case ''M'' -> 1000;
                default -> 0;
            };
            if (curr < prev) total -= curr;
            else total += curr;
            prev = curr;
        }
        return total;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.561Z', '2026-11-20T06:28:30.561Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvm00heo76vwpri74a4', 'cmwolljvm00hdo76v0cbwh4y2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int myAtoi(String s) {
        s = s.trim();
        if (s.isEmpty()) return 0;
        int sign = 1, i = 0;
        if (s.charAt(0) == ''-'') { sign = -1; i++; }
        else if (s.charAt(0) == ''+'') { i++; }
        long num = 0;
        while (i < s.length() && Character.isDigit(s.charAt(i))) {
            num = num * 10 + (s.charAt(i) - ''0'');
            if (sign == 1 && num > Integer.MAX_VALUE) return Integer.MAX_VALUE;
            if (sign == -1 && -num < Integer.MIN_VALUE) return Integer.MIN_VALUE;
            i++;
        }
        return (int) (sign * num);
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.562Z', '2026-11-20T06:28:30.562Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvm00hfo76v8n6j61hd', 'cmwolljvm00hdo76v0cbwh4y2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int myAtoi(String s) {
        int i = 0, n = s.length();
        while (i < n && s.charAt(i) == '' '') i++;
        if (i == n) return 0;
        int sign = 1;
        if (s.charAt(i) == ''+'' || s.charAt(i) == ''-'') {
            sign = (s.charAt(i) == ''-'') ? -1 : 1;
            i++;
        }
        int num = 0;
        while (i < n && Character.isDigit(s.charAt(i))) {
            int digit = s.charAt(i) - ''0'';
            if (num > (Integer.MAX_VALUE - digit) / 10) {
                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }
            num = num * 10 + digit;
            i++;
        }
        return sign * num;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.562Z', '2026-11-20T06:28:30.562Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvm00hio76vg7pv7ubv', 'cmwolljvm00hho76vhqtwialz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static long substrCount(String s, int k) {
        long count = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            Set<Character> distinct = new HashSet<>();
            for (int j = i; j < n; j++) {
                distinct.add(s.charAt(j));
                if (distinct.size() == k) count++;
                else if (distinct.size() > k) break;
            }
        }
        return count;
    }
}', 'O(N²)', 'O(K)', '2026-11-20T06:28:30.563Z', '2026-11-20T06:28:30.563Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvm00hjo76vnj42bb5e', 'cmwolljvm00hho76vhqtwialz', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long substrCount(String s, int k) {
        return atMostK(s, k) - atMostK(s, k - 1);
    }

    private static long atMostK(String s, int k) {
        if (k < 0) return 0;
        int[] freq = new int[26];
        long count = 0;
        int left = 0, distinct = 0;
        for (int right = 0; right < s.length(); right++) {
            if (freq[s.charAt(right) - ''a'']++ == 0) distinct++;
            while (distinct > k) {
                if (--freq[s.charAt(left) - ''a''] == 0) distinct--;
                left++;
            }
            count += (right - left + 1);
        }
        return count;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.563Z', '2026-11-20T06:28:30.563Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvn00hmo76vnmzois9l', 'cmwolljvn00hlo76v0b4ais75', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String longestPalindrome(String s) {
        String longest = "";
        for (int i = 0; i < s.length(); i++) {
            for (int j = i; j < s.length(); j++) {
                if (isPalindrome(s, i, j) && (j - i + 1) > longest.length()) {
                    longest = s.substring(i, j + 1);
                }
            }
        }
        return longest;
    }

    private static boolean isPalindrome(String s, int i, int j) {
        while (i < j) {
            if (s.charAt(i++) != s.charAt(j--)) return false;
        }
        return true;
    }
}', 'O(N³)', 'O(1)', '2026-11-20T06:28:30.563Z', '2026-11-20T06:28:30.563Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvn00hno76voch46jvl', 'cmwolljvn00hlo76v0b4ais75', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static String longestPalindrome(String s) {
        if (s == null || s.length() < 1) return "";
        int start = 0, end = 0;
        for (int i = 0; i < s.length(); i++) {
            int len1 = expandAroundCenter(s, i, i);
            int len2 = expandAroundCenter(s, i, i + 1);
            int len = Math.max(len1, len2);
            if (len > end - start) {
                start = i - (len - 1) / 2;
                end = i + len / 2;
            }
        }
        return s.substring(start, end + 1);
    }

    private static int expandAroundCenter(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        return right - left - 1;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.563Z', '2026-11-20T06:28:30.563Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvo00hqo76vy5xsyeo7', 'cmwolljvo00hpo76vjln27hny', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int beautySum(String s) {
        int sum = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            int[] freq = new int[26];
            for (int j = i; j < n; j++) {
                freq[s.charAt(j) - ''a'']++;
                int max = 0, min = Integer.MAX_VALUE;
                for (int f : freq) {
                    if (f > 0) {
                        max = Math.max(max, f);
                        min = Math.min(min, f);
                    }
                }
                sum += (max - min);
            }
        }
        return sum;
    }
}', 'O(26 * N²)', 'O(1)', '2026-11-20T06:28:30.564Z', '2026-11-20T06:28:30.564Z') ON CONFLICT DO NOTHING;
