INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvp00huo76vtmjuwqhs', 'cmwolljvp00hto76v2nvecybt', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static double myPow(double x, int n) {
        long N = n;
        if (N < 0) {
            x = 1 / x;
            N = -N;
        }
        double ans = 1;
        for (long i = 0; i < N; i++) {
            ans = ans * x;
        }
        return ans;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.565Z', '2026-11-20T06:28:30.565Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvp00hvo76v7h2b0gpl', 'cmwolljvp00hto76v2nvecybt', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static double myPow(double x, int n) {
        long N = n;
        if (N < 0) {
            x = 1 / x;
            N = -N;
        }
        double ans = 1;
        double currentProduct = x;
        for (long i = N; i > 0; i /= 2) {
            if (i % 2 == 1) ans = ans * currentProduct;
            currentProduct = currentProduct * currentProduct;
        }
        return ans;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.565Z', '2026-11-20T06:28:30.565Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvp00hyo76vq5f0ue53', 'cmwolljvp00hxo76v535yg9v5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        backtrack(result, "", 0, 0, n);
        return result;
    }

    private static void backtrack(List<String> result, String current, int open, int close, int max) {
        if (current.length() == max * 2) {
            result.add(current);
            return;
        }
        if (open < max) backtrack(result, current + "(", open + 1, close, max);
        if (close < open) backtrack(result, current + ")", open, close + 1, max);
    }
}', 'O(4^N / sqrt(N))', 'O(N)', '2026-11-20T06:28:30.566Z', '2026-11-20T06:28:30.566Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvp00hzo76v3wqspoq6', 'cmwolljvp00hxo76v535yg9v5', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        backtrack(result, new StringBuilder(), 0, 0, n);
        return result;
    }

    private static void backtrack(List<String> result, StringBuilder current, int open, int close, int max) {
        if (current.length() == max * 2) {
            result.add(current.toString());
            return;
        }
        if (open < max) {
            current.append(''('');
            backtrack(result, current, open + 1, close, max);
            current.deleteCharAt(current.length() - 1);
        }
        if (close < open) {
            current.append('')'');
            backtrack(result, current, open, close + 1, max);
            current.deleteCharAt(current.length() - 1);
        }
    }
}', 'O(4^N / sqrt(N))', 'O(N)', '2026-11-20T06:28:30.566Z', '2026-11-20T06:28:30.566Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvq00i2o76vh4zi8zfi', 'cmwolljvq00i1o76v8a4yytyt', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> AllPossibleStrings(String s) {
        List<String> res = new ArrayList<>();
        int n = s.length();
        for (int i = 1; i < (1 << n); i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) sb.append(s.charAt(j));
            }
            res.add(sb.toString());
        }
        Collections.sort(res);
        return res;
    }
}', 'O(N * 2^N)', 'O(2^N)', '2026-11-20T06:28:30.567Z', '2026-11-20T06:28:30.567Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvq00i3o76vb5esmb6c', 'cmwolljvq00i1o76v8a4yytyt', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> AllPossibleStrings(String s) {
        List<String> res = new ArrayList<>();
        solve(0, s, new StringBuilder(), res);
        Collections.sort(res);
        return res;
    }

    private static void solve(int index, String s, StringBuilder current, List<String> res) {
        if (index == s.length()) {
            if (current.length() > 0) res.add(current.toString());
            return;
        }
        current.append(s.charAt(index));
        solve(index + 1, s, current, res);
        current.deleteCharAt(current.length() - 1);
        solve(index + 1, s, current, res);
    }
}', 'O(2^N log(2^N))', 'O(N)', '2026-11-20T06:28:30.567Z', '2026-11-20T06:28:30.567Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvr00i6o76vgns0ubug', 'cmwolljvr00i5o76vjcm5v9q8', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    private static final long MOD = 1_000_000_007;

    public static int countGoodNumbers(long n) {
        long even = (n + 1) / 2;
        long odd = n / 2;
        long ans = 1;
        for (long i = 0; i < even; i++) ans = (ans * 5) % MOD;
        for (long i = 0; i < odd; i++) ans = (ans * 4) % MOD;
        return (int) ans;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.568Z', '2026-11-20T06:28:30.568Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvr00i7o76votng683e', 'cmwolljvr00i5o76vjcm5v9q8', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    private static final long MOD = 1_000_000_007;

    public static int countGoodNumbers(long n) {
        long even = (n + 1) / 2;
        long odd = n / 2;
        long first = power(5, even);
        long second = power(4, odd);
        return (int) ((first * second) % MOD);
    }

    private static long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.568Z', '2026-11-20T06:28:30.568Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvs00iao76v3pg5zxit', 'cmwolljvs00i9o76vzu70l3gd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static void reverse(Stack<Integer> s) {
        int[] arr = new int[s.size()];
        int idx = 0;
        while (!s.isEmpty()) arr[idx++] = s.pop();
        for (int i = 0; i < arr.length; i++) s.push(arr[i]);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.568Z', '2026-11-20T06:28:30.568Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvs00ibo76vlr07ye1t', 'cmwolljvs00i9o76vzu70l3gd', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static void reverse(Stack<Integer> s) {
        if (s.isEmpty()) return;
        int top = s.pop();
        reverse(s);
        insertAtBottom(s, top);
    }

    private static void insertAtBottom(Stack<Integer> s, int x) {
        if (s.isEmpty()) {
            s.push(x);
            return;
        }
        int top = s.pop();
        insertAtBottom(s, x);
        s.push(top);
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.568Z', '2026-11-20T06:28:30.568Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvt00ieo76va8tups3f', 'cmwolljvt00ido76v05efq8os', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static void printSubsequences(int[] arr) {
        // Pattern of Subsequence: Pick / Non-Pick
        solve(0, arr, new ArrayList<>());
    }

    private static void solve(int i, int[] arr, List<Integer> current) {
        if (i == arr.length) {
            System.out.println(current);
            return;
