INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvt00ijo76vtrwytm0x', 'cmwolljvt00iho76v5dx04031', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean checkSubsequenceSum(int n, int[] arr, int k) {
        return solve(0, arr, 0, k);
