INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvu00imo76vx2lhad2d', 'cmwolljvu00ilo76vdh4znqxq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int countSubsequences(int[] arr, int k) {
        return solve(0, arr, 0, k);
    }

    private static int solve(int idx, int[] arr, int sum, int k) {
        if (idx == arr.length) return sum == k ? 1 : 0;
        int take = solve(idx + 1, arr, sum + arr[idx], k);
        int notTake = solve(idx + 1, arr, sum, k);
        return take + notTake;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.571Z', '2026-11-20T06:28:30.571Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvu00ino76vq4qt28n2', 'cmwolljvu00ilo76vdh4znqxq', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countSubsequences(int[] arr, int k) {
        int[] dp = new int[k + 1];
        dp[0] = 1;
        for (int num : arr) {
            for (int j = k; j >= num; j--) {
                dp[j] = (dp[j] + dp[j - num]) % 1_000_000_007;
            }
        }
        return dp[k];
    }
}', 'O(N * K)', 'O(K)', '2026-11-20T06:28:30.571Z', '2026-11-20T06:28:30.571Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvv00iqo76vev3r6y44', 'cmwolljvv00ipo76vq2llivv1', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> generateBinaryStrings(int n) {
        List<String> res = new ArrayList<>();
        solve(n, "", res);
        return res;
    }

    private static void solve(int n, String curr, List<String> res) {
        if (curr.length() == n) {
            res.add(curr);
            return;
        }
        solve(n, curr + "0", res);
        if (curr.isEmpty() || curr.charAt(curr.length() - 1) != ''1'') {
            solve(n, curr + "1", res);
        }
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.571Z', '2026-11-20T06:28:30.571Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvv00iro76vi15x00q0', 'cmwolljvv00ipo76vq2llivv1', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> generateBinaryStrings(int n) {
        List<String> res = new ArrayList<>();
        solve(n, new StringBuilder(), res);
        return res;
    }

    private static void solve(int n, StringBuilder curr, List<String> res) {
        if (curr.length() == n) {
            res.add(curr.toString());
            return;
        }
        curr.append(''0'');
        solve(n, curr, res);
        curr.deleteCharAt(curr.length() - 1);
        if (curr.length() == 0 || curr.charAt(curr.length() - 1) != ''1'') {
            curr.append(''1'');
            solve(n, curr, res);
            curr.deleteCharAt(curr.length() - 1);
        }
    }
}', 'O(Fibonacci(N))', 'O(N)', '2026-11-20T06:28:30.571Z', '2026-11-20T06:28:30.571Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvw00iuo76vi4mhbtn4', 'cmwolljvw00ito76v55a89ity', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> ans = new ArrayList<>();
        findCombinations(0, candidates, target, ans, new ArrayList<>());
        return ans;
    }

    private static void findCombinations(int ind, int[] arr, int target, List<List<Integer>> ans, List<Integer> ds) {
        if (ind == arr.length) {
            if (target == 0) ans.add(new ArrayList<>(ds));
            return;
        }
        if (arr[ind] <= target) {
            ds.add(arr[ind]);
            findCombinations(ind, arr, target - arr[ind], ans, ds);
            ds.remove(ds.size() - 1);
        }
        findCombinations(ind + 1, arr, target, ans, ds);
    }
}', 'O(2^t * k)', 'O(k * x)', '2026-11-20T06:28:30.572Z', '2026-11-20T06:28:30.572Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwj00kvo76v9ujvbkyu', 'cmwolljwj00kto76vidum266h', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
