        if (head == null || head.next == null) return null;
        Node curr = head;
        while (curr.next.next != null) curr = curr.next;
        curr.next = null;
        return head;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.595Z', '2026-11-20T06:28:30.595Z') ON CONFLICT DO NOTHING;
