INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvy00j2o76v0zf2tdwc', 'cmwolljvy00j1o76vmrodjedj', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<Integer> subsetSums(int[] arr, int n) {
        ArrayList<Integer> subsetSum = new ArrayList<>();
        for (int i = 0; i < (1 << n); i++) {
            int sum = 0;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) sum += arr[j];
            }
            subsetSum.add(sum);
        }
        Collections.sort(subsetSum);
        return subsetSum;
    }
}', 'O(2^N * N)', 'O(2^N)', '2026-11-20T06:28:30.575Z', '2026-11-20T06:28:30.575Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvy00j3o76vrd8vrrn3', 'cmwolljvy00j1o76vmrodjedj', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<Integer> subsetSums(int[] arr, int n) {
        ArrayList<Integer> subsetSum = new ArrayList<>();
        helper(0, 0, arr, n, subsetSum);
        Collections.sort(subsetSum);
        return subsetSum;
    }

    private static void helper(int ind, int sum, int[] arr, int n, ArrayList<Integer> subsetSum) {
        if (ind == n) {
            subsetSum.add(sum);
            return;
        }
        helper(ind + 1, sum + arr[ind], arr, n, subsetSum);
        helper(ind + 1, sum, arr, n, subsetSum);
    }
}', 'O(2^N + 2^N log(2^N))', 'O(2^N)', '2026-11-20T06:28:30.575Z', '2026-11-20T06:28:30.575Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvz00j6o76v58ys9hfd', 'cmwolljvz00j5o76vt0fpo5ps', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

