        helper(0, nums, new ArrayList<>(), ans);
        return new ArrayList<>(ans);
    }

    private static void helper(int ind, int[] nums, List<Integer> ds, Set<List<Integer>> ans) {
        if (ind == nums.length) {
            ans.add(new ArrayList<>(ds));
            return;
        }
        ds.add(nums[ind]);
        helper(ind + 1, nums, ds, ans);
        ds.remove(ds.size() - 1);
        helper(ind + 1, nums, ds, ans);
    }
}', 'O(2^N * N log(ans))', 'O(2^N * N)', '2026-11-20T06:28:30.576Z', '2026-11-20T06:28:30.576Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljvz00j7o76vdu7w5348', 'cmwolljvz00j5o76vt0fpo5ps', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> ans = new ArrayList<>();
        findSubsets(0, nums, new ArrayList<>(), ans);
        return ans;
    }

    private static void findSubsets(int ind, int[] nums, List<Integer> ds, List<List<Integer>> ans) {
        ans.add(new ArrayList<>(ds));
        for (int i = ind; i < nums.length; i++) {
            if (i != ind && nums[i] == nums[i - 1]) continue;
            ds.add(nums[i]);
            findSubsets(i + 1, nums, ds, ans);
            ds.remove(ds.size() - 1);
        }
    }
}', 'O(2^N * N)', 'O(2^N * N)', '2026-11-20T06:28:30.576Z', '2026-11-20T06:28:30.576Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw100jao76volrh2hxw', 'cmwolljw100j9o76vxmta6f99', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<Integer>> combinationSum3(int k, int n) {
        List<List<Integer>> ans = new ArrayList<>();
        backtrack(1, k, n, new ArrayList<>(), ans);
        return ans;
    }

    private static void backtrack(int start, int k, int n, List<Integer> current, List<List<Integer>> ans) {
        if (current.size() == k) {
            if (n == 0) ans.add(new ArrayList<>(current));
            return;
        }
        for (int i = start; i <= 9; i++) {
            if (i > n) break;
            current.add(i);
            backtrack(i + 1, k, n - i, current, ans);
            current.remove(current.size() - 1);
        }
    }
}', 'O(C(9, k))', 'O(k)', '2026-11-20T06:28:30.577Z', '2026-11-20T06:28:30.577Z') ON CONFLICT DO NOTHING;
