INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwk00kyo76vpuilb9u5', 'cmwolljwk00kxo76vehtrfdj8', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node deleteKth(Node head, int k) {
        if (head == null) return null;
        if (k == 1) return head.next;
        Node curr = head;
        for (int i = 1; curr != null && i < k - 1; i++) curr = curr.next;
        if (curr != null && curr.next != null) curr.next = curr.next.next;
        return head;
    }
}', 'O(K)', 'O(1)', '2026-11-20T06:28:30.596Z', '2026-11-20T06:28:30.596Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw200jeo76vznv05r7r', 'cmwolljw200jdo76v21vow2m9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> letterCombinations(String digits) {
        List<String> res = new ArrayList<>();
        if (digits.isEmpty()) return res;
        String[] mapping = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        backtrack(0, digits, new StringBuilder(), res, mapping);
        return res;
    }

    private static void backtrack(int index, String digits, StringBuilder curr, List<String> res, String[] map) {
        if (index == digits.length()) {
            res.add(curr.toString());
            return;
        }
        String letters = map[digits.charAt(index) - ''0''];
        for (char c : letters.toCharArray()) {
            curr.append(c);
            backtrack(index + 1, digits, curr, res, map);
            curr.deleteCharAt(curr.length() - 1);
        }
    }
}', 'O(4^N * N)', 'O(N)', '2026-11-20T06:28:30.578Z', '2026-11-20T06:28:30.578Z') ON CONFLICT DO NOTHING;
