INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw600jqo76vuo3bjdue', 'cmwolljw600jpo76vrn5h2bap', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<String>> solveNQueens(int n) {
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, ''.'');
        List<List<String>> res = new ArrayList<>();
        dfs(0, board, res);
        return res;
    }

    private static void dfs(int col, char[][] board, List<List<String>> res) {
        if (col == board.length) {
            List<String> list = new ArrayList<>();
            for (char[] row : board) list.add(new String(row));
            res.add(list);
            return;
        }
        for (int row = 0; row < board.length; row++) {
            if (validate(board, row, col)) {
                board[row][col] = ''Q'';
                dfs(col + 1, board, res);
                board[row][col] = ''.'';
            }
        }
    }

    private static boolean validate(char[][] board, int row, int col) {
        for (int c = 0; c < col; c++) if (board[row][c] == ''Q'') return false;
        for (int r = row, c = col; r >= 0 && c >= 0; r--, c--) if (board[r][c] == ''Q'') return false;
        for (int r = row, c = col; r < board.length && c >= 0; r++, c--) if (board[r][c] == ''Q'') return false;
        return true;
    }
}', 'O(N! * N)', 'O(N²)', '2026-11-20T06:28:30.582Z', '2026-11-20T06:28:30.582Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw600jro76v1zofx6ug', 'cmwolljw600jpo76vrn5h2bap', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<String>> solveNQueens(int n) {
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, ''.'');
        List<List<String>> res = new ArrayList<>();
        int[] leftRow = new int[n];
        int[] upperDiagonal = new int[2 * n - 1];
        int[] lowerDiagonal = new int[2 * n - 1];
        solve(0, board, res, leftRow, lowerDiagonal, upperDiagonal);
        return res;
    }

    private static void solve(int col, char[][] board, List<List<String>> res, int[] leftRow, int[] lowerDiagonal, int[] upperDiagonal) {
        if (col == board.length) {
            List<String> list = new ArrayList<>();
            for (char[] row : board) list.add(new String(row));
            res.add(list);
            return;
        }
        for (int row = 0; row < board.length; row++) {
            if (leftRow[row] == 0 && lowerDiagonal[row + col] == 0 && upperDiagonal[board.length - 1 + col - row] == 0) {
                board[row][col] = ''Q'';
                leftRow[row] = 1;
                lowerDiagonal[row + col] = 1;
                upperDiagonal[board.length - 1 + col - row] = 1;
                solve(col + 1, board, res, leftRow, lowerDiagonal, upperDiagonal);
                board[row][col] = ''.'';
                leftRow[row] = 0;
                lowerDiagonal[row + col] = 0;
                upperDiagonal[board.length - 1 + col - row] = 0;
            }
        }
    }
}', 'O(N!)', 'O(N)', '2026-11-20T06:28:30.582Z', '2026-11-20T06:28:30.582Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwo00lao76vyc53xoun', 'cmwolljwo00l9o76v9u0o7dhs', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node insertTail(Node head, int val) {
        if (head == null) return new Node(val);
        Node curr = head;
        while (curr.next != null) curr = curr.next;
        curr.next = new Node(val);
        return head;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.600Z', '2026-11-20T06:28:30.600Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw700juo76v1q8yqudq', 'cmwolljw700jto76vl6ghwxzd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<String> findPath(int[][] m, int n) {
        ArrayList<String> ans = new ArrayList<>();
        int[][] vis = new int[n][n];
        if (m[0][0] == 1) solve(0, 0, m, n, ans, "", vis);
        return ans;
    }

    private static void solve(int i, int j, int[][] a, int n, ArrayList<String> ans, String move, int[][] vis) {
        if (i == n - 1 && j == n - 1) {
            ans.add(move);
            return;
        }
        // Down
        if (i + 1 < n && vis[i + 1][j] == 0 && a[i + 1][j] == 1) {
            vis[i][j] = 1;
            solve(i + 1, j, a, n, ans, move + ''D'', vis);
            vis[i][j] = 0;
        }
        // Left
        if (j - 1 >= 0 && vis[i][j - 1] == 0 && a[i][j - 1] == 1) {
            vis[i][j] = 1;
            solve(i, j - 1, a, n, ans, move + ''L'', vis);
            vis[i][j] = 0;
        }
        // Right
        if (j + 1 < n && vis[i][j + 1] == 0 && a[i][j + 1] == 1) {
            vis[i][j] = 1;
            solve(i, j + 1, a, n, ans, move + ''R'', vis);
            vis[i][j] = 0;
        }
        // Up
        if (i - 1 >= 0 && vis[i - 1][j] == 0 && a[i - 1][j] == 1) {
            vis[i][j] = 1;
            solve(i - 1, j, a, n, ans, move + ''U'', vis);
            vis[i][j] = 0;
        }
    }
}', 'O(4^(N*M))', 'O(N * M)', '2026-11-20T06:28:30.584Z', '2026-11-20T06:28:30.584Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw700jvo76vjom7wymh', 'cmwolljw700jto76vl6ghwxzd', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<String> findPath(int[][] m, int n) {
        ArrayList<String> ans = new ArrayList<>();
        int[][] vis = new int[n][n];
        int[] di = {+1, 0, 0, -1};
        int[] dj = {0, -1, 1, 0};
        if (m[0][0] == 1) solve(0, 0, m, n, ans, "", vis, di, dj);
        return ans;
    }

    private static void solve(int i, int j, int[][] a, int n, ArrayList<String> ans, String move, int[][] vis, int[] di, int[] dj) {
        if (i == n - 1 && j == n - 1) {
            ans.add(move);
            return;
        }
        String dir = "DLRU";
        for (int ind = 0; ind < 4; ind++) {
            int nexti = i + di[ind];
            int nextj = j + dj[ind];
            if (nexti >= 0 && nextj >= 0 && nexti < n && nextj < n && vis[nexti][nextj] == 0 && a[nexti][nextj] == 1) {
                vis[i][j] = 1;
                solve(nexti, nextj, a, n, ans, move + dir.charAt(ind), vis, di, dj);
                vis[i][j] = 0;
            }
        }
    }
}', 'O(4^(N*M))', 'O(N * M)', '2026-11-20T06:28:30.584Z', '2026-11-20T06:28:30.584Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw800jyo76v2kxdcb7d', 'cmwolljw800jxo76v82opu61q', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static boolean graphColoring(boolean[][] graph, int m, int n) {
        int[] color = new int[n];
        return solve(0, graph, color, m, n);
    }

    private static boolean solve(int node, boolean[][] graph, int[] color, int m, int n) {
        if (node == n) return true;
        for (int i = 1; i <= m; i++) {
            if (isSafe(node, graph, color, n, i)) {
                color[node] = i;
                if (solve(node + 1, graph, color, m, n)) return true;
                color[node] = 0;
            }
        }
        return false;
    }

    private static boolean isSafe(int node, boolean[][] graph, int[] color, int n, int col) {
        for (int k = 0; k < n; k++) {
            if (k != node && graph[k][node] && color[k] == col) return false;
        }
        return true;
    }
}', 'O(M^N)', 'O(N)', '2026-11-20T06:28:30.585Z', '2026-11-20T06:28:30.585Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljw800jzo76vozl37tez', 'cmwolljw800jxo76v82opu61q', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static boolean graphColoring(boolean[][] graph, int m, int n) {
        int[] color = new int[n];
        return solve(0, graph, color, m, n);
    }

    private static boolean solve(int node, boolean[][] graph, int[] color, int m, int n) {
        if (node == n) return true;
        for (int i = 1; i <= m; i++) {
            if (isSafe(node, graph, color, n, i)) {
                color[node] = i;
                if (solve(node + 1, graph, color, m, n)) return true;
                color[node] = 0;
            }
        }
        return false;
    }

    private static boolean isSafe(int node, boolean[][] graph, int[] color, int n, int col) {
        for (int k = 0; k < n; k++) {
            if (k != node && graph[k][node] && color[k] == col) return false;
        }
        return true;
    }
}', 'O(M^N)', 'O(N)', '2026-11-20T06:28:30.585Z', '2026-11-20T06:28:30.585Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwa00k2o76veonhnjxz', 'cmwolljwa00k1o76v6afvdjjo', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void solveSudoku(char[][] board) {
        solve(board);
    }

    private static boolean solve(char[][] board) {
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == ''.'') {
                    for (char c = ''1''; c <= ''9''; c++) {
                        if (isValid(board, i, j, c)) {
                            board[i][j] = c;
                            if (solve(board)) return true;
                            board[i][j] = ''.'';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValid(char[][] board, int row, int col, char c) {
        for (int i = 0; i < 9; i++) {
            if (board[i][col] == c) return false;
            if (board[row][i] == c) return false;
            if (board[3 * (row / 3) + i / 3][3 * (col / 3) + i % 3] == c) return false;
        }
        return true;
    }
}', 'O(9^(empty cells))', 'O(1)', '2026-11-20T06:28:30.586Z', '2026-11-20T06:28:30.586Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwk00kzo76vq8y580aa', 'cmwolljwk00kxo76vehtrfdj8', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static Node deleteKth(Node head, int k) {
        if (head == null) return null;
        if (k == 1) return head.next;
        Node curr = head;
        for (int i = 1; curr != null && i < k - 1; i++) curr = curr.next;
        if (curr != null && curr.next != null) curr.next = curr.next.next;
        return head;
    }
}', 'O(K)', 'O(1)', '2026-11-20T06:28:30.596Z', '2026-11-20T06:28:30.596Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwa00k3o76vk88das7q', 'cmwolljwa00k1o76v6afvdjjo', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void solveSudoku(char[][] board) {
        solve(board);
    }

    private static boolean solve(char[][] board) {
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == ''.'') {
                    for (char c = ''1''; c <= ''9''; c++) {
                        if (isValid(board, i, j, c)) {
                            board[i][j] = c;
                            if (solve(board)) return true;
                            board[i][j] = ''.'';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValid(char[][] board, int row, int col, char c) {
        for (int i = 0; i < 9; i++) {
            if (board[i][col] == c) return false;
            if (board[row][i] == c) return false;
            if (board[3 * (row / 3) + i / 3][3 * (col / 3) + i % 3] == c) return false;
        }
        return true;
    }
}', 'O(9^(empty cells))', 'O(1)', '2026-11-20T06:28:30.586Z', '2026-11-20T06:28:30.586Z') ON CONFLICT DO NOTHING;
