INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwb00k6o76v7lffriab', 'cmwolljwb00k5o76vwl1b6slg', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> addOperators(String num, int target) {
        List<String> res = new ArrayList<>();
        if (num.isEmpty()) return res;
        backtrack(0, "", 0, 0, num, target, res);
        return res;
    }

    private static void backtrack(int pos, String path, long eval, long multed, String num, int target, List<String> res) {
        if (pos == num.length()) {
            if (eval == target) res.add(path);
            return;
        }
        for (int i = pos; i < num.length(); i++) {
            if (i != pos && num.charAt(pos) == ''0'') break;
            long cur = Long.parseLong(num.substring(pos, i + 1));
            if (pos == 0) {
                backtrack(i + 1, path + cur, cur, cur, num, target, res);
            } else {
                backtrack(i + 1, path + "+" + cur, eval + cur, cur, num, target, res);
                backtrack(i + 1, path + "-" + cur, eval - cur, -cur, num, target, res);
                backtrack(i + 1, path + "*" + cur, eval - multed + multed * cur, multed * cur, num, target, res);
            }
        }
    }
}', 'O(4^N)', 'O(N)', '2026-11-20T06:28:30.587Z', '2026-11-20T06:28:30.587Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwb00k7o76v7ubskrh9', 'cmwolljwb00k5o76vwl1b6slg', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<String> addOperators(String num, int target) {
        List<String> res = new ArrayList<>();
        if (num.isEmpty()) return res;
        backtrack(0, new StringBuilder(), 0, 0, num, target, res);
        return res;
    }

    private static void backtrack(int pos, StringBuilder path, long eval, long multed, String num, int target, List<String> res) {
        if (pos == num.length()) {
            if (eval == target) res.add(path.toString());
            return;
        }
        long cur = 0;
        for (int i = pos; i < num.length(); i++) {
            if (i != pos && num.charAt(pos) == ''0'') break;
            cur = cur * 10 + (num.charAt(i) - ''0'');
            int len = path.length();
            if (pos == 0) {
                path.append(cur);
                backtrack(i + 1, path, cur, cur, num, target, res);
                path.setLength(len);
            } else {
                path.append(''+'').append(cur);
                backtrack(i + 1, path, eval + cur, cur, num, target, res);
                path.setLength(len);

                path.append(''-'').append(cur);
                backtrack(i + 1, path, eval - cur, -cur, num, target, res);
                path.setLength(len);

                path.append(''*'').append(cur);
                backtrack(i + 1, path, eval - multed + multed * cur, multed * cur, num, target, res);
                path.setLength(len);
            }
        }
    }
}', 'O(4^N)', 'O(N)', '2026-11-20T06:28:30.587Z', '2026-11-20T06:28:30.587Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwc00kao76v5tki98eq', 'cmwolljwc00k9o76vvcv6xfya', 'BRUTE_FORCE', 'Brute Force Solution', '', 'class Node {
    int data;
    Node next;
    Node(int d) { data = d; next = null; }
}

public class Solution {
    public static Node constructLL(int[] arr) {
        if (arr.length == 0) return null;
        Node head = new Node(arr[0]), curr = head;
        for (int i = 1; i < arr.length; i++) {
            curr.next = new Node(arr[i]);
            curr = curr.next;
        }
        return head;
