INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljwf00kio76v9o19kfvc', 'cmwolljwf00kho76vcfvkugz2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node deleteNode(Node head, int position) {
        if (head == null) return null;
        if (position == 1) return head.next;
        Node curr = head;
        for (int i = 1; curr != null && i < position - 1; i++) {
            curr = curr.next;
        }
        if (curr == null || curr.next == null) return head;
        curr.next = curr.next.next;
        return head;
    }
