INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljww00mfo76vghrgvrvu', 'cmwolljww00mdo76vtbjq3ly2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
