INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx200n6o76vs0xi8wpq', 'cmwolljx200n5o76v7rdyf7ml', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static Node reverseDLL(Node head) {
        Stack<Integer> st = new Stack<>();
        Node curr = head;
        while (curr != null) { st.push(curr.data); curr = curr.next; }
        curr = head;
        while (curr != null) { curr.data = st.pop(); curr = curr.next; }
        return head;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.614Z', '2026-11-20T06:28:30.614Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx200n7o76vbnhvorcx', 'cmwolljx200n5o76v7rdyf7ml', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static Node reverseDLL(Node head) {
        if (head == null || head.next == null) return head;
        Node curr = head, prev = null;
        while (curr != null) {
            prev = curr.prev;
            curr.prev = curr.next;
            curr.next = prev;
            curr = curr.prev;
        }
        return prev.prev;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.614Z', '2026-11-20T06:28:30.614Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx300nao76vxnaegi1j', 'cmwolljx300n9o76vq94qnbnm', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0), curr = dummy;
        int carry = 0;
        while (l1 != null || l2 != null || carry != 0) {
            int sum = carry;
            if (l1 != null) { sum += l1.val; l1 = l1.next; }
            if (l2 != null) { sum += l2.val; l2 = l2.next; }
            carry = sum / 10;
            curr.next = new ListNode(sum % 10);
            curr = curr.next;
        }
        return dummy.next;
    }
}', 'O(max(N, M))', 'O(max(N, M))', '2026-11-20T06:28:30.615Z', '2026-11-20T06:28:30.615Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx300nbo76v5du4ulu5', 'cmwolljx300n9o76vq94qnbnm', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0), curr = dummy;
        int carry = 0;
        while (l1 != null || l2 != null || carry != 0) {
            int sum = carry;
            if (l1 != null) { sum += l1.val; l1 = l1.next; }
            if (l2 != null) { sum += l2.val; l2 = l2.next; }
            carry = sum / 10;
            curr.next = new ListNode(sum % 10);
            curr = curr.next;
        }
        return dummy.next;
    }
}', 'O(max(N, M))', 'O(max(N, M))', '2026-11-20T06:28:30.615Z', '2026-11-20T06:28:30.615Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx300neo76vi48n30sp', 'cmwolljx300ndo76vc0htiscv', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static ListNode oddEvenList(ListNode head) {
        if (head == null) return null;
        ArrayList<Integer> arr = new ArrayList<>();
        ListNode temp = head;
        while (temp != null) { arr.add(temp.val); if (temp.next != null) temp = temp.next.next; else break; }
        temp = head.next;
        while (temp != null) { arr.add(temp.val); if (temp.next != null) temp = temp.next.next; else break; }
        temp = head; int i = 0;
        while (temp != null) { temp.val = arr.get(i++); temp = temp.next; }
        return head;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.616Z', '2026-11-20T06:28:30.616Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx300nfo76vrt7fi3ji', 'cmwolljx300ndo76vc0htiscv', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode oddEvenList(ListNode head) {
        if (head == null || head.next == null) return head;
        ListNode odd = head, even = head.next, evenHead = even;
        while (even != null && even.next != null) {
            odd.next = even.next;
            odd = odd.next;
            even.next = odd.next;
            even = even.next;
        }
        odd.next = evenHead;
        return head;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.616Z', '2026-11-20T06:28:30.616Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx400nio76v3blu63k2', 'cmwolljx400nho76vbctb1g3w', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node segregate(Node head) {
        int c0 = 0, c1 = 0, c2 = 0;
        Node curr = head;
        while (curr != null) {
            if (curr.data == 0) c0++;
            else if (curr.data == 1) c1++;
            else c2++;
            curr = curr.next;
        }
        curr = head;
        while (c0-- > 0) { curr.data = 0; curr = curr.next; }
        while (c1-- > 0) { curr.data = 1; curr = curr.next; }
        while (c2-- > 0) { curr.data = 2; curr = curr.next; }
        return head;
    }
}', 'O(2N)', 'O(1)', '2026-11-20T06:28:30.616Z', '2026-11-20T06:28:30.616Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx400njo76vm0plwqc2', 'cmwolljx400nho76vbctb1g3w', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static Node segregate(Node head) {
        Node zeroD = new Node(0), oneD = new Node(0), twoD = new Node(0);
        Node zero = zeroD, one = oneD, two = twoD;
        Node curr = head;
        while (curr != null) {
            if (curr.data == 0) { zero.next = curr; zero = zero.next; }
            else if (curr.data == 1) { one.next = curr; one = one.next; }
            else { two.next = curr; two = two.next; }
            curr = curr.next;
        }
        zero.next = (oneD.next != null) ? oneD.next : twoD.next;
        one.next = twoD.next;
        two.next = null;
        return zeroD.next;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.616Z', '2026-11-20T06:28:30.616Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx500nmo76vluk4z44d', 'cmwolljx500nlo76vcc5e9g7d', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static ListNode removeNthFromEnd(ListNode head, int n) {
        int len = 0;
        ListNode temp = head;
        while (temp != null) { len++; temp = temp.next; }
        if (len == n) return head.next;
        temp = head;
        for (int i = 1; i < len - n; i++) temp = temp.next;
        temp.next = temp.next.next;
        return head;
    }
}', 'O(2N)', 'O(1)', '2026-11-20T06:28:30.617Z', '2026-11-20T06:28:30.617Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx500nno76vee3l1gsx', 'cmwolljx500nlo76vcc5e9g7d', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode fast = dummy, slow = dummy;
        for (int i = 0; i <= n; i++) fast = fast.next;
        while (fast != null) {
            fast = fast.next;
            slow = slow.next;
        }
        slow.next = slow.next.next;
        return dummy.next;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.617Z', '2026-11-20T06:28:30.617Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx500nqo76vnw89w553', 'cmwolljx500npo76v8qf5rt0m', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static ListNode reverseList(ListNode head) {
        if (head == null) return null;
        Stack<Integer> st = new Stack<>();
        ListNode temp = head;
        while (temp != null) { st.push(temp.val); temp = temp.next; }
        temp = head;
        while (temp != null) { temp.val = st.pop(); temp = temp.next; }
        return head;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.618Z', '2026-11-20T06:28:30.618Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx500nro76v63yz7nsj', 'cmwolljx500npo76v8qf5rt0m', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode reverseList(ListNode head) {
        ListNode prev = null, curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.618Z', '2026-11-20T06:28:30.618Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx600nuo76vzlr1fsjg', 'cmwolljx600nto76vtg1idgf0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node addOne(Node head) {
        head = reverse(head);
        Node curr = head;
        int carry = 1;
        while (curr != null) {
            int sum = curr.data + carry;
            curr.data = sum % 10;
            carry = sum / 10;
            if (curr.next == null && carry > 0) {
                curr.next = new Node(carry);
                carry = 0;
            }
            curr = curr.next;
        }
        return reverse(head);
    }

    private static Node reverse(Node head) {
        Node prev = null, curr = head;
        while (curr != null) {
            Node next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}', 'O(3N)', 'O(1)', '2026-11-20T06:28:30.619Z', '2026-11-20T06:28:30.619Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx600nvo76vshz8s929', 'cmwolljx600nto76vtg1idgf0', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static Node addOne(Node head) {
        int carry = helper(head);
        if (carry == 1) {
            Node newHead = new Node(1);
            newHead.next = head;
            return newHead;
        }
        return head;
    }

    private static int helper(Node temp) {
        if (temp == null) return 1;
        int carry = helper(temp.next);
        temp.data += carry;
        if (temp.data < 10) return 0;
        temp.data = 0;
        return 1;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.619Z', '2026-11-20T06:28:30.619Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx700nyo76vq0gixf7c', 'cmwolljx700nxo76v1666j015', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
