INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx800o2o76vrgdknytx', 'cmwolljx800o1o76v1h4ql050', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static ListNode deleteMiddle(ListNode head) {
        if (head == null || head.next == null) return null;
        int len = 0;
        ListNode temp = head;
        while (temp != null) { len++; temp = temp.next; }
        temp = head;
        for (int i = 0; i < (len / 2) - 1; i++) temp = temp.next;
        temp.next = temp.next.next;
        return head;
    }
}', 'O(N + N/2)', 'O(1)', '2026-11-20T06:28:30.620Z', '2026-11-20T06:28:30.620Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx800o3o76ven4a7qez', 'cmwolljx800o1o76v1h4ql050', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode deleteMiddle(ListNode head) {
        if (head == null || head.next == null) return null;
        ListNode slow = head, fast = head, prev = null;
        while (fast != null && fast.next != null) {
            prev = slow;
            slow = slow.next;
            fast = fast.next.next;
        }
        prev.next = slow.next;
        return head;
    }
}', 'O(N/2)', 'O(1)', '2026-11-20T06:28:30.620Z', '2026-11-20T06:28:30.620Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx900o6o76vvqz3lzk8', 'cmwolljx900o5o76v0sei8mla', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static boolean isPalindrome(ListNode head) {
        Stack<Integer> st = new Stack<>();
        ListNode temp = head;
        while (temp != null) { st.push(temp.val); temp = temp.next; }
        temp = head;
        while (temp != null) {
            if (temp.val != st.pop()) return false;
            temp = temp.next;
        }
        return true;
    }
}', 'O(2N)', 'O(N)', '2026-11-20T06:28:30.621Z', '2026-11-20T06:28:30.621Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx900o7o76v1wk9dqaf', 'cmwolljx900o5o76v0sei8mla', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isPalindrome(ListNode head) {
        if (head == null || head.next == null) return true;
        ListNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode secondHalf = reverse(slow.next);
        ListNode firstHalf = head;
        while (secondHalf != null) {
            if (firstHalf.val != secondHalf.val) return false;
            firstHalf = firstHalf.next;
            secondHalf = secondHalf.next;
        }
        return true;
    }

    private static ListNode reverse(ListNode head) {
        ListNode prev = null, curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}', 'O(2N)', 'O(1)', '2026-11-20T06:28:30.621Z', '2026-11-20T06:28:30.621Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx900oao76vb9zj6mez', 'cmwolljx900o9o76vba1e31lb', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        Set<ListNode> set = new HashSet<>();
        while (headA != null) { set.add(headA); headA = headA.next; }
        while (headB != null) {
            if (set.contains(headB)) return headB;
            headB = headB.next;
        }
        return null;
    }
}', 'O(N + M)', 'O(N)', '2026-11-20T06:28:30.622Z', '2026-11-20T06:28:30.622Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljx900obo76vuygccoj4', 'cmwolljx900o9o76vba1e31lb', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        if (headA == null || headB == null) return null;
        ListNode a = headA, b = headB;
        while (a != b) {
            a = (a == null) ? headB : a.next;
            b = (b == null) ? headA : b.next;
        }
        return a;
    }
}', 'O(2 * max(N, M))', 'O(1)', '2026-11-20T06:28:30.622Z', '2026-11-20T06:28:30.622Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxa00oeo76vx07ea10k', 'cmwolljxa00odo76vta8olkll', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static boolean hasCycle(ListNode head) {
        Set<ListNode> set = new HashSet<>();
        while (head != null) {
            if (set.contains(head)) return true;
            set.add(head);
            head = head.next;
        }
        return false;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.622Z', '2026-11-20T06:28:30.622Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxa00ofo76vi2fkclsj', 'cmwolljxa00odo76vta8olkll', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean hasCycle(ListNode head) {
        if (head == null) return false;
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.622Z', '2026-11-20T06:28:30.622Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxb00oio76vqn8mclsi', 'cmwolljxb00oho76viwfq4zzh', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static ListNode detectCycle(ListNode head) {
        Set<ListNode> set = new HashSet<>();
        while (head != null) {
            if (set.contains(head)) return head;
            set.add(head);
            head = head.next;
        }
        return null;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.623Z', '2026-11-20T06:28:30.623Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxb00ojo76vtgp8u1se', 'cmwolljxb00oho76viwfq4zzh', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode detectCycle(ListNode head) {
        if (head == null || head.next == null) return null;
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                slow = head;
                while (slow != fast) {
                    slow = slow.next;
                    fast = fast.next;
                }
                return slow;
            }
        }
        return null;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.623Z', '2026-11-20T06:28:30.623Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxc00omo76viwyvs6k3', 'cmwolljxc00olo76v8n6w4lew', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int countNodesinLoop(Node head) {
        Map<Node, Integer> map = new HashMap<>();
        Node temp = head;
        int timer = 0;
        while (temp != null) {
            if (map.containsKey(temp)) return timer - map.get(temp);
            map.put(temp, timer++);
            temp = temp.next;
        }
        return 0;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.624Z', '2026-11-20T06:28:30.624Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxc00ono76v5xvv1kkr', 'cmwolljxc00olo76v8n6w4lew', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countNodesinLoop(Node head) {
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                int count = 1;
                fast = fast.next;
                while (slow != fast) { count++; fast = fast.next; }
                return count;
            }
        }
        return 0;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.624Z', '2026-11-20T06:28:30.624Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxd00oqo76vx9x63bay', 'cmwolljxd00opo76vciz8566j', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static ListNode reverseKGroup(ListNode head, int k) {
        if (head == null || k == 1) return head;
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode curr = dummy, nex = dummy, pre = dummy;
        int count = 0;
        while (curr.next != null) { curr = curr.next; count++; }
        while (count >= k) {
            curr = pre.next;
            nex = curr.next;
            for (int i = 1; i < k; i++) {
                curr.next = nex.next;
                nex.next = pre.next;
                pre.next = nex;
                nex = curr.next;
            }
            pre = curr;
            count -= k;
        }
        return dummy.next;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.626Z', '2026-11-20T06:28:30.626Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxd00oro76vpnw8pv5v', 'cmwolljxd00opo76vciz8566j', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
