INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxf00ouo76v9syanydl', 'cmwolljxf00oto76vgnbdaffs', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0) return head;
        int len = 1;
        ListNode curr = head;
        while (curr.next != null) { len++; curr = curr.next; }
        k = k % len;
        if (k == 0) return head;
        curr.next = head;
        for (int i = 0; i < len - k; i++) curr = curr.next;
        head = curr.next;
        curr.next = null;
        return head;
    }
}', 'O(2N)', 'O(1)', '2026-11-20T06:28:30.627Z', '2026-11-20T06:28:30.627Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxf00ovo76vvz2vmii4', 'cmwolljxf00oto76vgnbdaffs', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
