INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxg00oyo76v5y6quuy7', 'cmwolljxg00oxo76vb9fblzod', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        ListNode dummy = new ListNode(0), curr = dummy;
        while (list1 != null && list2 != null) {
            if (list1.val <= list2.val) {
                curr.next = list1;
                list1 = list1.next;
            } else {
                curr.next = list2;
                list2 = list2.next;
            }
            curr = curr.next;
        }
        curr.next = (list1 != null) ? list1 : list2;
        return dummy.next;
    }
}', 'O(N + M)', 'O(1)', '2026-11-20T06:28:30.628Z', '2026-11-20T06:28:30.628Z') ON CONFLICT DO NOTHING;
