INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxh00p2o76v88a6pmn0', 'cmwolljxh00p1o76vm03l1cna', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    static class Node {
        int data;
        Node next, bottom;
        Node(int d) { data = d; next = null; bottom = null; }
    }

    public static Node flatten(Node root) {
        if (root == null || root.next == null) return root;
        root.next = flatten(root.next);
        root = merge(root, root.next);
        return root;
    }

    private static Node merge(Node a, Node b) {
        Node dummy = new Node(0), res = dummy;
        while (a != null && b != null) {
            if (a.data < b.data) { res.bottom = a; res = a; a = a.bottom; }
            else { res.bottom = b; res = b; b = b.bottom; }
        }
        if (a != null) res.bottom = a;
        else res.bottom = b;
        return dummy.bottom;
    }
}', 'O(N * M)', 'O(N)', '2026-11-20T06:28:30.630Z', '2026-11-20T06:28:30.630Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxh00p3o76v6blhwlqu', 'cmwolljxh00p1o76vm03l1cna', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    static class Node {
        int data;
        Node next, bottom;
        Node(int d) { data = d; next = null; bottom = null; }
    }

    public static Node flatten(Node root) {
        if (root == null || root.next == null) return root;
        root.next = flatten(root.next);
        root = merge(root, root.next);
        return root;
    }

    private static Node merge(Node a, Node b) {
        Node dummy = new Node(0), res = dummy;
        while (a != null && b != null) {
            if (a.data < b.data) { res.bottom = a; res = a; a = a.bottom; }
            else { res.bottom = b; res = b; b = b.bottom; }
        }
        if (a != null) res.bottom = a;
        else res.bottom = b;
        return dummy.bottom;
    }
}', 'O(N * M)', 'O(N)', '2026-11-20T06:28:30.630Z', '2026-11-20T06:28:30.630Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxj00p6o76vxiv1toxi', 'cmwolljxj00p5o76vn0fyfx6h', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static ListNode sortList(ListNode head) {
        List<Integer> list = new ArrayList<>();
        ListNode temp = head;
        while (temp != null) { list.add(temp.val); temp = temp.next; }
        Collections.sort(list);
        temp = head; int i = 0;
        while (temp != null) { temp.val = list.get(i++); temp = temp.next; }
        return head;
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.631Z', '2026-11-20T06:28:30.631Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxj00p7o76v7n61csgg', 'cmwolljxj00p5o76vn0fyfx6h', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;
        ListNode mid = getMid(head);
        ListNode right = mid.next;
        mid.next = null;
        ListNode leftSorted = sortList(head);
        ListNode rightSorted = sortList(right);
        return merge(leftSorted, rightSorted);
    }

    private static ListNode getMid(ListNode head) {
        ListNode slow = head, fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    private static ListNode merge(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0), curr = dummy;
        while (l1 != null && l2 != null) {
            if (l1.val <= l2.val) { curr.next = l1; l1 = l1.next; }
            else { curr.next = l2; l2 = l2.next; }
            curr = curr.next;
        }
        curr.next = (l1 != null) ? l1 : l2;
        return dummy.next;
    }
}', 'O(N log N)', 'O(log N)', '2026-11-20T06:28:30.631Z', '2026-11-20T06:28:30.631Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxk00pao76vn6pfyq5l', 'cmwolljxk00p9o76voxn4d3r0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

class Node {
    int val;
    Node next, random;
    Node(int val) { this.val = val; this.next = null; this.random = null; }
}

public class Solution {
    public static Node copyRandomList(Node head) {
        Map<Node, Node> map = new HashMap<>();
        Node curr = head;
        while (curr != null) {
            map.put(curr, new Node(curr.val));
            curr = curr.next;
        }
        curr = head;
        while (curr != null) {
            map.get(curr).next = map.get(curr.next);
            map.get(curr).random = map.get(curr.random);
            curr = curr.next;
        }
        return map.get(head);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.632Z', '2026-11-20T06:28:30.632Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxk00pbo76v3ei5gebu', 'cmwolljxk00p9o76voxn4d3r0', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static Node copyRandomList(Node head) {
        if (head == null) return null;
        Node curr = head;
        while (curr != null) {
            Node next = curr.next;
            Node copy = new Node(curr.val);
            curr.next = copy;
            copy.next = next;
            curr = next;
        }
        curr = head;
        while (curr != null) {
            if (curr.random != null) curr.next.random = curr.random.next;
            curr = curr.next.next;
        }
        curr = head;
        Node dummy = new Node(0), copyCurr = dummy;
        while (curr != null) {
            copyCurr.next = curr.next;
            copyCurr = copyCurr.next;
            curr.next = curr.next.next;
            curr = curr.next;
        }
        return dummy.next;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.632Z', '2026-11-20T06:28:30.632Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxl00peo76vd14v5850', 'cmwolljxl00pdo76vqycm2sgc', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
