        Node curr = head;
        while (curr != null) {
            if (curr.data == k) {
                if (curr == head) head = head.next;
                Node nextNode = curr.next;
                Node prevNode = curr.prev;
                if (nextNode != null) nextNode.prev = prevNode;
                if (prevNode != null) prevNode.next = nextNode;
                curr = nextNode;
            } else {
                curr = curr.next;
            }
        }
        return head;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.634Z', '2026-11-20T06:28:30.634Z') ON CONFLICT DO NOTHING;
