INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxn00pio76vgo1x2ofs', 'cmwolljxn00pho76vvl1jqmaa', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static Node removeDuplicates(Node head) {
