INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxo00pmo76v7e1mj3y9', 'cmwolljxo00plo76vd6vfnq2a', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<ArrayList<Integer>> findPairsWithGivenSum(int target, Node head) {
        ArrayList<ArrayList<Integer>> ans = new ArrayList<>();
        Node n1 = head;
        while (n1 != null) {
            Node n2 = n1.next;
            while (n2 != null && (n1.data + n2.data) <= target) {
                if (n1.data + n2.data == target) {
                    ArrayList<Integer> pair = new ArrayList<>();
                    pair.add(n1.data);
                    pair.add(n2.data);
                    ans.add(pair);
                }
                n2 = n2.next;
            }
            n1 = n1.next;
        }
        return ans;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.636Z', '2026-11-20T06:28:30.636Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxo00pno76v84wzyyxf', 'cmwolljxo00plo76vd6vfnq2a', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<ArrayList<Integer>> findPairsWithGivenSum(int target, Node head) {
        ArrayList<ArrayList<Integer>> ans = new ArrayList<>();
        if (head == null) return ans;
        Node left = head, right = head;
        while (right.next != null) right = right.next;
        while (left != null && right != null && left.data < right.data) {
            int sum = left.data + right.data;
            if (sum == target) {
                ArrayList<Integer> pair = new ArrayList<>();
                pair.add(left.data);
                pair.add(right.data);
                ans.add(pair);
                left = left.next;
                right = right.prev;
            } else if (sum < target) {
                left = left.next;
            } else {
                right = right.prev;
            }
        }
        return ans;
    }
}', 'O(2N)', 'O(1)', '2026-11-20T06:28:30.636Z', '2026-11-20T06:28:30.636Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxp00pqo76vaav24y1l', 'cmwolljxp00ppo76v2lll71gp', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
