INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxt00q2o76vrmmz6rsh', 'cmwolljxt00q1o76vy4xhsu0i', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
