INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxt00q3o76vpfvjdrjs', 'cmwolljxt00q1o76vy4xhsu0i', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
