INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxv00q6o76vm0j0pijw', 'cmwolljxv00q5o76vbau850qx', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int countSetBits(int n) {
        int count = 0;
        while (n > 0) {
            count += (n & 1);
            n >>= 1;
        }
        return count;
