INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxv00q7o76vafyz6jt1', 'cmwolljxv00q5o76vbau850qx', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countSetBits(int n) {
