INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxw00qao76vy4046qjb', 'cmwolljxw00q9o76vm7wtc30t', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int setBit(int n) {
        int temp = n, pos = 0;
        while ((temp & 1) != 0) {
            temp >>= 1;
            pos++;
        }
        return n | (1 << pos);
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.644Z', '2026-11-20T06:28:30.644Z') ON CONFLICT DO NOTHING;
