INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxx00qeo76vm07ua4lf', 'cmwolljxx00qdo76ve0u4l2e5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> get(int a, int b) {
        int temp = a;
        a = b;
        b = temp;
        List<Integer> list = new ArrayList<>();
        list.add(a);
        list.add(b);
        return list;
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.646Z', '2026-11-20T06:28:30.646Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxx00qfo76vjo13e1nj', 'cmwolljxx00qdo76ve0u4l2e5', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> get(int a, int b) {
        a = a ^ b;
        b = a ^ b;
        a = a ^ b;
        List<Integer> list = new ArrayList<>();
        list.add(a);
        list.add(b);
        return list;
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.646Z', '2026-11-20T06:28:30.646Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxy00qio76vjpgapnhn', 'cmwolljxy00qho76vujp5z5sl', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int minBitFlips(int start, int goal) {
        int xor = start ^ goal;
        int count = 0;
        while (xor > 0) {
            count += (xor & 1);
            xor >>= 1;
        }
        return count;
    }
}', 'O(log(start ^ goal))', 'O(1)', '2026-11-20T06:28:30.647Z', '2026-11-20T06:28:30.647Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljxy00qjo76vd9lfxxv1', 'cmwolljxy00qho76vujp5z5sl', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int minBitFlips(int start, int goal) {
        int xor = start ^ goal;
        int count = 0;
        while (xor > 0) {
            xor = xor & (xor - 1);
            count++;
        }
        return count;
    }
}', 'O(set bits)', 'O(1)', '2026-11-20T06:28:30.647Z', '2026-11-20T06:28:30.647Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy000qmo76vn39pk5bz', 'cmwolljy000qlo76vaa282sug', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int singleNumber(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() == 1) return entry.getKey();
        }
        return -1;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.648Z', '2026-11-20T06:28:30.648Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy000qno76v40fpgzj2', 'cmwolljy000qlo76vaa282sug', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int singleNumber(int[] nums) {
        int xor = 0;
        for (int num : nums) xor ^= num;
        return xor;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.648Z', '2026-11-20T06:28:30.648Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy100qqo76vfmr8o9l1', 'cmwolljy100qpo76v91npumf4', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int singleNumber(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() == 1) return entry.getKey();
        }
        return -1;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.649Z', '2026-11-20T06:28:30.649Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy100qro76v2hgjla2w', 'cmwolljy100qpo76v91npumf4', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int singleNumber(int[] nums) {
        int ones = 0, twos = 0;
        for (int num : nums) {
            ones = (ones ^ num) & ~twos;
            twos = (twos ^ num) & ~ones;
        }
        return ones;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.649Z', '2026-11-20T06:28:30.649Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy200quo76vh5pt21sp', 'cmwolljy200qto76v9anpe9ph', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int[] singleNumber(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int x : nums) map.put(x, map.getOrDefault(x, 0) + 1);
        int[] res = new int[2];
        int idx = 0;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() == 1) res[idx++] = entry.getKey();
        }
        return res;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.651Z', '2026-11-20T06:28:30.651Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy200qvo76vfw2pyyla', 'cmwolljy200qto76v9anpe9ph', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int[] singleNumber(int[] nums) {
        long xor = 0;
        for (int num : nums) xor ^= num;
        long rightmost = xor & -xor;
        int b1 = 0, b2 = 0;
        for (int num : nums) {
            if ((num & rightmost) != 0) b1 ^= num;
            else b2 ^= num;
        }
        return new int[]{b1, b2};
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.651Z', '2026-11-20T06:28:30.651Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy400qyo76vyxda3dvu', 'cmwolljy400qxo76v98a7mnv4', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int divide(int dividend, int divisor) {
        if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;
        long count = 0;
        long a = Math.abs((long) dividend);
        long b = Math.abs((long) divisor);
        while (a >= b) {
            a -= b;
            count++;
        }
        boolean sign = (dividend < 0) ^ (divisor < 0);
        return (int) (sign ? -count : count);
    }
}', 'O(dividend / divisor)', 'O(1)', '2026-11-20T06:28:30.652Z', '2026-11-20T06:28:30.652Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy400qzo76vyrmatikx', 'cmwolljy400qxo76v98a7mnv4', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int divide(int dividend, int divisor) {
        if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;
        boolean sign = (dividend < 0) ^ (divisor < 0);
        long n = Math.abs((long) dividend);
        long d = Math.abs((long) divisor);
        long ans = 0;
        while (n >= d) {
            int count = 0;
            while (n >= (d << (count + 1))) count++;
            ans += (1L << count);
            n -= (d << count);
        }
        return (int) (sign ? -ans : ans);
    }
}', 'O((log N)²)', 'O(1)', '2026-11-20T06:28:30.652Z', '2026-11-20T06:28:30.652Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy500r2o76vsn8566a7', 'cmwolljy500r1o76vb4qy8bbq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> ans = new ArrayList<>();
        int n = nums.length;
        for (int i = 0; i < (1 << n); i++) {
            List<Integer> sub = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) sub.add(nums[j]);
            }
            ans.add(sub);
        }
        return ans;
    }
}', 'O(N * 2^N)', 'O(2^N)', '2026-11-20T06:28:30.653Z', '2026-11-20T06:28:30.653Z') ON CONFLICT DO NOTHING;
