INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy600r6o76vya0pekr6', 'cmwolljy600r5o76vrkquy1c9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findXOR(int l, int r) {
        int xor = 0;
        for (int i = l; i <= r; i++) xor ^= i;
        return xor;
    }
