INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy600r7o76v6wuhcwap', 'cmwolljy600r5o76vrkquy1c9', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findXOR(int l, int r) {
        return xorTill(r) ^ xorTill(l - 1);
    }

    private static int xorTill(int n) {
        if (n % 4 == 1) return 1;
        if (n % 4 == 2) return n + 1;
        if (n % 4 == 3) return 0;
        return n;
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.655Z', '2026-11-20T06:28:30.655Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy800rao76vtmixc8z9', 'cmwolljy800r9o76ve89jkb19', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int findContentChildren(int[] g, int[] s) {
        Arrays.sort(g);
        Arrays.sort(s);
        int i = 0, j = 0;
        while (i < g.length && j < s.length) {
            if (s[j] >= g[i]) i++;
            j++;
        }
        return i;
    }
}', 'O(N log N + M log M)', 'O(1)', '2026-11-20T06:28:30.656Z', '2026-11-20T06:28:30.656Z') ON CONFLICT DO NOTHING;
