INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljy900reo76v5dn2z65k', 'cmwolljy900rdo76vrnsf9bz5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean lemonadeChange(int[] bills) {
        int five = 0, ten = 0;
        for (int bill : bills) {
            if (bill == 5) {
                five++;
            } else if (bill == 10) {
                if (five == 0) return false;
                five--;
                ten++;
            } else {
                if (ten > 0 && five > 0) {
                    ten--;
                    five--;
                } else if (five >= 3) {
                    five -= 3;
                } else {
                    return false;
                }
            }
        }
        return true;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.657Z', '2026-11-20T06:28:30.657Z') ON CONFLICT DO NOTHING;
