INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyb00rio76v4wl6h553', 'cmwolljyb00rho76vczj47a98', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

class Item {
    int value, weight;
    Item(int x, int y){ this.value = x; this.weight = y; }
}

public class Solution {
    public static double fractionalKnapsack(int w, Item[] arr, int n) {
        Arrays.sort(arr, (a, b) -> Double.compare((double) b.value / b.weight, (double) a.value / a.weight));
        double totalValue = 0.0;
        for (Item item : arr) {
            if (item.weight <= w) {
                w -= item.weight;
                totalValue += item.value;
            } else {
                totalValue += ((double) item.value / item.weight) * w;
                break;
            }
        }
        return totalValue;
    }
}', 'O(N log N)', 'O(1)', '2026-11-20T06:28:30.659Z', '2026-11-20T06:28:30.659Z') ON CONFLICT DO NOTHING;
