INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyc00rmo76vmissnvcl', 'cmwolljyc00rlo76vzn85oxfu', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean canJump(int[] nums) {
        return canReach(nums, 0);
    }

    private static boolean canReach(int[] nums, int index) {
        if (index >= nums.length - 1) return true;
        int maxJump = nums[index];
        for (int i = 1; i <= maxJump; i++) {
            if (canReach(nums, index + i)) return true;
        }
        return false;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.660Z', '2026-11-20T06:28:30.660Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyc00rno76v1uqlmn8a', 'cmwolljyc00rlo76vzn85oxfu', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean canJump(int[] nums) {
        int maxReach = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > maxReach) return false;
            maxReach = Math.max(maxReach, i + nums[i]);
        }
        return true;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.660Z', '2026-11-20T06:28:30.660Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyd00rqo76va1vm7hp1', 'cmwolljyd00rpo76vo94w5icq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static long solve(int[] bt) {
        Arrays.sort(bt);
        long waitTime = 0, totalTime = 0;
        for (int t : bt) {
            waitTime += totalTime;
            totalTime += t;
        }
        return waitTime / bt.length;
    }
}', 'O(N log N)', 'O(1)', '2026-11-20T06:28:30.662Z', '2026-11-20T06:28:30.662Z') ON CONFLICT DO NOTHING;
