INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljye00ruo76vu8mu6e37', 'cmwolljye00rto76vldjoe0m9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

class Job {
    int id, profit, deadline;
    Job(int x, int y, int z){ this.id = x; this.deadline = y; this.profit = z; }
}

public class Solution {
    public static int[] JobScheduling(Job[] arr, int n) {
        Arrays.sort(arr, (a, b) -> b.profit - a.profit);
        int maxDeadline = 0;
        for (Job j : arr) maxDeadline = Math.max(maxDeadline, j.deadline);
        int[] result = new int[maxDeadline + 1];
        Arrays.fill(result, -1);
        int count = 0, totalProfit = 0;
        for (Job j : arr) {
            for (int k = j.deadline; k > 0; k--) {
                if (result[k] == -1) {
                    result[k] = j.id;
                    count++;
                    totalProfit += j.profit;
                    break;
                }
            }
        }
        return new int[]{count, totalProfit};
    }
}', 'O(N log N + N * maxDeadline)', 'O(maxDeadline)', '2026-11-20T06:28:30.663Z', '2026-11-20T06:28:30.663Z') ON CONFLICT DO NOTHING;
