INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyg00ryo76v8qm3t3lw', 'cmwolljyg00rxo76vm9jczh1z', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

class Meeting {
    int start, end;
    Meeting(int s, int e) { this.start = s; this.end = e; }
}

public class Solution {
    public static int maxMeetings(int[] start, int[] end, int n) {
        List<Meeting> list = new ArrayList<>();
        for (int i = 0; i < n; i++) list.add(new Meeting(start[i], end[i]));
        list.sort(Comparator.comparingInt(a -> a.end));
        int count = 1, limit = list.get(0).end;
        for (int i = 1; i < n; i++) {
            if (list.get(i).start > limit) {
                count++;
                limit = list.get(i).end;
            }
        }
        return count;
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.664Z', '2026-11-20T06:28:30.664Z') ON CONFLICT DO NOTHING;
