INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyh00s2o76vrfrhyoku', 'cmwolljyh00s1o76vc5dha2g6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public static int eraseOverlapIntervals(int[][] intervals) {
        if (intervals.length == 0) return 0;
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[1]));
        int count = 1, end = intervals[0][1];
        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] >= end) {
                count++;
                end = intervals[i][1];
            }
        }
        return intervals.length - count;
    }
}', 'O(N log N)', 'O(1)', '2026-11-20T06:28:30.665Z', '2026-11-20T06:28:30.665Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyh00s3o76ves4vxszn', 'cmwolljyh00s1o76vc5dha2g6', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public static int eraseOverlapIntervals(int[][] intervals) {
