INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyi00s6o76v5gze2t9j', 'cmwolljyi00s5o76vnzgfhc2f', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[][] insert(int[][] intervals, int[] newInterval) {
        List<int[]> list = new ArrayList<>(Arrays.asList(intervals));
        list.add(newInterval);
        list.sort(Comparator.comparingInt(a -> a[0]));
        List<int[]> merged = new ArrayList<>();
        for (int[] interval : list) {
            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {
                merged.add(interval);
            } else {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);
            }
        }
        return merged.toArray(new int[merged.size()][]);
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.667Z', '2026-11-20T06:28:30.667Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyi00s7o76vfwac2oju', 'cmwolljyi00s5o76vnzgfhc2f', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static int[][] insert(int[][] intervals, int[] newInterval) {
        List<int[]> result = new ArrayList<>();
        int i = 0, n = intervals.length;
        while (i < n && intervals[i][1] < newInterval[0]) {
            result.add(intervals[i++]);
        }
        while (i < n && intervals[i][0] <= newInterval[1]) {
            newInterval[0] = Math.min(newInterval[0], intervals[i][0]);
            newInterval[1] = Math.max(newInterval[1], intervals[i][1]);
            i++;
        }
        result.add(newInterval);
        while (i < n) {
            result.add(intervals[i++]);
        }
        return result.toArray(new int[result.size()][]);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.667Z', '2026-11-20T06:28:30.667Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyk00sao76vafqxr762', 'cmwolljyk00s9o76vi0ccdwwd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
        List<int[]> ans = new ArrayList<>();
        int n = intervals.length;
        for (int i = 0; i < n; i++) {
            int start = intervals[i][0], end = intervals[i][1];
            if (!ans.isEmpty() && end <= ans.get(ans.size() - 1)[1]) continue;
            for (int j = i + 1; j < n; j++) {
                if (intervals[j][0] <= end) end = Math.max(end, intervals[j][1]);
                else break;
            }
            ans.add(new int[]{start, end});
        }
        return ans.toArray(new int[ans.size()][]);
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.668Z', '2026-11-20T06:28:30.668Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyk00sbo76vaa9a6ghy', 'cmwolljyk00s9o76vi0ccdwwd', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
        List<int[]> merged = new ArrayList<>();
        for (int[] interval : intervals) {
            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {
                merged.add(interval);
            } else {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);
            }
        }
        return merged.toArray(new int[merged.size()][]);
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.668Z', '2026-11-20T06:28:30.668Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyl00seo76vcfjlci22', 'cmwolljyl00sdo76v19wcfqkb', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findPlatform(int[] arr, int[] dep, int n) {
        int maxPlat = 1;
        for (int i = 0; i < n; i++) {
            int plat = 1;
            for (int j = 0; j < n; j++) {
                if (i != j && arr[i] >= arr[j] && dep[j] >= arr[i]) plat++;
            }
            maxPlat = Math.max(maxPlat, plat);
        }
        return maxPlat;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.669Z', '2026-11-20T06:28:30.669Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyl00sfo76v3rs39ws1', 'cmwolljyl00sdo76v19wcfqkb', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int findPlatform(int[] arr, int[] dep, int n) {
        Arrays.sort(arr);
        Arrays.sort(dep);
        int plat = 1, maxPlat = 1;
        int i = 1, j = 0;
        while (i < n && j < n) {
            if (arr[i] <= dep[j]) {
                plat++;
                i++;
            } else {
                plat--;
                j++;
            }
            maxPlat = Math.max(maxPlat, plat);
        }
        return maxPlat;
    }
}', 'O(N log N)', 'O(1)', '2026-11-20T06:28:30.669Z', '2026-11-20T06:28:30.669Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljym00sio76vhacpo2ih', 'cmwolljym00sho76vzqdex4o5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean checkValidString(String s) {
        return isValid(s, 0, 0);
    }

    private static boolean isValid(String s, int index, int count) {
        if (count < 0) return false;
        if (index == s.length()) return count == 0;
        char c = s.charAt(index);
        if (c == ''('') return isValid(s, index + 1, count + 1);
        if (c == '')'') return isValid(s, index + 1, count - 1);
        return isValid(s, index + 1, count + 1) || isValid(s, index + 1, count - 1) || isValid(s, index + 1, count);
    }
}', 'O(3^N)', 'O(N)', '2026-11-20T06:28:30.671Z', '2026-11-20T06:28:30.671Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljym00sjo76v8zhocrwt', 'cmwolljym00sho76vzqdex4o5', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean checkValidString(String s) {
        int minOpen = 0, maxOpen = 0;
        for (char c : s.toCharArray()) {
            if (c == ''('') {
                minOpen++;
                maxOpen++;
            } else if (c == '')'') {
                minOpen--;
                maxOpen--;
            } else {
                minOpen--;
                maxOpen++;
            }
            if (maxOpen < 0) return false;
            minOpen = Math.max(minOpen, 0);
        }
        return minOpen == 0;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.671Z', '2026-11-20T06:28:30.671Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyn00smo76v0x2dcco4', 'cmwolljyn00slo76v809x1xe6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int candy(int[] ratings) {
        int n = ratings.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Arrays.fill(left, 1);
        Arrays.fill(right, 1);
        for (int i = 1; i < n; i++) {
            if (ratings[i] > ratings[i - 1]) left[i] = left[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {
            if (ratings[i] > ratings[i + 1]) right[i] = right[i + 1] + 1;
        }
        int total = 0;
        for (int i = 0; i < n; i++) total += Math.max(left[i], right[i]);
        return total;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.672Z', '2026-11-20T06:28:30.672Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyn00sno76v5y4jw5ju', 'cmwolljyn00slo76v809x1xe6', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int candy(int[] ratings) {
        int n = ratings.length;
        int sum = 1, i = 1;
        while (i < n) {
            if (ratings[i] == ratings[i - 1]) {
                sum++;
                i++;
                continue;
            }
            int peak = 1;
            while (i < n && ratings[i] > ratings[i - 1]) {
                peak++;
                sum += peak;
                i++;
            }
            int down = 1;
            while (i < n && ratings[i] < ratings[i - 1]) {
                sum += down;
                down++;
                i++;
            }
            if (down > peak) sum += (down - peak);
        }
        return sum;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.672Z', '2026-11-20T06:28:30.672Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyp00sqo76v6k3fgteb', 'cmwolljyp00spo76v4orolvl2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int jump(int[] nums) {
        int[] dp = new int[nums.length];
        java.util.Arrays.fill(dp, 100000);
        dp[0] = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = 1; j <= nums[i] && i + j < nums.length; j++) {
                dp[i + j] = Math.min(dp[i + j], dp[i] + 1);
            }
        }
        return dp[nums.length - 1];
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.673Z', '2026-11-20T06:28:30.673Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyp00sro76vsnwfgk6j', 'cmwolljyp00spo76v4orolvl2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int jump(int[] nums) {
        int jumps = 0, currentEnd = 0, farthest = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == currentEnd) {
                jumps++;
                currentEnd = farthest;
            }
        }
        return jumps;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.673Z', '2026-11-20T06:28:30.673Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyq00suo76vwnvj050x', 'cmwolljyq00sto76vbaturc2m', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int fixedWindowSum(int[] nums, int k) {
        // Standard sliding window demonstration
        int sum = 0;
        for (int i = 0; i < k; i++) sum += nums[i];
        int maxSum = sum;
        for (int i = k; i < nums.length; i++) {
            sum += nums[i] - nums[i - k];
            maxSum = Math.max(maxSum, sum);
        }
        return maxSum;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.675Z', '2026-11-20T06:28:30.675Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyq00svo76v2cpdgt7l', 'cmwolljyq00sto76vbaturc2m', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
