INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljys00syo76v818vb1wa', 'cmwolljys00sxo76vlgng2xxx', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int maxScore(int[] cardPoints, int k) {
        int lSum = 0, rSum = 0, maxSum = 0;
        for (int i = 0; i < k; i++) lSum += cardPoints[i];
        maxSum = lSum;
        int rightIndex = cardPoints.length - 1;
        for (int i = k - 1; i >= 0; i--) {
            lSum -= cardPoints[i];
            rSum += cardPoints[rightIndex--];
            maxSum = Math.max(maxSum, lSum + rSum);
        }
        return maxSum;
    }
}', 'O(2K)', 'O(1)', '2026-11-20T06:28:30.676Z', '2026-11-20T06:28:30.676Z') ON CONFLICT DO NOTHING;
