INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyt00t2o76vn5xt1i2t', 'cmwolljyt00t1o76v2kxic8i7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static int lengthOfLongestSubstring(String s) {
        int max = 0;
        for (int i = 0; i < s.length(); i++) {
            Set<Character> set = new HashSet<>();
            for (int j = i; j < s.length(); j++) {
                if (set.contains(s.charAt(j))) break;
                set.add(s.charAt(j));
                max = Math.max(max, j - i + 1);
            }
        }
        return max;
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.677Z', '2026-11-20T06:28:30.677Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyt00t3o76ve5y08z7j', 'cmwolljyt00t1o76v2kxic8i7', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> map = new HashMap<>();
        int left = 0, max = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (map.containsKey(c)) {
                left = Math.max(left, map.get(c) + 1);
            }
            map.put(c, right);
            max = Math.max(max, right - left + 1);
        }
        return max;
    }
}', 'O(N)', 'O(min(N, 256))', '2026-11-20T06:28:30.677Z', '2026-11-20T06:28:30.677Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyu00t6o76v0btbg0w9', 'cmwolljyu00t5o76v2tyv2d2i', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int longestOnes(int[] nums, int k) {
        int max = 0;
        for (int i = 0; i < nums.length; i++) {
            int zeros = 0;
            for (int j = i; j < nums.length; j++) {
                if (nums[j] == 0) zeros++;
                if (zeros <= k) max = Math.max(max, j - i + 1);
                else break;
            }
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.679Z', '2026-11-20T06:28:30.679Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyu00t7o76voomf4esk', 'cmwolljyu00t5o76v2tyv2d2i', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int longestOnes(int[] nums, int k) {
        int left = 0, zeros = 0, max = 0;
        for (int right = 0; right < nums.length; right++) {
            if (nums[right] == 0) zeros++;
            while (zeros > k) {
                if (nums[left] == 0) zeros--;
                left++;
            }
            max = Math.max(max, right - left + 1);
        }
        return max;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.679Z', '2026-11-20T06:28:30.679Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyv00tao76vt8k5xndk', 'cmwolljyv00t9o76v4vauxdhs', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static int totalFruits(int[] fruits) {
        int max = 0;
        for (int i = 0; i < fruits.length; i++) {
            Set<Integer> set = new HashSet<>();
            for (int j = i; j < fruits.length; j++) {
                set.add(fruits[j]);
                if (set.size() <= 2) max = Math.max(max, j - i + 1);
                else break;
            }
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.680Z', '2026-11-20T06:28:30.680Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyv00tbo76v3oqx8bm9', 'cmwolljyv00t9o76v4vauxdhs', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int totalFruits(int[] fruits) {
        Map<Integer, Integer> map = new HashMap<>();
        int left = 0, max = 0;
        for (int right = 0; right < fruits.length; right++) {
            map.put(fruits[right], map.getOrDefault(fruits[right], 0) + 1);
            while (map.size() > 2) {
                map.put(fruits[left], map.get(fruits[left]) - 1);
                if (map.get(fruits[left]) == 0) map.remove(fruits[left]);
                left++;
            }
            max = Math.max(max, right - left + 1);
        }
        return max;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.680Z', '2026-11-20T06:28:30.680Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyx00teo76vpz08sqow', 'cmwolljyx00tdo76v8bboaiu5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static int kDistinctChars(int k, String s) {
        int max = 0;
        for (int i = 0; i < s.length(); i++) {
            Set<Character> set = new HashSet<>();
            for (int j = i; j < s.length(); j++) {
                set.add(s.charAt(j));
                if (set.size() <= k) max = Math.max(max, j - i + 1);
                else break;
            }
        }
        return max;
    }
}', 'O(N²)', 'O(K)', '2026-11-20T06:28:30.681Z', '2026-11-20T06:28:30.681Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyx00tfo76vw17ca7nq', 'cmwolljyx00tdo76v8bboaiu5', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int kDistinctChars(int k, String s) {
        Map<Character, Integer> map = new HashMap<>();
        int left = 0, max = 0;
        for (int right = 0; right < s.length(); right++) {
            map.put(s.charAt(right), map.getOrDefault(s.charAt(right), 0) + 1);
            while (map.size() > k) {
                map.put(s.charAt(left), map.get(s.charAt(left)) - 1);
                if (map.get(s.charAt(left)) == 0) map.remove(s.charAt(left));
                left++;
            }
            max = Math.max(max, right - left + 1);
        }
        return max;
    }
}', 'O(N)', 'O(K)', '2026-11-20T06:28:30.681Z', '2026-11-20T06:28:30.681Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzh00vro76vkgluuhje', 'cmwolljzh00vpo76v6sf7glzk', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static String postToPre(String post_exp) {
        Stack<String> s = new Stack<>();
        for (char c : post_exp.toCharArray()) {
            if (Character.isLetterOrDigit(c)) {
                s.push(c + "");
            } else {
                String op2 = s.pop();
                String op1 = s.pop();
                s.push(c + op1 + op2);
            }
        }
        return s.peek();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.701Z', '2026-11-20T06:28:30.701Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyy00tio76vkfnm282j', 'cmwolljyy00tho76v33zhnhxf', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int characterReplacement(String s, int k) {
        int max = 0;
        for (int i = 0; i < s.length(); i++) {
            int[] count = new int[26];
            int maxFreq = 0;
            for (int j = i; j < s.length(); j++) {
                count[s.charAt(j) - ''A'']++;
                maxFreq = Math.max(maxFreq, count[s.charAt(j) - ''A'']);
                int changes = (j - i + 1) - maxFreq;
                if (changes <= k) max = Math.max(max, j - i + 1);
                else break;
            }
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.682Z', '2026-11-20T06:28:30.682Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyy00tjo76vftmp5ilw', 'cmwolljyy00tho76v33zhnhxf', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int characterReplacement(String s, int k) {
        int[] count = new int[26];
        int left = 0, maxFreq = 0, max = 0;
        for (int right = 0; right < s.length(); right++) {
            count[s.charAt(right) - ''A'']++;
            maxFreq = Math.max(maxFreq, count[s.charAt(right) - ''A'']);
            if ((right - left + 1) - maxFreq > k) {
                count[s.charAt(left) - ''A'']--;
                left++;
            }
            max = Math.max(max, right - left + 1);
        }
        return max;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.682Z', '2026-11-20T06:28:30.682Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyz00tmo76vsyxoukof', 'cmwolljyz00tlo76vc7mpbvf0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static String minWindow(String s, String t) {
        if (s.length() < t.length()) return "";
        Map<Character, Integer> tMap = new HashMap<>();
        for (char c : t.toCharArray()) tMap.put(c, tMap.getOrDefault(c, 0) + 1);

        String minStr = "";
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            Map<Character, Integer> sMap = new HashMap<>();
            for (int j = i; j < s.length(); j++) {
                sMap.put(s.charAt(j), sMap.getOrDefault(s.charAt(j), 0) + 1);
                boolean containsAll = true;
                for (char key : tMap.keySet()) {
                    if (sMap.getOrDefault(key, 0) < tMap.get(key)) {
                        containsAll = false;
                        break;
                    }
                }
                if (containsAll && (j - i + 1) < minLen) {
                    minLen = j - i + 1;
                    minStr = s.substring(i, j + 1);
                    break;
                }
            }
        }
        return minStr;
    }
}', 'O(N²)', 'O(N + M)', '2026-11-20T06:28:30.684Z', '2026-11-20T06:28:30.684Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljyz00tno76vdcy8w52z', 'cmwolljyz00tlo76vc7mpbvf0', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static String minWindow(String s, String t) {
        int[] map = new int[128];
        for (char c : t.toCharArray()) map[c]++;
        int count = t.length(), left = 0, minLen = Integer.MAX_VALUE, start = 0;
        for (int right = 0; right < s.length(); right++) {
            if (map[s.charAt(right)]-- > 0) count--;
            while (count == 0) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    start = left;
                }
                if (++map[s.charAt(left++)] > 0) count++;
            }
        }
        return minLen == Integer.MAX_VALUE ? "" : s.substring(start, start + minLen);
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.684Z', '2026-11-20T06:28:30.684Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz100tqo76v2vliri2s', 'cmwolljz100tpo76v7i0lozg0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String minWindow(String s1, String s2) {
        String ans = "";
        int minLen = Integer.MAX_VALUE;
        int m = s1.length(), n = s2.length();
        int j = 0;
        for (int i = 0; i < m; i++) {
            if (s1.charAt(i) == s2.charAt(j)) {
                j++;
                if (j == n) {
                    int end = i + 1;
                    j--;
                    while (j >= 0) {
                        if (s1.charAt(i) == s2.charAt(j)) j--;
                        i--;
                    }
                    i++;
                    j++;
                    if (end - i < minLen) {
                        minLen = end - i;
                        ans = s1.substring(i, end);
                    }
                }
            }
        }
        return ans;
    }
}', 'O(M * N)', 'O(1)', '2026-11-20T06:28:30.685Z', '2026-11-20T06:28:30.685Z') ON CONFLICT DO NOTHING;
