INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz200tuo76vn7992obx', 'cmwolljz200tto76vtu2ycjak', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int numberOfSubstrings(String s) {
        int count = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            int[] seen = new int[3];
            for (int j = i; j < n; j++) {
                seen[s.charAt(j) - ''a''] = 1;
                if (seen[0] + seen[1] + seen[2] == 3) {
                    count += (n - j);
                    break;
                }
            }
        }
        return count;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.686Z', '2026-11-20T06:28:30.686Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1g012fo76vfbj5c81k', 'cmwollk1g012do76vn54tn8b1', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static TreeNode inorderSuccessor(TreeNode root, TreeNode p) {
        TreeNode successor = null;
        while (root != null) {
            if (p.val >= root.val) {
                root = root.right;
            } else {
                successor = root;
                root = root.left;
            }
        }
        return successor;
    }
}', 'O(H)', 'O(1)', '2026-11-20T06:28:30.772Z', '2026-11-20T06:28:30.772Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz200tvo76vxjo211tr', 'cmwolljz200tto76vtu2ycjak', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int numberOfSubstrings(String s) {
        int[] lastSeen = {-1, -1, -1};
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            lastSeen[s.charAt(i) - ''a''] = i;
            if (lastSeen[0] != -1 && lastSeen[1] != -1 && lastSeen[2] != -1) {
                count += 1 + Math.min(lastSeen[0], Math.min(lastSeen[1], lastSeen[2]));
            }
        }
        return count;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.686Z', '2026-11-20T06:28:30.686Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz300tyo76vnfkenzqh', 'cmwolljz300txo76vs8posyuj', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int numSubarraysWithSum(int[] nums, int goal) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int sum = 0;
            for (int j = i; j < nums.length; j++) {
                sum += nums[j];
                if (sum == goal) count++;
                else if (sum > goal) break;
            }
        }
        return count;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.688Z', '2026-11-20T06:28:30.688Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz300tzo76vgfs2x334', 'cmwolljz300txo76vs8posyuj', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int numSubarraysWithSum(int[] nums, int goal) {
        return atMost(nums, goal) - atMost(nums, goal - 1);
    }

    private static int atMost(int[] nums, int goal) {
        if (goal < 0) return 0;
        int left = 0, sum = 0, count = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (sum > goal) {
                sum -= nums[left++];
            }
            count += (right - left + 1);
        }
        return count;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.688Z', '2026-11-20T06:28:30.688Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz400u2o76vdmtga4x3', 'cmwolljz400u1o76vq3sqtj2m', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int numberOfSubarrays(int[] nums, int k) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int odds = 0;
            for (int j = i; j < nums.length; j++) {
                if (nums[j] % 2 != 0) odds++;
                if (odds == k) count++;
                else if (odds > k) break;
            }
        }
        return count;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.689Z', '2026-11-20T06:28:30.689Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz400u3o76votmdx5r0', 'cmwolljz400u1o76vq3sqtj2m', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int numberOfSubarrays(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    private static int atMost(int[] nums, int k) {
        if (k < 0) return 0;
        int left = 0, count = 0, odds = 0;
        for (int right = 0; right < nums.length; right++) {
            if (nums[right] % 2 != 0) odds++;
            while (odds > k) {
                if (nums[left++] % 2 != 0) odds--;
            }
            count += (right - left + 1);
        }
        return count;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.689Z', '2026-11-20T06:28:30.689Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz600u6o76vooiuiopk', 'cmwolljz600u5o76v2w5ge6x3', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static int subarraysWithKDistinct(int[] nums, int k) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            Set<Integer> set = new HashSet<>();
            for (int j = i; j < nums.length; j++) {
                set.add(nums[j]);
                if (set.size() == k) count++;
                else if (set.size() > k) break;
            }
        }
        return count;
    }
}', 'O(N²)', 'O(K)', '2026-11-20T06:28:30.690Z', '2026-11-20T06:28:30.690Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz600u7o76vmsk1rpvq', 'cmwolljz600u5o76v2w5ge6x3', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int subarraysWithKDistinct(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    private static int atMost(int[] nums, int k) {
        if (k <= 0) return 0;
        Map<Integer, Integer> map = new HashMap<>();
        int left = 0, count = 0;
        for (int right = 0; right < nums.length; right++) {
            map.put(nums[right], map.getOrDefault(nums[right], 0) + 1);
            while (map.size() > k) {
                map.put(nums[left], map.get(nums[left]) - 1);
                if (map.get(nums[left]) == 0) map.remove(nums[left]);
                left++;
            }
            count += (right - left + 1);
        }
        return count;
    }
}', 'O(N)', 'O(K)', '2026-11-20T06:28:30.690Z', '2026-11-20T06:28:30.690Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz600uao76vvkk89038', 'cmwolljz600u9o76vnly61wpz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
