INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz800uio76vz893ltz4', 'cmwolljz800uho76vdji7oytx', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
