INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz900umo76vor5yczj9', 'cmwolljz900ulo76vasinfbuv', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    static class MyStack {
        Queue<Integer> q1 = new LinkedList<>();
        Queue<Integer> q2 = new LinkedList<>();

        public void push(int x) {
            q2.add(x);
            while (!q1.isEmpty()) q2.add(q1.remove());
            Queue<Integer> temp = q1;
            q1 = q2;
            q2 = temp;
        }

        public int pop() { return q1.remove(); }
        public int top() { return q1.peek(); }
        public boolean empty() { return q1.isEmpty(); }
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.693Z', '2026-11-20T06:28:30.693Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljz900uno76vu338nwfy', 'cmwolljz900ulo76vasinfbuv', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    static class MyStack {
        Queue<Integer> q = new LinkedList<>();

        public void push(int x) {
            q.add(x);
            for (int i = 0; i < q.size() - 1; i++) {
                q.add(q.remove());
            }
        }

        public int pop() { return q.remove(); }
        public int top() { return q.peek(); }
        public boolean empty() { return q.isEmpty(); }
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.693Z', '2026-11-20T06:28:30.693Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljza00uqo76vl43o3pt1', 'cmwolljza00upo76vg0zzagpq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    static class MyQueue {
        Stack<Integer> s1 = new Stack<>();
        Stack<Integer> s2 = new Stack<>();

        public void push(int x) {
            while (!s1.isEmpty()) s2.push(s1.pop());
            s1.push(x);
            while (!s2.isEmpty()) s1.push(s2.pop());
        }

        public int pop() { return s1.pop(); }
        public int peek() { return s1.peek(); }
        public boolean empty() { return s1.isEmpty(); }
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.694Z', '2026-11-20T06:28:30.694Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljza00uro76vv4yi4rk2', 'cmwolljza00upo76vg0zzagpq', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    static class MyQueue {
        Stack<Integer> input = new Stack<>();
        Stack<Integer> output = new Stack<>();

        public void push(int x) { input.push(x); }

        public int pop() {
            peek();
            return output.pop();
        }

        public int peek() {
            if (output.isEmpty()) {
                while (!input.isEmpty()) output.push(input.pop());
            }
            return output.peek();
        }

        public boolean empty() { return input.isEmpty() && output.isEmpty(); }
    }
}', 'O(1) amortized', 'O(N)', '2026-11-20T06:28:30.694Z', '2026-11-20T06:28:30.694Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljza00uuo76volaohezi', 'cmwolljza00uto76vrk0thttq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'class StackNode {
    int data;
    StackNode next;
    StackNode(int a) { data = a; next = null; }
}

public class Solution {
    static class MyStack {
        StackNode top;
        void push(int a) {
            StackNode temp = new StackNode(a);
            temp.next = top;
            top = temp;
        }
        int pop() {
            if (top == null) return -1;
            int res = top.data;
            top = top.next;
            return res;
        }
    }
}', 'O(1)', 'O(N)', '2026-11-20T06:28:30.695Z', '2026-11-20T06:28:30.695Z') ON CONFLICT DO NOTHING;
