INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzb00uyo76vo24nmdpw', 'cmwolljzb00uxo76vcq79oisp', 'BRUTE_FORCE', 'Brute Force Solution', '', 'class QueueNode {
    int data;
    QueueNode next;
    QueueNode(int a) { data = a; next = null; }
}

public class Solution {
    static class MyQueue {
        QueueNode front, rear;
        void push(int a) {
            QueueNode temp = new QueueNode(a);
            if (rear == null) { front = rear = temp; return; }
            rear.next = temp;
            rear = temp;
        }
        int pop() {
            if (front == null) return -1;
            int res = front.data;
            front = front.next;
            if (front == null) rear = null;
            return res;
        }
    }
