INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzb00uzo76vel89jqa6', 'cmwolljzb00uxo76vcq79oisp', 'OPTIMAL', 'Optimal Solution', '', 'class QueueNode {
    int data;
    QueueNode next;
    QueueNode(int a) { data = a; next = null; }
}

public class Solution {
    static class MyQueue {
        QueueNode front, rear;
        void push(int a) {
            QueueNode temp = new QueueNode(a);
            if (rear == null) { front = rear = temp; return; }
            rear.next = temp;
            rear = temp;
        }
        int pop() {
            if (front == null) return -1;
            int res = front.data;
            front = front.next;
            if (front == null) rear = null;
            return res;
        }
    }
}', 'O(1)', 'O(N)', '2026-11-20T06:28:30.696Z', '2026-11-20T06:28:30.696Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzc00v2o76vg7j4mcvp', 'cmwolljzc00v1o76vdum608s6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static boolean isValid(String s) {
        Stack<Character> st = new Stack<>();
        for (char c : s.toCharArray()) {
            if (c == ''('' || c == ''{'' || c == ''['') st.push(c);
            else {
                if (st.isEmpty()) return false;
                char top = st.pop();
                if ((c == '')'' && top != ''('') ||
                    (c == ''}'' && top != ''{'') ||
                    (c == '']'' && top != ''['')) return false;
            }
        }
        return st.isEmpty();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.696Z', '2026-11-20T06:28:30.696Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzc00v3o76vmpliv4q9', 'cmwolljzc00v1o76vdum608s6', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isValid(String s) {
        char[] stack = new char[s.length()];
        int head = 0;
        for (char c : s.toCharArray()) {
            switch (c) {
                case ''{'' -> stack[head++] = ''}'';
                case ''['' -> stack[head++] = '']'';
                case ''('' -> stack[head++] = '')'';
                default -> {
                    if (head == 0 || stack[--head] != c) return false;
                }
            }
        }
        return head == 0;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.696Z', '2026-11-20T06:28:30.696Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzd00v6o76v0a6rjt5m', 'cmwolljzd00v5o76vmtww9l43', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static String infixToPostfix(String exp) {
        StringBuilder result = new StringBuilder();
        Stack<Character> stack = new Stack<>();
        for (char c : exp.toCharArray()) {
            if (Character.isLetterOrDigit(c)) result.append(c);
            else if (c == ''('') stack.push(c);
            else if (c == '')'') {
                while (!stack.isEmpty() && stack.peek() != ''('') result.append(stack.pop());
                stack.pop();
            } else {
                while (!stack.isEmpty() && prec(c) <= prec(stack.peek())) result.append(stack.pop());
                stack.push(c);
            }
        }
        while (!stack.isEmpty()) result.append(stack.pop());
        return result.toString();
    }

    private static int prec(char ch) {
        return switch (ch) {
            case ''+'', ''-'' -> 1;
            case ''*'', ''/'' -> 2;
            case ''^'' -> 3;
            default -> -1;
        };
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.697Z', '2026-11-20T06:28:30.697Z') ON CONFLICT DO NOTHING;
