INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzi00vuo76vr7x99dwk', 'cmwolljzi00vto76vkhc5xvlz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long[] nextLargerElement(long[] arr, int n) {
        long[] ans = new long[n];
        for (int i = 0; i < n; i++) {
            ans[i] = -1;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] > arr[i]) {
                    ans[i] = arr[j];
                    break;
                }
            }
        }
        return ans;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.702Z', '2026-11-20T06:28:30.702Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzi00vvo76vnkxsq2ec', 'cmwolljzi00vto76vkhc5xvlz', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static long[] nextLargerElement(long[] arr, int n) {
        long[] ans = new long[n];
        Stack<Long> s = new Stack<>();
        for (int i = n - 1; i >= 0; i--) {
            while (!s.isEmpty() && s.peek() <= arr[i]) s.pop();
            ans[i] = s.isEmpty() ? -1 : s.peek();
            s.push(arr[i]);
        }
        return ans;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.702Z', '2026-11-20T06:28:30.702Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzj00vyo76vv748tglj', 'cmwolljzj00vxo76vaafrkqsd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                int idx = (i + j) % n;
                if (nums[idx] > nums[i]) {
                    ans[i] = nums[idx];
                    break;
                }
            }
        }
        return ans;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.703Z', '2026-11-20T06:28:30.703Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzj00vzo76vrqcwjjut', 'cmwolljzj00vxo76vaafrkqsd', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        Stack<Integer> s = new Stack<>();
        for (int i = 2 * n - 1; i >= 0; i--) {
            while (!s.isEmpty() && s.peek() <= nums[i % n]) s.pop();
            if (i < n) ans[i] = s.isEmpty() ? -1 : s.peek();
            s.push(nums[i % n]);
        }
        return ans;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.703Z', '2026-11-20T06:28:30.703Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzk00w2o76v2pamuv72', 'cmwolljzk00w1o76vmd4enjby', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static int[] asteroidCollision(int[] asteroids) {
        Stack<Integer> st = new Stack<>();
        for (int a : asteroids) {
            boolean destroyed = false;
            while (!st.isEmpty() && a < 0 && st.peek() > 0) {
                if (st.peek() < -a) {
                    st.pop();
                } else if (st.peek() == -a) {
                    st.pop();
                    destroyed = true;
                    break;
                } else {
                    destroyed = true;
                    break;
                }
            }
            if (!destroyed) st.push(a);
        }
        int[] res = new int[st.size()];
        for (int i = res.length - 1; i >= 0; i--) res[i] = st.pop();
        return res;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.704Z', '2026-11-20T06:28:30.704Z') ON CONFLICT DO NOTHING;
