INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzl00w6o76vxtiqgp75', 'cmwolljzl00w5o76vlchc2vp2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int sumSubarrayMins(int[] arr) {
        long sum = 0, mod = 1_000_000_007;
        int n = arr.length;
        for (int i = 0; i < n; i++) {
            int min = arr[i];
            for (int j = i; j < n; j++) {
                min = Math.min(min, arr[j]);
                sum = (sum + min) % mod;
            }
        }
        return (int) sum;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.706Z', '2026-11-20T06:28:30.706Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzl00w7o76v8syxjt8b', 'cmwolljzl00w5o76vlchc2vp2', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Stack<Integer> s1 = new Stack<>();
        Stack<Integer> s2 = new Stack<>();

        for (int i = 0; i < n; i++) {
            while (!s1.isEmpty() && arr[s1.peek()] > arr[i]) s1.pop();
            left[i] = s1.isEmpty() ? i + 1 : i - s1.peek();
            s1.push(i);
        }

        for (int i = n - 1; i >= 0; i--) {
            while (!s2.isEmpty() && arr[s2.peek()] >= arr[i]) s2.pop();
            right[i] = s2.isEmpty() ? n - i : s2.peek() - i;
            s2.push(i);
        }

        long sum = 0, mod = 1_000_000_007;
        for (int i = 0; i < n; i++) {
            long count = ((long) left[i] * right[i]) % mod;
            sum = (sum + count * arr[i]) % mod;
        }
        return (int) sum;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.706Z', '2026-11-20T06:28:30.706Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzn00wao76vbwfreh2w', 'cmwolljzn00w9o76vff5xwvms', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long subArrayRanges(int[] nums) {
        long sum = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int min = nums[i], max = nums[i];
            for (int j = i; j < n; j++) {
                min = Math.min(min, nums[j]);
                max = Math.max(max, nums[j]);
                sum += (max - min);
            }
        }
        return sum;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.707Z', '2026-11-20T06:28:30.707Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzn00wbo76v6thnt6p1', 'cmwolljzn00w9o76vff5xwvms', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static long subArrayRanges(int[] nums) {
        return sumSubarrayMaxs(nums) - sumSubarrayMins(nums);
    }

    private static long sumSubarrayMins(int[] arr) {
        int n = arr.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Stack<Integer> s1 = new Stack<>();
        Stack<Integer> s2 = new Stack<>();
        for (int i = 0; i < n; i++) {
            while (!s1.isEmpty() && arr[s1.peek()] > arr[i]) s1.pop();
            left[i] = s1.isEmpty() ? i + 1 : i - s1.peek();
            s1.push(i);
        }
        for (int i = n - 1; i >= 0; i--) {
            while (!s2.isEmpty() && arr[s2.peek()] >= arr[i]) s2.pop();
            right[i] = s2.isEmpty() ? n - i : s2.peek() - i;
            s2.push(i);
        }
        long sum = 0;
        for (int i = 0; i < n; i++) sum += (long) left[i] * right[i] * arr[i];
        return sum;
    }

    private static long sumSubarrayMaxs(int[] arr) {
        int n = arr.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Stack<Integer> s1 = new Stack<>();
        Stack<Integer> s2 = new Stack<>();
        for (int i = 0; i < n; i++) {
            while (!s1.isEmpty() && arr[s1.peek()] < arr[i]) s1.pop();
            left[i] = s1.isEmpty() ? i + 1 : i - s1.peek();
            s1.push(i);
        }
        for (int i = n - 1; i >= 0; i--) {
            while (!s2.isEmpty() && arr[s2.peek()] <= arr[i]) s2.pop();
            right[i] = s2.isEmpty() ? n - i : s2.peek() - i;
            s2.push(i);
        }
        long sum = 0;
        for (int i = 0; i < n; i++) sum += (long) left[i] * right[i] * arr[i];
        return sum;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.707Z', '2026-11-20T06:28:30.707Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzo00weo76vte43eaok', 'cmwolljzo00wdo76vkb1wkpbr', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String removeKdigits(String num, int k) {
        if (num.length() == k) return "0";
        StringBuilder sb = new StringBuilder(num);
        for (int i = 0; i < k; i++) {
            int j = 0;
            while (j < sb.length() - 1 && sb.charAt(j) <= sb.charAt(j + 1)) j++;
            sb.deleteCharAt(j);
        }
        while (sb.length() > 1 && sb.charAt(0) == ''0'') sb.deleteCharAt(0);
        return sb.length() == 0 ? "0" : sb.toString();
    }
}', 'O(K * N)', 'O(N)', '2026-11-20T06:28:30.708Z', '2026-11-20T06:28:30.708Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzo00wfo76v50755p4x', 'cmwolljzo00wdo76vkb1wkpbr', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static String removeKdigits(String num, int k) {
        int len = num.length();
        if (k == len) return "0";
        Stack<Character> stack = new Stack<>();
        for (char c : num.toCharArray()) {
            while (k > 0 && !stack.isEmpty() && stack.peek() > c) {
                stack.pop();
                k--;
            }
            stack.push(c);
        }
        while (k > 0) {
            stack.pop();
            k--;
        }
        StringBuilder sb = new StringBuilder();
        while (!stack.isEmpty()) sb.append(stack.pop());
        sb.reverse();
        while (sb.length() > 1 && sb.charAt(0) == ''0'') sb.deleteCharAt(0);
        return sb.length() == 0 ? "0" : sb.toString();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.708Z', '2026-11-20T06:28:30.708Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzp00wio76v2vbzlx7z', 'cmwolljzp00who76vklzjrnwd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;

public class Solution {
    public static ArrayList<Integer> prevSmaller(ArrayList<Integer> A) {
        ArrayList<Integer> ans = new ArrayList<>();
        int n = A.size();
        for (int i = 0; i < n; i++) {
            int smaller = -1;
            for (int j = i - 1; j >= 0; j--) {
                if (A.get(j) < A.get(i)) {
                    smaller = A.get(j);
                    break;
                }
            }
            ans.add(smaller);
        }
        return ans;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.710Z', '2026-11-20T06:28:30.710Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzp00wjo76v4uc4dvk7', 'cmwolljzp00who76vklzjrnwd', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;
import java.util.Stack;

public class Solution {
    public static ArrayList<Integer> prevSmaller(ArrayList<Integer> A) {
        ArrayList<Integer> ans = new ArrayList<>();
        Stack<Integer> st = new Stack<>();
        for (int x : A) {
            while (!st.isEmpty() && st.peek() >= x) st.pop();
            ans.add(st.isEmpty() ? -1 : st.peek());
            st.push(x);
        }
        return ans;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.710Z', '2026-11-20T06:28:30.710Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzr00wmo76v2oyl2ywq', 'cmwolljzr00wlo76viehiv5jr', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    static class MinStack {
        Stack<Integer> stack = new Stack<>();
        Stack<Integer> minStack = new Stack<>();

        public void push(int val) {
            stack.push(val);
            if (minStack.isEmpty() || val <= minStack.peek()) minStack.push(val);
        }

        public void pop() {
            if (stack.peek().equals(minStack.peek())) minStack.pop();
            stack.pop();
        }

        public int top() { return stack.peek(); }
        public int getMin() { return minStack.peek(); }
    }
}', 'O(1)', 'O(2N)', '2026-11-20T06:28:30.711Z', '2026-11-20T06:28:30.711Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzr00wno76vpwr1blt1', 'cmwolljzr00wlo76viehiv5jr', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    static class MinStack {
        Stack<Long> stack = new Stack<>();
        Long min;

        public void push(int val) {
            Long x = (long) val;
            if (stack.isEmpty()) {
                stack.push(x);
                min = x;
            } else if (x < min) {
                stack.push(2 * x - min);
                min = x;
            } else {
                stack.push(x);
            }
        }

        public void pop() {
            if (stack.isEmpty()) return;
            Long x = stack.pop();
            if (x < min) min = 2 * min - x;
        }

        public int top() {
            Long x = stack.peek();
            if (x < min) return min.intValue();
            return x.intValue();
        }

        public int getMin() { return min.intValue(); }
    }
}', 'O(1)', 'O(N)', '2026-11-20T06:28:30.711Z', '2026-11-20T06:28:30.711Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzs00wqo76vlmh0m7h1', 'cmwolljzs00wpo76vck5e9qn6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] res = new int[n - k + 1];
        for (int i = 0; i <= n - k; i++) {
            int max = nums[i];
            for (int j = 1; j < k; j++) {
                max = Math.max(max, nums[i + j]);
            }
            res[i] = max;
        }
        return res;
    }
}', 'O(N * K)', 'O(1)', '2026-11-20T06:28:30.712Z', '2026-11-20T06:28:30.712Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzs00wro76vh876xsj8', 'cmwolljzs00wpo76vck5e9qn6', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public static int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] res = new int[n - k + 1];
        Deque<Integer> q = new ArrayDeque<>();
        int ri = 0;
        for (int i = 0; i < n; i++) {
            if (!q.isEmpty() && q.peek() == i - k) q.poll();
            while (!q.isEmpty() && nums[q.peekLast()] < nums[i]) q.pollLast();
            q.offer(i);
            if (i >= k - 1) res[ri++] = nums[q.peek()];
        }
        return res;
    }
}', 'O(N)', 'O(K)', '2026-11-20T06:28:30.712Z', '2026-11-20T06:28:30.712Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzt00wuo76v4il1fsoq', 'cmwolljzt00wto76vuxzvc2hi', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int trap(int[] height) {
        int n = height.length;
        int water = 0;
        for (int i = 0; i < n; i++) {
            int leftMax = 0, rightMax = 0;
            for (int j = 0; j <= i; j++) leftMax = Math.max(leftMax, height[j]);
            for (int j = i; j < n; j++) rightMax = Math.max(rightMax, height[j]);
            water += Math.min(leftMax, rightMax) - height[i];
        }
        return water;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.714Z', '2026-11-20T06:28:30.714Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzt00wvo76vyjgzdunj', 'cmwolljzt00wto76vuxzvc2hi', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int trap(int[] height) {
        int left = 0, right = height.length - 1;
        int leftMax = 0, rightMax = 0, water = 0;
        while (left <= right) {
            if (height[left] <= height[right]) {
                if (height[left] >= leftMax) leftMax = height[left];
                else water += leftMax - height[left];
                left++;
            } else {
                if (height[right] >= rightMax) rightMax = height[right];
                else water += rightMax - height[right];
                right--;
            }
        }
        return water;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.714Z', '2026-11-20T06:28:30.714Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzu00wyo76v0uhubtbt', 'cmwolljzu00wxo76vw5jq9w8h', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int largestRectangleArea(int[] heights) {
        int max = 0, n = heights.length;
        for (int i = 0; i < n; i++) {
            int minHeight = heights[i];
            for (int j = i; j < n; j++) {
                minHeight = Math.min(minHeight, heights[j]);
                max = Math.max(max, minHeight * (j - i + 1));
            }
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.715Z', '2026-11-20T06:28:30.715Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzu00wzo76vtu3ex0ip', 'cmwolljzu00wxo76vw5jq9w8h', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static int largestRectangleArea(int[] heights) {
        int n = heights.length, max = 0;
        Stack<Integer> st = new Stack<>();
        for (int i = 0; i <= n; i++) {
            int h = (i == n) ? 0 : heights[i];
            while (!st.isEmpty() && h < heights[st.peek()]) {
                int height = heights[st.pop()];
                int width = st.isEmpty() ? i : i - st.peek() - 1;
                max = Math.max(max, height * width);
            }
            st.push(i);
        }
        return max;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.715Z', '2026-11-20T06:28:30.715Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzw00x2o76vvba8hm51', 'cmwolljzw00x1o76vxr1005p4', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int maximalRectangle(char[][] matrix) {
        if (matrix.length == 0) return 0;
        int m = matrix.length, n = matrix[0].length;
        int[] heights = new int[n];
        int max = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == ''1'') heights[j]++;
                else heights[j] = 0;
            }
            max = Math.max(max, largestHistogram(heights));
        }
        return max;
    }

    private static int largestHistogram(int[] heights) {
        int max = 0;
        for (int i = 0; i < heights.length; i++) {
            int minH = heights[i];
            for (int j = i; j < heights.length; j++) {
                minH = Math.min(minH, heights[j]);
                max = Math.max(max, minH * (j - i + 1));
            }
        }
        return max;
    }
}', 'O(M * N²)', 'O(N)', '2026-11-20T06:28:30.716Z', '2026-11-20T06:28:30.716Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzw00x3o76vha5mzie7', 'cmwolljzw00x1o76vxr1005p4', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    public static int maximalRectangle(char[][] matrix) {
        if (matrix.length == 0) return 0;
        int m = matrix.length, n = matrix[0].length;
        int[] heights = new int[n];
        int max = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == ''1'') heights[j]++;
                else heights[j] = 0;
            }
            max = Math.max(max, largestHistogram(heights));
        }
        return max;
    }

    private static int largestHistogram(int[] heights) {
        int n = heights.length, max = 0;
        Stack<Integer> st = new Stack<>();
        for (int i = 0; i <= n; i++) {
            int h = (i == n) ? 0 : heights[i];
            while (!st.isEmpty() && h < heights[st.peek()]) {
                int height = heights[st.pop()];
                int width = st.isEmpty() ? i : i - st.peek() - 1;
                max = Math.max(max, height * width);
            }
            st.push(i);
        }
        return max;
    }
}', 'O(M * N)', 'O(N)', '2026-11-20T06:28:30.716Z', '2026-11-20T06:28:30.716Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzx00x6o76vy4c0uddm', 'cmwolljzx00x5o76vurithlq6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    static class StockSpanner {
        java.util.List<Integer> prices = new java.util.ArrayList<>();
        public int next(int price) {
            prices.add(price);
            int span = 1;
            for (int i = prices.size() - 2; i >= 0 && prices.get(i) <= price; i--) {
                span++;
            }
            return span;
        }
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.718Z', '2026-11-20T06:28:30.718Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzx00x7o76v3l7iqzz0', 'cmwolljzx00x5o76vurithlq6', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    static class StockSpanner {
        Stack<int[]> stack = new Stack<>();
        public int next(int price) {
            int span = 1;
            while (!stack.isEmpty() && stack.peek()[0] <= price) {
                span += stack.pop()[1];
            }
            stack.push(new int[]{price, span});
            return span;
        }
    }
}', 'O(1) amortized', 'O(N)', '2026-11-20T06:28:30.718Z', '2026-11-20T06:28:30.718Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzy00xao76vii9a83q7', 'cmwolljzy00x9o76vz4bvj33d', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int celebrity(int[][] M, int n) {
        int[] in = new int[n];
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (M[i][j] == 1) { out[i]++; in[j]++; }
            }
        }
        for (int i = 0; i < n; i++) {
            if (in[i] == n - 1 && out[i] == 0) return i;
        }
        return -1;
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.719Z', '2026-11-20T06:28:30.719Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwolljzy00xbo76vy0t3g2wy', 'cmwolljzy00x9o76vz4bvj33d', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int celebrity(int[][] M, int n) {
        int a = 0, b = n - 1;
        while (a < b) {
            if (M[a][b] == 1) a++;
            else b--;
        }
        for (int i = 0; i < n; i++) {
            if (i != a && (M[a][i] == 1 || M[i][a] == 0)) return -1;
        }
        return a;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.719Z', '2026-11-20T06:28:30.719Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0500xvo76vl7n9usmu', 'cmwollk0500xto76v2p2mo3b2', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static List<Integer> inorderTraversal(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        Stack<TreeNode> stack = new Stack<>();
        TreeNode curr = root;
        while (curr != null || !stack.isEmpty()) {
            while (curr != null) {
                stack.push(curr);
                curr = curr.left;
            }
            curr = stack.pop();
            res.add(curr.val);
            curr = curr.right;
        }
        return res;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.726Z', '2026-11-20T06:28:30.726Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0000xeo76v5al0y0xz', 'cmwollk0000xdo76vumha640s', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashMap;
import java.util.Map;

public class Solution {
    static class LRUCache {
        class Node {
            int key, val;
            Node prev, next;
            Node(int k, int v) { key = k; val = v; }
        }

        Node head = new Node(0, 0), tail = new Node(0, 0);
        Map<Integer, Node> map = new HashMap<>();
        int capacity;

        public LRUCache(int capacity) {
            this.capacity = capacity;
            head.next = tail;
            tail.prev = head;
        }

        public int get(int key) {
            if (map.containsKey(key)) {
                Node node = map.get(key);
                remove(node);
                insert(node);
                return node.val;
            }
            return -1;
        }

        public void put(int key, int value) {
            if (map.containsKey(key)) remove(map.get(key));
            if (map.size() == capacity) remove(tail.prev);
            insert(new Node(key, value));
        }

        private void remove(Node node) {
            map.remove(node.key);
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }

        private void insert(Node node) {
            map.put(node.key, node);
            node.next = head.next;
            node.next.prev = node;
            head.next = node;
            node.prev = head;
        }
    }
}', 'O(1)', 'O(capacity)', '2026-11-20T06:28:30.720Z', '2026-11-20T06:28:30.720Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0000xfo76vnurvi5ge', 'cmwollk0000xdo76vumha640s', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.LinkedHashMap;
import java.util.Map;

public class Solution {
    static class LRUCache extends LinkedHashMap<Integer, Integer> {
        private final int capacity;

        public LRUCache(int capacity) {
            super(capacity, 0.75f, true);
            this.capacity = capacity;
        }

        public int get(int key) {
            return super.getOrDefault(key, -1);
        }

        public void put(int key, int value) {
            super.put(key, value);
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {
            return size() > capacity;
        }
    }
}', 'O(1)', 'O(capacity)', '2026-11-20T06:28:30.720Z', '2026-11-20T06:28:30.720Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0100xio76vw8v7zzyh', 'cmwollk0100xho76v96uj9iqc', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    static class LFUCache {
        int cap, minFreq;
        Map<Integer, Integer> vals = new HashMap<>();
        Map<Integer, Integer> counts = new HashMap<>();
        Map<Integer, LinkedHashSet<Integer>> lists = new HashMap<>();

        public LFUCache(int capacity) {
            cap = capacity;
            minFreq = -1;
            lists.put(1, new LinkedHashSet<>());
        }

        public int get(int key) {
            if (!vals.containsKey(key)) return -1;
            int count = counts.get(key);
            counts.put(key, count + 1);
            lists.get(count).remove(key);
            if (count == minFreq && lists.get(count).isEmpty()) minFreq++;
            if (!lists.containsKey(count + 1)) lists.put(count + 1, new LinkedHashSet<>());
            lists.get(count + 1).add(key);
            return vals.get(key);
        }

        public void put(int key, int value) {
            if (cap <= 0) return;
            if (vals.containsKey(key)) {
                vals.put(key, value);
                get(key);
                return;
            }
            if (vals.size() >= cap) {
                int evict = lists.get(minFreq).iterator().next();
                lists.get(minFreq).remove(evict);
                vals.remove(evict);
                counts.remove(evict);
            }
            vals.put(key, value);
            counts.put(key, 1);
            minFreq = 1;
            lists.get(1).add(key);
        }
    }
}', 'O(1)', 'O(capacity)', '2026-11-20T06:28:30.721Z', '2026-11-20T06:28:30.721Z') ON CONFLICT DO NOTHING;
