INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0200xmo76v7qw6low7', 'cmwollk0200xlo76vkte8w00w', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] countGreater(int[] arr, int[] query) {
        int[] ans = new int[query.length];
        for (int q = 0; q < query.length; q++) {
            int idx = query[q];
            int count = 0;
            for (int i = idx + 1; i < arr.length; i++) {
                if (arr[i] > arr[idx]) count++;
            }
            ans[q] = count;
        }
        return ans;
    }
}', 'O(Q * N)', 'O(1)', '2026-11-20T06:28:30.723Z', '2026-11-20T06:28:30.723Z') ON CONFLICT DO NOTHING;
