INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0a00yao76v7lmil7vw', 'cmwollk0a00y9o76vh30z5uib', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

class Pair {
    TreeNode node;
    int num;
    Pair(TreeNode n, int num) { this.node = n; this.num = num; }
}

public class Solution {
    public static void allTraversals(TreeNode root) {
        List<Integer> pre = new ArrayList<>(), in = new ArrayList<>(), post = new ArrayList<>();
        if (root == null) return;
        Stack<Pair> st = new Stack<>();
        st.push(new Pair(root, 1));
        while (!st.isEmpty()) {
            Pair it = st.pop();
            if (it.num == 1) {
                pre.add(it.node.val);
                it.num++;
                st.push(it);
                if (it.node.left != null) st.push(new Pair(it.node.left, 1));
            } else if (it.num == 2) {
                in.add(it.node.val);
                it.num++;
                st.push(it);
                if (it.node.right != null) st.push(new Pair(it.node.right, 1));
            } else {
                post.add(it.node.val);
            }
        }
    }
}', 'O(3N)', 'O(4N)', '2026-11-20T06:28:30.731Z', '2026-11-20T06:28:30.731Z') ON CONFLICT DO NOTHING;
