INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0d00yio76vws4sqtnh', 'cmwollk0d00yho76v64iczcfz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) return true;
        if (p == null || q == null) return false;
        return (p.val == q.val) && isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.733Z', '2026-11-20T06:28:30.733Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0d00yjo76vy7dj1ze3', 'cmwollk0d00yho76v64iczcfz', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) return true;
        if (p == null || q == null) return false;
        return (p.val == q.val) && isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.733Z', '2026-11-20T06:28:30.733Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0e00ymo76vo8tea9no', 'cmwollk0e00ylo76viw6f3emx', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isBalanced(TreeNode root) {
        if (root == null) return true;
        int lh = height(root.left);
        int rh = height(root.right);
        return Math.abs(lh - rh) <= 1 && isBalanced(root.left) && isBalanced(root.right);
    }

    private static int height(TreeNode node) {
        if (node == null) return 0;
        return 1 + Math.max(height(node.left), height(node.right));
    }
}', 'O(N²)', 'O(H)', '2026-11-20T06:28:30.735Z', '2026-11-20T06:28:30.735Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0e00yno76vuerlew5w', 'cmwollk0e00ylo76viw6f3emx', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isBalanced(TreeNode root) {
        return dfsHeight(root) != -1;
    }

    private static int dfsHeight(TreeNode root) {
        if (root == null) return 0;
        int leftHeight = dfsHeight(root.left);
        if (leftHeight == -1) return -1;
        int rightHeight = dfsHeight(root.right);
        if (rightHeight == -1) return -1;
        if (Math.abs(leftHeight - rightHeight) > 1) return -1;
        return Math.max(leftHeight, rightHeight) + 1;
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.735Z', '2026-11-20T06:28:30.735Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0g00yqo76vq9l69mtp', 'cmwollk0g00ypo76vuf826o7x', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int diameterOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        int cur = height(root.left) + height(root.right);
        int left = diameterOfBinaryTree(root.left);
        int right = diameterOfBinaryTree(root.right);
        return Math.max(cur, Math.max(left, right));
    }

    private static int height(TreeNode node) {
        if (node == null) return 0;
        return 1 + Math.max(height(node.left), height(node.right));
    }
}', 'O(N²)', 'O(H)', '2026-11-20T06:28:30.736Z', '2026-11-20T06:28:30.736Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0g00yro76vj7tbjaqt', 'cmwollk0g00ypo76vuf826o7x', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    private static int diameter = 0;

    public static int diameterOfBinaryTree(TreeNode root) {
        diameter = 0;
        height(root);
        return diameter;
    }

    private static int height(TreeNode node) {
        if (node == null) return 0;
        int lh = height(node.left);
        int rh = height(node.right);
        diameter = Math.max(diameter, lh + rh);
        return 1 + Math.max(lh, rh);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.736Z', '2026-11-20T06:28:30.736Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0h00yuo76v9w167mak', 'cmwollk0h00yto76vb1ett0lo', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    private static int maxValue;

    public static int maxPathSum(TreeNode root) {
        maxValue = Integer.MIN_VALUE;
        maxPathDown(root);
        return maxValue;
    }

    private static int maxPathDown(TreeNode node) {
        if (node == null) return 0;
        int left = Math.max(0, maxPathDown(node.left));
        int right = Math.max(0, maxPathDown(node.right));
        maxValue = Math.max(maxValue, left + right + node.val);
        return Math.max(left, right) + node.val;
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.737Z', '2026-11-20T06:28:30.737Z') ON CONFLICT DO NOTHING;
