INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0i00yyo76vs9ot4x43', 'cmwollk0i00yxo76vddoe0fwj', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isSymmetric(TreeNode root) {
        return root == null || isSymmetricHelp(root.left, root.right);
    }

    private static boolean isSymmetricHelp(TreeNode left, TreeNode right) {
        if (left == null || right == null) return left == right;
        if (left.val != right.val) return false;
        return isSymmetricHelp(left.left, right.right) && isSymmetricHelp(left.right, right.left);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.738Z', '2026-11-20T06:28:30.738Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0i00yzo76v1oxycmyl', 'cmwollk0i00yxo76vddoe0fwj', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isSymmetric(TreeNode root) {
        return root == null || isSymmetricHelp(root.left, root.right);
    }

    private static boolean isSymmetricHelp(TreeNode left, TreeNode right) {
        if (left == null || right == null) return left == right;
        if (left.val != right.val) return false;
        return isSymmetricHelp(left.left, right.right) && isSymmetricHelp(left.right, right.left);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.738Z', '2026-11-20T06:28:30.738Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0j00z2o76vjv60w832', 'cmwollk0j00z1o76vs4kobg62', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int isSumProperty(TreeNode root) {
        if (root == null || (root.left == null && root.right == null)) return 1;
        int sum = 0;
        if (root.left != null) sum += root.left.val;
        if (root.right != null) sum += root.right.val;
        if (root.val == sum && isSumProperty(root.left) == 1 && isSumProperty(root.right) == 1) return 1;
        return 0;
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.739Z', '2026-11-20T06:28:30.739Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0j00z3o76vrvw5o9lv', 'cmwollk0j00z1o76vs4kobg62', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void changeTree(TreeNode root) {
        if (root == null) return;
        int child = 0;
        if (root.left != null) child += root.left.val;
        if (root.right != null) child += root.right.val;
        if (child >= root.val) root.val = child;
        else {
            if (root.left != null) root.left.val = root.val;
            else if (root.right != null) root.right.val = root.val;
        }
        changeTree(root.left);
        changeTree(root.right);
        int tot = 0;
        if (root.left != null) tot += root.left.val;
        if (root.right != null) tot += root.right.val;
        if (root.left != null || root.right != null) root.val = tot;
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.739Z', '2026-11-20T06:28:30.739Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0k00z6o76v20q8ks59', 'cmwollk0k00z5o76v7vdqxad0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<Integer>> zigzagLevelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) return result;
        Queue<TreeNode> nodesQueue = new LinkedList<>();
        nodesQueue.add(root);
        boolean leftToRight = true;
        while (!nodesQueue.isEmpty()) {
            int size = nodesQueue.size();
            LinkedList<Integer> row = new LinkedList<>();
            for (int i = 0; i < size; i++) {
                TreeNode node = nodesQueue.poll();
                if (leftToRight) row.add(node.val);
                else row.addFirst(node.val);
                if (node.left != null) nodesQueue.add(node.left);
                if (node.right != null) nodesQueue.add(node.right);
            }
            leftToRight = !leftToRight;
            result.add(row);
        }
        return result;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.740Z', '2026-11-20T06:28:30.740Z') ON CONFLICT DO NOTHING;
