INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0n00zio76vqfaezj92', 'cmwollk0n00zho76vv95qwkvl', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<Integer> topView(TreeNode root) {
        ArrayList<Integer> ans = new ArrayList<>();
        if (root == null) return ans;
        Map<Integer, Integer> map = new TreeMap<>();
        Queue<Pair> q = new LinkedList<>();
        q.add(new Pair(root, 0));
        while (!q.isEmpty()) {
            Pair it = q.remove();
            int hd = it.num;
            TreeNode node = it.node;
            if (!map.containsKey(hd)) map.put(hd, node.val);
            if (node.left != null) q.add(new Pair(node.left, hd - 1));
            if (node.right != null) q.add(new Pair(node.right, hd + 1));
        }
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) ans.add(entry.getValue());
        return ans;
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.744Z', '2026-11-20T06:28:30.744Z') ON CONFLICT DO NOTHING;
