INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0s00zuo76v3zuerb7r', 'cmwollk0r00zto76v6zemw39e', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<ArrayList<Integer>> Paths(TreeNode root) {
        ArrayList<ArrayList<Integer>> res = new ArrayList<>();
        ArrayList<Integer> path = new ArrayList<>();
        getPath(root, res, path);
        return res;
    }

    private static void getPath(TreeNode root, ArrayList<ArrayList<Integer>> res, ArrayList<Integer> path) {
        if (root == null) return;
        path.add(root.val);
        if (root.left == null && root.right == null) res.add(new ArrayList<>(path));
        else {
            getPath(root.left, res, path);
            getPath(root.right, res, path);
        }
        path.remove(path.size() - 1);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.748Z', '2026-11-20T06:28:30.748Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0s00zvo76vus4853yd', 'cmwollk0r00zto76v6zemw39e', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static ArrayList<ArrayList<Integer>> Paths(TreeNode root) {
        ArrayList<ArrayList<Integer>> res = new ArrayList<>();
        ArrayList<Integer> path = new ArrayList<>();
        getPath(root, res, path);
        return res;
    }

    private static void getPath(TreeNode root, ArrayList<ArrayList<Integer>> res, ArrayList<Integer> path) {
        if (root == null) return;
        path.add(root.val);
        if (root.left == null && root.right == null) res.add(new ArrayList<>(path));
        else {
            getPath(root.left, res, path);
            getPath(root.right, res, path);
        }
        path.remove(path.size() - 1);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.748Z', '2026-11-20T06:28:30.748Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0t00zyo76vi8hobyg0', 'cmwollk0t00zxo76vabsoojb2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        if (root == null || root == p || root == q) return root;
        TreeNode left = lowestCommonAncestor(root.left, p, q);
        TreeNode right = lowestCommonAncestor(root.right, p, q);
        if (left == null) return right;
        else if (right == null) return left;
        else return root;
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.749Z', '2026-11-20T06:28:30.749Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0t00zzo76vv4ijay3x', 'cmwollk0t00zxo76vabsoojb2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
