INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0x010eo76vh5gfrp9u', 'cmwollk0x010do76va0gcyhne', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int countNodes(TreeNode root) {
        if (root == null) return 0;
        return 1 + countNodes(root.left) + countNodes(root.right);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.754Z', '2026-11-20T06:28:30.754Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0x010fo76vzts2dmmi', 'cmwollk0x010do76va0gcyhne', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countNodes(TreeNode root) {
        if (root == null) return 0;
        int left = getLeftHeight(root);
        int right = getRightHeight(root);
        if (left == right) return ((2 << (left)) - 1);
        else return 1 + countNodes(root.left) + countNodes(root.right);
    }

    private static int getLeftHeight(TreeNode root) {
        int count = 0;
        while (root.left != null) { count++; root = root.left; }
        return count;
    }

    private static int getRightHeight(TreeNode root) {
        int count = 0;
        while (root.right != null) { count++; root = root.right; }
        return count;
    }
}', 'O((log N)²)', 'O(log N)', '2026-11-20T06:28:30.754Z', '2026-11-20T06:28:30.754Z') ON CONFLICT DO NOTHING;
