INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0y010jo76vrjdfargb', 'cmwollk0y010ho76v4xyy4ygp', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void flatten(TreeNode root) {
        TreeNode curr = root;
        while (curr != null) {
            if (curr.left != null) {
                TreeNode prev = curr.left;
                while (prev.right != null) prev = prev.right;
                prev.right = curr.right;
                curr.right = curr.left;
                curr.left = null;
            }
            curr = curr.right;
        }
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.755Z', '2026-11-20T06:28:30.755Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk0z010mo76va7s0di3w', 'cmwollk0z010lo76vasskvo7k', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isPossible(int a, int b) {
        // True if one traversal is Inorder and other is Preorder or Postorder
        return (a == 2 && b != 2) || (b == 2 && a != 2);
    }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.756Z', '2026-11-20T06:28:30.756Z') ON CONFLICT DO NOTHING;
