INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4401cjo76vr5jutikz', 'cmwollk4301cho76vy4bzchx4', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public boolean canPartition(int[] nums) {
        int sum = 0;
        for (int x : nums) sum += x;
        if (sum % 2 != 0) return false;
        int target = sum / 2;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;
        for (int num : nums) {
            for (int t = target; t >= num; t--) {
                dp[t] = dp[t] || dp[t - num];
            }
        }
        return dp[target];
    }
}', 'O(N * Sum/2)', 'O(Sum/2)', '2026-11-20T06:28:30.868Z', '2026-11-20T06:28:30.868Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk10010qo76v7xddfvgw', 'cmwollk10010po76vdz8ykhxw', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> inMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) inMap.put(inorder[i], i);
        return build(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1, inMap);
    }

    private static TreeNode build(int[] pre, int preStart, int preEnd, int[] in, int inStart, int inEnd, Map<Integer, Integer> inMap) {
        if (preStart > preEnd || inStart > inEnd) return null;
        TreeNode root = new TreeNode(pre[preStart]);
        int inRoot = inMap.get(root.val);
        int numsLeft = inRoot - inStart;
        root.left = build(pre, preStart + 1, preStart + numsLeft, in, inStart, inRoot - 1, inMap);
        root.right = build(pre, preStart + numsLeft + 1, preEnd, in, inRoot + 1, inEnd, inMap);
        return root;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.757Z', '2026-11-20T06:28:30.757Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk10010ro76vbpvmro95', 'cmwollk10010po76vdz8ykhxw', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

