INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk13010yo76vcamls2ut', 'cmwollk13010xo76vymrg3ecg', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static String serialize(TreeNode root) {
        if (root == null) return "";
        Queue<TreeNode> q = new LinkedList<>();
        StringBuilder res = new StringBuilder();
        q.add(root);
        while (!q.isEmpty()) {
            TreeNode node = q.poll();
            if (node == null) {
                res.append("n ");
                continue;
            }
            res.append(node.val + " ");
            q.add(node.left);
            q.add(node.right);
        }
        return res.toString();
    }

    public static TreeNode deserialize(String data) {
        if (data.isEmpty()) return null;
        Queue<TreeNode> q = new LinkedList<>();
        String[] values = data.split(" ");
        TreeNode root = new TreeNode(Integer.parseInt(values[0]));
        q.add(root);
        for (int i = 1; i < values.length; i++) {
            TreeNode parent = q.poll();
            if (!values[i].equals("n")) {
                TreeNode left = new TreeNode(Integer.parseInt(values[i]));
                parent.left = left;
                q.add(left);
            }
            if (!values[++i].equals("n")) {
                TreeNode right = new TreeNode(Integer.parseInt(values[i]));
                parent.right = right;
                q.add(right);
            }
        }
        return root;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.759Z', '2026-11-20T06:28:30.759Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1a011qo76vmsrsj0n2', 'cmwollk1a011po76v9y06jsuz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static TreeNode insertIntoBST(TreeNode root, int val) {
        if (root == null) return new TreeNode(val);
        if (val < root.val) root.left = insertIntoBST(root.left, val);
        else root.right = insertIntoBST(root.right, val);
        return root;
    }
}', 'O(H)', 'O(H)', '2026-11-20T06:28:30.767Z', '2026-11-20T06:28:30.767Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1a011ro76vv5yvnqsv', 'cmwollk1a011po76v9y06jsuz', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static TreeNode insertIntoBST(TreeNode root, int val) {
        if (root == null) return new TreeNode(val);
        TreeNode cur = root;
        while (true) {
            if (cur.val <= val) {
                if (cur.right != null) cur = cur.right;
                else { cur.right = new TreeNode(val); break; }
            } else {
                if (cur.left != null) cur = cur.left;
                else { cur.left = new TreeNode(val); break; }
            }
        }
        return root;
    }
}', 'O(H)', 'O(1)', '2026-11-20T06:28:30.767Z', '2026-11-20T06:28:30.767Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1h012io76vuz3baohl', 'cmwollk1h012ho76vetuubyfv', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    static class BSTIterator {
        private Stack<TreeNode> stack = new Stack<>();

        public BSTIterator(TreeNode root) { pushAll(root); }
        public boolean hasNext() { return !stack.isEmpty(); }

        public int next() {
            TreeNode tmpNode = stack.pop();
            pushAll(tmpNode.right);
            return tmpNode.val;
        }

        private void pushAll(TreeNode node) {
            for (; node != null; stack.push(node), node = node.left);
        }
    }
}', 'O(1) amortized', 'O(H)', '2026-11-20T06:28:30.773Z', '2026-11-20T06:28:30.773Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5c01h3o76v32l4fw0h', 'cmwollk5c01h1o76vfh4i1quo', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countRev(String s) {
        if (s.length() % 2 != 0) return -1;
        int open = 0, close = 0;
        for (char c : s.toCharArray()) {
            if (c == ''{'') {
                open++;
            } else {
                if (open > 0) open--;
                else close++;
            }
        }
        return (open + 1) / 2 + (close + 1) / 2;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.912Z', '2026-11-20T06:28:30.912Z') ON CONFLICT DO NOTHING;
