INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk17011eo76vecgrw3qv', 'cmwollk17011do76vemzigi9f', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static TreeNode searchBST(TreeNode root, int val) {
        if (root == null || root.val == val) return root;
        if (val < root.val) return searchBST(root.left, val);
        return searchBST(root.right, val);
    }
}', 'O(H)', 'O(H)', '2026-11-20T06:28:30.764Z', '2026-11-20T06:28:30.764Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk17011fo76v5ar1buve', 'cmwollk17011do76vemzigi9f', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static TreeNode searchBST(TreeNode root, int val) {
        while (root != null && root.val != val) {
            root = val < root.val ? root.left : root.right;
        }
        return root;
