INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk18011io76ven4vleni', 'cmwollk18011ho76vncew3pqn', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findCeil(TreeNode root, int key) {
        int ceil = -1;
        while (root != null) {
            if (root.val == key) return root.val;
            if (key > root.val) {
                root = root.right;
            } else {
                ceil = root.val;
                root = root.left;
            }
        }
        return ceil;
    }
}', 'O(H)', 'O(1)', '2026-11-20T06:28:30.765Z', '2026-11-20T06:28:30.765Z') ON CONFLICT DO NOTHING;
