INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1b011uo76v2xyxteyx', 'cmwollk1b011to76vkyt4rx6k', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static TreeNode deleteNode(TreeNode root, int key) {
        if (root == null) return null;
        if (root.val == key) return helper(root);
        TreeNode dummy = root;
        while (root != null) {
            if (root.val > key) {
                if (root.left != null && root.left.val == key) {
                    root.left = helper(root.left);
                    break;
                } else root = root.left;
            } else {
                if (root.right != null && root.right.val == key) {
                    root.right = helper(root.right);
                    break;
                } else root = root.right;
            }
        }
        return dummy;
    }

    private static TreeNode helper(TreeNode root) {
        if (root.left == null) return root.right;
        else if (root.right == null) return root.left;
        TreeNode rightChild = root.right;
        TreeNode lastRight = findLastRight(root.left);
        lastRight.right = rightChild;
        return root.left;
    }

    private static TreeNode findLastRight(TreeNode root) {
        if (root.right == null) return root;
        return findLastRight(root.right);
    }
}', 'O(H)', 'O(1)', '2026-11-20T06:28:30.768Z', '2026-11-20T06:28:30.768Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1b011vo76vn0e957rm', 'cmwollk1b011to76vkyt4rx6k', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static TreeNode deleteNode(TreeNode root, int key) {
        if (root == null) return null;
        if (root.val == key) return helper(root);
        TreeNode dummy = root;
        while (root != null) {
            if (root.val > key) {
                if (root.left != null && root.left.val == key) {
                    root.left = helper(root.left);
                    break;
                } else root = root.left;
            } else {
                if (root.right != null && root.right.val == key) {
                    root.right = helper(root.right);
                    break;
                } else root = root.right;
            }
        }
        return dummy;
    }

    private static TreeNode helper(TreeNode root) {
        if (root.left == null) return root.right;
        else if (root.right == null) return root.left;
        TreeNode rightChild = root.right;
        TreeNode lastRight = findLastRight(root.left);
        lastRight.right = rightChild;
        return root.left;
    }

    private static TreeNode findLastRight(TreeNode root) {
        if (root.right == null) return root;
        return findLastRight(root.right);
    }
}', 'O(H)', 'O(1)', '2026-11-20T06:28:30.768Z', '2026-11-20T06:28:30.768Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1d011yo76vjqdx3oka', 'cmwollk1d011xo76vr04my7gt', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int kthSmallest(TreeNode root, int k) {
        List<Integer> list = new ArrayList<>();
        inorder(root, list);
        return list.get(k - 1);
    }

    private static void inorder(TreeNode root, List<Integer> list) {
        if (root == null) return;
        inorder(root.left, list);
        list.add(root.val);
        inorder(root.right, list);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.769Z', '2026-11-20T06:28:30.769Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1d011zo76vr7180jmr', 'cmwollk1d011xo76vr04my7gt', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    private static int count = 0;
    private static int result = Integer.MIN_VALUE;

    public static int kthSmallest(TreeNode root, int k) {
        count = 0;
        result = Integer.MIN_VALUE;
        inorder(root, k);
        return result;
    }

    private static void inorder(TreeNode root, int k) {
        if (root == null) return;
        inorder(root.left, k);
        count++;
        if (count == k) {
            result = root.val;
            return;
        }
        inorder(root.right, k);
    }
}', 'O(min(K, N))', 'O(H)', '2026-11-20T06:28:30.769Z', '2026-11-20T06:28:30.769Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1d0122o76v1uzwkjab', 'cmwollk1d0121o76vect6w0i5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isValidBST(TreeNode root) {
        return isValid(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private static boolean isValid(TreeNode root, long minVal, long maxVal) {
        if (root == null) return true;
        if (root.val >= maxVal || root.val <= minVal) return false;
        return isValid(root.left, minVal, root.val) && isValid(root.right, root.val, maxVal);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.770Z', '2026-11-20T06:28:30.770Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1d0123o76vo6492ei4', 'cmwollk1d0121o76vect6w0i5', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean isValidBST(TreeNode root) {
        return isValid(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private static boolean isValid(TreeNode root, long minVal, long maxVal) {
        if (root == null) return true;
        if (root.val >= maxVal || root.val <= minVal) return false;
        return isValid(root.left, minVal, root.val) && isValid(root.right, root.val, maxVal);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.770Z', '2026-11-20T06:28:30.770Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1e0126o76vendk9e6g', 'cmwollk1e0125o76v6er62nj2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        if (root == null) return null;
        int cur = root.val;
        if (cur < p.val && cur < q.val) return lowestCommonAncestor(root.right, p, q);
        if (cur > p.val && cur > q.val) return lowestCommonAncestor(root.left, p, q);
        return root;
    }
}', 'O(H)', 'O(H)', '2026-11-20T06:28:30.771Z', '2026-11-20T06:28:30.771Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1e0127o76v7ff05xki', 'cmwollk1e0125o76v6er62nj2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        while (root != null) {
            int cur = root.val;
            if (cur < p.val && cur < q.val) root = root.right;
            else if (cur > p.val && cur > q.val) root = root.left;
            else return root;
        }
        return null;
    }
}', 'O(H)', 'O(1)', '2026-11-20T06:28:30.771Z', '2026-11-20T06:28:30.771Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1f012ao76v166zew8q', 'cmwollk1f0129o76v3evzffrd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static TreeNode bstFromPreorder(int[] preorder) {
        return bst(preorder, Integer.MAX_VALUE, new int[]{0});
    }

    private static TreeNode bst(int[] A, int bound, int[] i) {
        if (i[0] == A.length || A[i[0]] > bound) return null;
        TreeNode root = new TreeNode(A[i[0]++]);
        root.left = bst(A, root.val, i);
        root.right = bst(A, bound, i);
        return root;
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.771Z', '2026-11-20T06:28:30.771Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1f012bo76vixh2ag1v', 'cmwollk1f0129o76v3evzffrd', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static TreeNode bstFromPreorder(int[] preorder) {
        return bst(preorder, Integer.MAX_VALUE, new int[]{0});
    }

    private static TreeNode bst(int[] A, int bound, int[] i) {
        if (i[0] == A.length || A[i[0]] > bound) return null;
        TreeNode root = new TreeNode(A[i[0]++]);
        root.left = bst(A, root.val, i);
        root.right = bst(A, bound, i);
        return root;
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.771Z', '2026-11-20T06:28:30.771Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1g012eo76vv2t7vcqh', 'cmwollk1g012do76vn54tn8b1', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static TreeNode inorderSuccessor(TreeNode root, TreeNode p) {
        TreeNode successor = null;
        while (root != null) {
            if (p.val >= root.val) {
                root = root.right;
            } else {
                successor = root;
                root = root.left;
            }
        }
        return successor;
    }
}', 'O(H)', 'O(1)', '2026-11-20T06:28:30.772Z', '2026-11-20T06:28:30.772Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1h012jo76v6fkuyoqw', 'cmwollk1h012ho76vetuubyfv', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Stack;

public class Solution {
    static class BSTIterator {
        private Stack<TreeNode> stack = new Stack<>();

        public BSTIterator(TreeNode root) { pushAll(root); }
        public boolean hasNext() { return !stack.isEmpty(); }

        public int next() {
            TreeNode tmpNode = stack.pop();
            pushAll(tmpNode.right);
            return tmpNode.val;
        }

        private void pushAll(TreeNode node) {
            for (; node != null; stack.push(node), node = node.left);
        }
    }
}', 'O(1) amortized', 'O(H)', '2026-11-20T06:28:30.773Z', '2026-11-20T06:28:30.773Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1h012mo76vnldly09e', 'cmwollk1h012lo76viewkgxxd', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static boolean findTarget(TreeNode root, int k) {
        Set<Integer> set = new HashSet<>();
        return dfs(root, set, k);
    }

    private static boolean dfs(TreeNode root, Set<Integer> set, int k) {
        if (root == null) return false;
        if (set.contains(k - root.val)) return true;
        set.add(root.val);
        return dfs(root.left, set, k) || dfs(root.right, set, k);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.774Z', '2026-11-20T06:28:30.774Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1h012no76v1afwczca', 'cmwollk1h012lo76viewkgxxd', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static boolean findTarget(TreeNode root, int k) {
        Set<Integer> set = new HashSet<>();
        return dfs(root, set, k);
    }

    private static boolean dfs(TreeNode root, Set<Integer> set, int k) {
        if (root == null) return false;
        if (set.contains(k - root.val)) return true;
        set.add(root.val);
        return dfs(root.left, set, k) || dfs(root.right, set, k);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.774Z', '2026-11-20T06:28:30.774Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1i012qo76vyslms04w', 'cmwollk1i012po76vmr7ls8fp', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    private static TreeNode first, prev, middle, last;

    public static void recoverTree(TreeNode root) {
        first = middle = last = null;
        prev = new TreeNode(Integer.MIN_VALUE);
        inorder(root);
        if (first != null && last != null) {
            int t = first.val; first.val = last.val; last.val = t;
        } else if (first != null && middle != null) {
            int t = first.val; first.val = middle.val; middle.val = t;
        }
    }

    private static void inorder(TreeNode root) {
        if (root == null) return;
        inorder(root.left);
        if (prev != null && (root.val < prev.val)) {
            if (first == null) {
                first = prev;
                middle = root;
            } else last = root;
        }
        prev = root;
        inorder(root.right);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.775Z', '2026-11-20T06:28:30.775Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1i012ro76v82n8tgts', 'cmwollk1i012po76vmr7ls8fp', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    private static TreeNode first, prev, middle, last;

    public static void recoverTree(TreeNode root) {
        first = middle = last = null;
        prev = new TreeNode(Integer.MIN_VALUE);
        inorder(root);
        if (first != null && last != null) {
            int t = first.val; first.val = last.val; last.val = t;
        } else if (first != null && middle != null) {
            int t = first.val; first.val = middle.val; middle.val = t;
        }
    }

    private static void inorder(TreeNode root) {
        if (root == null) return;
        inorder(root.left);
        if (prev != null && (root.val < prev.val)) {
            if (first == null) {
                first = prev;
                middle = root;
            } else last = root;
        }
        prev = root;
        inorder(root.right);
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.775Z', '2026-11-20T06:28:30.775Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1j012uo76vtxxoba4g', 'cmwollk1j012to76vllqlzxqs', 'BRUTE_FORCE', 'Brute Force Solution', '', 'class NodeValue {
    public int maxNode, minNode, maxSize;
    NodeValue(int minNode, int maxNode, int maxSize) {
        this.minNode = minNode;
        this.maxNode = maxNode;
        this.maxSize = maxSize;
    }
}

public class Solution {
    public static int largestBst(TreeNode root) {
        return largestBSTSubtreeHelper(root).maxSize;
    }

    private static NodeValue largestBSTSubtreeHelper(TreeNode root) {
        if (root == null) return new NodeValue(Integer.MAX_VALUE, Integer.MIN_VALUE, 0);
        NodeValue left = largestBSTSubtreeHelper(root.left);
        NodeValue right = largestBSTSubtreeHelper(root.right);
        if (left.maxNode < root.val && root.val < right.minNode) {
            return new NodeValue(Math.min(root.val, left.minNode), Math.max(root.val, right.maxNode), 1 + left.maxSize + right.maxSize);
        }
        return new NodeValue(Integer.MIN_VALUE, Integer.MAX_VALUE, Math.max(left.maxSize, right.maxSize));
    }
}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.775Z', '2026-11-20T06:28:30.775Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1j012vo76vo1ohgia1', 'cmwollk1j012to76vllqlzxqs', 'OPTIMAL', 'Optimal Solution', '', 'class NodeValue {
