}', 'O(N)', 'O(H)', '2026-11-20T06:28:30.775Z', '2026-11-20T06:28:30.775Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1k012yo76vqc1ue5o2', 'cmwollk1k012xo76vtjh3uqcw', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    // Binary Heap representation in an Array:
    // Left Child: 2*i + 1, Right Child: 2*i + 2, Parent: (i - 1) / 2
    public static int getParent(int i) { return (i - 1) / 2; }
    public static int getLeftChild(int i) { return 2 * i + 1; }
    public static int getRightChild(int i) { return 2 * i + 2; }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.776Z', '2026-11-20T06:28:30.776Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1k012zo76vofwo6fz3', 'cmwollk1k012xo76vtjh3uqcw', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int getParent(int i) { return (i - 1) / 2; }
    public static int getLeftChild(int i) { return 2 * i + 1; }
    public static int getRightChild(int i) { return 2 * i + 2; }
}', 'O(1)', 'O(1)', '2026-11-20T06:28:30.776Z', '2026-11-20T06:28:30.776Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1l0132o76v9nh02lfw', 'cmwollk1l0131o76vzvxrpxid', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void heapify(int[] arr, int n, int i) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < n && arr[left] > arr[largest]) largest = left;
        if (right < n && arr[right] > arr[largest]) largest = right;
        if (largest != i) {
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;
            heapify(arr, n, largest);
        }
    }
}', 'O(log N)', 'O(log N)', '2026-11-20T06:28:30.777Z', '2026-11-20T06:28:30.777Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4501cmo76v3muhsa6z', 'cmwollk4501clo76vzx8wrb7w', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int minSubsetSumDifference(int[] arr, int n) {
        int totSum = 0;
        for (int x : arr) totSum += x;
        return solve(n - 1, 0, totSum, arr);
    }
    private static int solve(int ind, int curSum, int totSum, int[] arr) {
        if (ind < 0) return Math.abs((totSum - curSum) - curSum);
        return Math.min(solve(ind - 1, curSum + arr[ind], totSum, arr), solve(ind - 1, curSum, totSum, arr));
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.869Z', '2026-11-20T06:28:30.869Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1l0133o76vkpvskjcb', 'cmwollk1l0131o76vzvxrpxid', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void heapify(int[] arr, int n, int i) {
        while (true) {
            int largest = i;
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            if (left < n && arr[left] > arr[largest]) largest = left;
            if (right < n && arr[right] > arr[largest]) largest = right;
            if (largest == i) break;
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;
            i = largest;
        }
    }
}', 'O(log N)', 'O(1)', '2026-11-20T06:28:30.777Z', '2026-11-20T06:28:30.777Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1m0136o76vy5kyz89i', 'cmwollk1m0135o76v29qbo0dm', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void buildHeap(int[] arr, int n) {
        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(arr, n, i);
        }
    }

    private static void heapify(int[] arr, int n, int i) {
        int largest = i, l = 2 * i + 1, r = 2 * i + 2;
        if (l < n && arr[l] > arr[largest]) largest = l;
        if (r < n && arr[r] > arr[largest]) largest = r;
        if (largest != i) {
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;
            heapify(arr, n, largest);
        }
    }
}', 'O(N)', 'O(log N)', '2026-11-20T06:28:30.778Z', '2026-11-20T06:28:30.778Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1m0137o76v73m7fi2x', 'cmwollk1m0135o76v29qbo0dm', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static void buildHeap(int[] arr, int n) {
        for (int i = n / 2 - 1; i >= 0; i--) {
            int curr = i;
            while (true) {
                int largest = curr, l = 2 * curr + 1, r = 2 * curr + 2;
                if (l < n && arr[l] > arr[largest]) largest = l;
                if (r < n && arr[r] > arr[largest]) largest = r;
                if (largest == curr) break;
                int swap = arr[curr];
                arr[curr] = arr[largest];
                arr[largest] = swap;
                curr = largest;
            }
        }
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.778Z', '2026-11-20T06:28:30.778Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1n013ao76v3nthmjfw', 'cmwollk1n0139o76vde63bfjq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    static class MinHeap {
        int[] harr = new int[1000];
        int capacity = 1000;
        int heap_size = 0;

        int parent(int i) { return (i - 1) / 2; }
        int left(int i) { return (2 * i + 1); }
        int right(int i) { return (2 * i + 2); }

        int extractMin() {
            if (heap_size <= 0) return -1;
            if (heap_size == 1) return harr[--heap_size];
            int root = harr[0];
            harr[0] = harr[--heap_size];
            MinHeapify(0);
            return root;
        }

        void insertKey(int k) {
            if (heap_size == capacity) return;
            int i = heap_size++;
            harr[i] = k;
            while (i != 0 && harr[parent(i)] > harr[i]) {
                int temp = harr[i];
                harr[i] = harr[parent(i)];
                harr[parent(i)] = temp;
                i = parent(i);
            }
        }

        void MinHeapify(int i) {
            int l = left(i), r = right(i), smallest = i;
            if (l < heap_size && harr[l] < harr[smallest]) smallest = l;
            if (r < heap_size && harr[r] < harr[smallest]) smallest = r;
            if (smallest != i) {
                int temp = harr[i];
                harr[i] = harr[smallest];
                harr[smallest] = temp;
                MinHeapify(smallest);
            }
        }
    }
}', 'O(log N)', 'O(N)', '2026-11-20T06:28:30.779Z', '2026-11-20T06:28:30.779Z') ON CONFLICT DO NOTHING;
