INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1o013eo76vmk0jf8gm', 'cmwollk1o013do76vqdfyan2o', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    static class MaxHeap {
        int[] arr = new int[1000];
        int size = 0;

        void push(int val) {
            int i = size++;
            arr[i] = val;
            while (i != 0 && arr[(i - 1) / 2] < arr[i]) {
                int temp = arr[i];
                arr[i] = arr[(i - 1) / 2];
                arr[(i - 1) / 2] = temp;
                i = (i - 1) / 2;
            }
        }

        int pop() {
            if (size <= 0) return -1;
            if (size == 1) return arr[--size];
            int root = arr[0];
            arr[0] = arr[--size];
            heapify(0);
            return root;
        }

        void heapify(int i) {
            int l = 2 * i + 1, r = 2 * i + 2, largest = i;
            if (l < size && arr[l] > arr[largest]) largest = l;
            if (r < size && arr[r] > arr[largest]) largest = r;
            if (largest != i) {
                int temp = arr[i];
                arr[i] = arr[largest];
                arr[largest] = temp;
                heapify(largest);
            }
        }
    }
}', 'O(log N)', 'O(N)', '2026-11-20T06:28:30.780Z', '2026-11-20T06:28:30.780Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1u0143o76v45p9qwee', 'cmwollk1u0141o76vsyjt9lqg', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.PriorityQueue;

public class Solution {
    public static void nearlySorted(int[] arr, int num, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        int index = 0;
        for (int i = 0; i <= Math.min(num - 1, k); i++) pq.add(arr[i]);
        for (int i = k + 1; i < num; i++) {
            arr[index++] = pq.poll();
            pq.add(arr[i]);
        }
        while (!pq.isEmpty()) arr[index++] = pq.poll();
    }
}', 'O(N log K)', 'O(K)', '2026-11-20T06:28:30.787Z', '2026-11-20T06:28:30.787Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1v0146o76vgtg03gog', 'cmwollk1v0145o76vwvgn680a', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

class ListNode {
    int val;
    ListNode next;
    ListNode(int val) { this.val = val; }
}

public class Solution {
    public static ListNode mergeKLists(ListNode[] lists) {
        List<Integer> vals = new ArrayList<>();
        for (ListNode node : lists) {
            while (node != null) {
                vals.add(node.val);
                node = node.next;
            }
        }
        Collections.sort(vals);
        ListNode dummy = new ListNode(0), curr = dummy;
        for (int v : vals) {
            curr.next = new ListNode(v);
            curr = curr.next;
        }
        return dummy.next;
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.788Z', '2026-11-20T06:28:30.788Z') ON CONFLICT DO NOTHING;
