INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1p013io76vk6y6k516', 'cmwollk1p013ho76v3qsl06uy', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean isMinHeap(int[] arr, int n) {
        for (int i = 0; i <= (n - 2) / 2; i++) {
