INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1q013mo76vyr6fxjiy', 'cmwollk1q013lo76vp4yn3g2g', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void convertMinToMaxHeap(int n, int[] arr) {
        for (int i = (n - 2) / 2; i >= 0; --i) {
            maxHeapify(arr, i, n);
        }
    }

    private static void maxHeapify(int[] arr, int i, int n) {
        int l = 2 * i + 1, r = 2 * i + 2, largest = i;
        if (l < n && arr[l] > arr[largest]) largest = l;
        if (r < n && arr[r] > arr[largest]) largest = r;
        if (largest != i) {
            int temp = arr[i];
            arr[i] = arr[largest];
            arr[largest] = temp;
            maxHeapify(arr, largest, n);
        }
    }
}', 'O(N)', 'O(log N)', '2026-11-20T06:28:30.782Z', '2026-11-20T06:28:30.782Z') ON CONFLICT DO NOTHING;
