INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1s013vo76vjvgqv5yg', 'cmwollk1s013to76vdgfk52ts', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.PriorityQueue;

public class Solution {
    public static int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.add(num);
            if (pq.size() > k) pq.poll();
        }
        return pq.peek();
    }
}', 'O(N log K)', 'O(K)', '2026-11-20T06:28:30.785Z', '2026-11-20T06:28:30.785Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1t013yo76vo79ke58s', 'cmwollk1t013xo76voeidwftp', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.PriorityQueue;

public class Solution {
    static class KthLargest {
        private PriorityQueue<Integer> pq;
        private int k;

        public KthLargest(int k, int[] nums) {
            this.k = k;
            this.pq = new PriorityQueue<>(k);
            for (int n : nums) add(n);
        }

        public int add(int val) {
            pq.offer(val);
            if (pq.size() > k) pq.poll();
            return pq.peek();
        }
    }
}', 'O(log K)', 'O(K)', '2026-11-20T06:28:30.786Z', '2026-11-20T06:28:30.786Z') ON CONFLICT DO NOTHING;
