INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1v0147o76vhqiu4y0u', 'cmwollk1v0145o76vwvgn680a', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.PriorityQueue;

public class Solution {
    public static ListNode mergeKLists(ListNode[] lists) {
        if (lists == null || lists.length == 0) return null;
        PriorityQueue<ListNode> pq = new PriorityQueue<>((a, b) -> a.val - b.val);
        for (ListNode node : lists) {
            if (node != null) pq.add(node);
        }
        ListNode dummy = new ListNode(0), curr = dummy;
        while (!pq.isEmpty()) {
            ListNode node = pq.poll();
            curr.next = node;
            curr = curr.next;
            if (node.next != null) pq.add(node.next);
        }
        return dummy.next;
    }
}', 'O(N log K)', 'O(K)', '2026-11-20T06:28:30.788Z', '2026-11-20T06:28:30.788Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1x014ao76v3od0wo23', 'cmwollk1x0149o76v2sk2s7ub', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[] replaceWithRank(int[] arr, int N) {
        int[] sorted = arr.clone();
        Arrays.sort(sorted);
        Map<Integer, Integer> rank = new HashMap<>();
        int r = 1;
        for (int x : sorted) {
            if (!rank.containsKey(x)) rank.put(x, r++);
        }
        int[] res = new int[N];
        for (int i = 0; i < N; i++) res[i] = rank.get(arr[i]);
        return res;
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.789Z', '2026-11-20T06:28:30.789Z') ON CONFLICT DO NOTHING;
