INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1y014eo76v7z9n0ycd', 'cmwollk1y014do76v8u2iu8k5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int leastInterval(char[] tasks, int n) {
        int[] freq = new int[26];
        for (char t : tasks) freq[t - ''A'']++;
        Arrays.sort(freq);
        int maxFreq = freq[25] - 1;
        int idleSlots = maxFreq * n;
        for (int i = 24; i >= 0 && freq[i] > 0; i--) {
            idleSlots -= Math.min(freq[i], maxFreq);
        }
        return idleSlots > 0 ? idleSlots + tasks.length : tasks.length;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.790Z', '2026-11-20T06:28:30.790Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1y014fo76vj2bpu79t', 'cmwollk1y014do76v8u2iu8k5', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int leastInterval(char[] tasks, int n) {
        int[] freq = new int[26];
        for (char t : tasks) freq[t - ''A'']++;
        Arrays.sort(freq);
        int maxFreq = freq[25] - 1;
        int idleSlots = maxFreq * n;
        for (int i = 24; i >= 0 && freq[i] > 0; i--) {
            idleSlots -= Math.min(freq[i], maxFreq);
        }
        return idleSlots > 0 ? idleSlots + tasks.length : tasks.length;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.790Z', '2026-11-20T06:28:30.790Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk1z014io76v7qatl6wd', 'cmwollk1z014ho76vcxemrun9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;
        TreeMap<Integer, Integer> count = new TreeMap<>();
        for (int card : hand) count.put(card, count.getOrDefault(card, 0) + 1);
        for (int card : count.keySet()) {
            if (count.get(card) > 0) {
                int need = count.get(card);
                for (int i = 0; i < groupSize; i++) {
                    if (count.getOrDefault(card + i, 0) < need) return false;
                    count.put(card + i, count.get(card + i) - need);
                }
            }
        }
        return true;
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.791Z', '2026-11-20T06:28:30.791Z') ON CONFLICT DO NOTHING;
