INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk23014yo76v96co49k5', 'cmwollk23014xo76vaebncy0u', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.PriorityQueue;

public class Solution {
    static class MedianFinder {
        private PriorityQueue<Integer> small = new PriorityQueue<>((a, b) -> b - a);
        private PriorityQueue<Integer> large = new PriorityQueue<>();

        public void addNum(int num) {
            small.add(num);
            large.add(small.poll());
            if (large.size() > small.size()) small.add(large.poll());
        }

        public double findMedian() {
            return small.size() > large.size() ? small.peek() : (small.peek() + large.peek()) / 2.0;
        }
    }
}', 'O(log N)', 'O(N)', '2026-11-20T06:28:30.796Z', '2026-11-20T06:28:30.796Z') ON CONFLICT DO NOTHING;
