INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2a015mo76vnr23b4du', 'cmwollk2a015lo76vhd6jjcwf', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int numIslands(char[][] grid) {
        int count = 0;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == ''1'') {
                    dfs(grid, i, j);
                    count++;
                }
            }
        }
        return count;
    }

    private static void dfs(char[][] grid, int i, int j) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] != ''1'') return;
        grid[i][j] = ''0'';
        dfs(grid, i + 1, j);
        dfs(grid, i - 1, j);
        dfs(grid, i, j + 1);
        dfs(grid, i, j - 1);
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.803Z', '2026-11-20T06:28:30.803Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2a015no76v2brkrxio', 'cmwollk2a015lo76vhd6jjcwf', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
