INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2b015qo76vzfte2fh8', 'cmwollk2b015po76vq5ykmrzl', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int initColor = image[sr][sc];
        if (initColor != color) dfs(image, sr, sc, initColor, color);
        return image;
    }

    private static void dfs(int[][] image, int r, int c, int initColor, int newColor) {
        if (r < 0 || r >= image.length || c < 0 || c >= image[0].length || image[r][c] != initColor) return;
        image[r][c] = newColor;
        dfs(image, r + 1, c, initColor, newColor);
        dfs(image, r - 1, c, initColor, newColor);
        dfs(image, r, c + 1, initColor, newColor);
        dfs(image, r, c - 1, initColor, newColor);
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.804Z', '2026-11-20T06:28:30.804Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2b015ro76v29tlgzmv', 'cmwollk2b015po76vq5ykmrzl', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int initColor = image[sr][sc];
        if (initColor != color) dfs(image, sr, sc, initColor, color);
        return image;
    }

    private static void dfs(int[][] image, int r, int c, int initColor, int newColor) {
        if (r < 0 || r >= image.length || c < 0 || c >= image[0].length || image[r][c] != initColor) return;
        image[r][c] = newColor;
        dfs(image, r + 1, c, initColor, newColor);
        dfs(image, r - 1, c, initColor, newColor);
        dfs(image, r, c + 1, initColor, newColor);
        dfs(image, r, c - 1, initColor, newColor);
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.804Z', '2026-11-20T06:28:30.804Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2d015uo76v1ql85oz2', 'cmwollk2d015to76v70xvahu7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int numEnclaves(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 1) dfs(grid, i, 0);
            if (grid[i][n - 1] == 1) dfs(grid, i, n - 1);
        }
        for (int j = 0; j < n; j++) {
            if (grid[0][j] == 1) dfs(grid, 0, j);
            if (grid[m - 1][j] == 1) dfs(grid, m - 1, j);
        }
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) count++;
            }
        }
        return count;
    }

    private static void dfs(int[][] grid, int r, int c) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] != 1) return;
        grid[r][c] = 0;
        dfs(grid, r + 1, c);
        dfs(grid, r - 1, c);
        dfs(grid, r, c + 1);
        dfs(grid, r, c - 1);
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.805Z', '2026-11-20T06:28:30.805Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4d01dio76vlfhhvwkj', 'cmwollk4d01dho76vz4u5jl69', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int cutRod(int price[], int n) {
        return solve(n - 1, n, price);
    }
    private static int solve(int ind, int N, int[] price) {
        if (ind == 0) return N * price[0];
        int notTake = solve(ind - 1, N, price);
        int take = Integer.MIN_VALUE;
        int rodLength = ind + 1;
        if (rodLength <= N) take = price[ind] + solve(ind, N - rodLength, price);
        return Math.max(notTake, take);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.878Z', '2026-11-20T06:28:30.878Z') ON CONFLICT DO NOTHING;
