INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2e015yo76v9nm0sspc', 'cmwollk2e015xo76vb2b9o1lc', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public static int orangesRotting(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        int rows = grid.length, cols = grid[0].length;
        Queue<int[]> queue = new LinkedList<>();
        int count_fresh = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 2) queue.offer(new int[]{i, j});
                if (grid[i][j] == 1) count_fresh++;
            }
        }
        if (count_fresh == 0) return 0;
        int count = 0, dirs[][] = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!queue.isEmpty()) {
            int size = queue.size();
            count++;
            for (int i = 0; i < size; i++) {
                int[] point = queue.poll();
                for (int[] dir : dirs) {
                    int x = point[0] + dir[0], y = point[1] + dir[1];
                    if (x < 0 || y < 0 || x >= rows || y >= cols || grid[x][y] == 0 || grid[x][y] == 2) continue;
                    grid[x][y] = 2;
                    queue.offer(new int[]{x, y});
                    count_fresh--;
                }
            }
        }
        return count_fresh == 0 ? count - 1 : -1;
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.806Z', '2026-11-20T06:28:30.806Z') ON CONFLICT DO NOTHING;
