INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2f0162o76vpe8uz1ah', 'cmwollk2f0161o76v50oxmp3w', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public static int[][] updateMatrix(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int[][] dist = new int[m][n];
        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 0) q.offer(new int[]{i, j});
                else dist[i][j] = -1;
            }
        }
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            for (int[] d : dirs) {
                int r = curr[0] + d[0], c = curr[1] + d[1];
                if (r >= 0 && r < m && c >= 0 && c < n && dist[r][c] == -1) {
                    dist[r][c] = dist[curr[0]][curr[1]] + 1;
                    q.offer(new int[]{r, c});
                }
            }
        }
        return dist;
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.807Z', '2026-11-20T06:28:30.807Z') ON CONFLICT DO NOTHING;
