INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2j016jo76v0ckbcciv', 'cmwollk2j016ho76v1jeleoc1', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;

public class Solution {
    public static boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);
        for (int i = 0; i < n; i++) {
            if (color[i] == -1 && !dfs(i, 0, color, graph)) return false;
        }
        return true;
    }

    private static boolean dfs(int node, int col, int[] color, int[][] graph) {
        color[node] = col;
        for (int it : graph[node]) {
            if (color[it] == -1) {
                if (!dfs(it, 1 - col, color, graph)) return false;
            } else if (color[it] == col) return false;
        }
        return true;
    }
}', 'O(V + E)', 'O(V)', '2026-11-20T06:28:30.812Z', '2026-11-20T06:28:30.812Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2g0166o76vpdjk28pc', 'cmwollk2g0165o76vh6cw1i72', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void solve(char[][] board) {
        if (board.length == 0 || board[0].length == 0) return;
        int m = board.length, n = board[0].length;
        for (int i = 0; i < m; i++) {
            if (board[i][0] == ''O'') dfs(board, i, 0);
            if (board[i][n - 1] == ''O'') dfs(board, i, n - 1);
        }
        for (int j = 0; j < n; j++) {
            if (board[0][j] == ''O'') dfs(board, 0, j);
            if (board[m - 1][j] == ''O'') dfs(board, m - 1, j);
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == ''O'') board[i][j] = ''X'';
                if (board[i][j] == ''#'') board[i][j] = ''O'';
            }
        }
    }

    private static void dfs(char[][] board, int r, int c) {
        if (r < 0 || c < 0 || r >= board.length || c >= board[0].length || board[r][c] != ''O'') return;
        board[r][c] = ''#'';
        dfs(board, r + 1, c);
        dfs(board, r - 1, c);
        dfs(board, r, c + 1);
        dfs(board, r, c - 1);
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.808Z', '2026-11-20T06:28:30.808Z') ON CONFLICT DO NOTHING;
