INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2h016ao76v1y2bywpx', 'cmwollk2h0169o76v0rksgfh7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int countDistinctIslands(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Set<List<String>> set = new HashSet<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    List<String> list = new ArrayList<>();
                    dfs(grid, i, j, i, j, list);
                    set.add(list);
                }
            }
        }
        return set.size();
    }

    private static void dfs(int[][] grid, int r, int c, int r0, int c0, List<String> list) {
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length || grid[r][c] != 1) return;
        grid[r][c] = 0;
        list.add((r - r0) + ":" + (c - c0));
        dfs(grid, r + 1, c, r0, c0, list);
        dfs(grid, r - 1, c, r0, c0, list);
        dfs(grid, r, c + 1, r0, c0, list);
        dfs(grid, r, c - 1, r0, c0, list);
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.809Z', '2026-11-20T06:28:30.809Z') ON CONFLICT DO NOTHING;
