INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2i016eo76vqdkuflbg', 'cmwollk2i016do76vqjxnleud', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static boolean isCycle(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] vis = new boolean[V];
        for (int i = 0; i < V; i++) {
            if (!vis[i] && checkForCycle(i, adj, vis)) return true;
        }
        return false;
    }

    private static boolean checkForCycle(int src, ArrayList<ArrayList<Integer>> adj, boolean[] vis) {
        vis[src] = true;
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{src, -1});
        while (!q.isEmpty()) {
            int node = q.peek()[0], parent = q.peek()[1];
            q.remove();
            for (int adjNode : adj.get(node)) {
                if (!vis[adjNode]) {
                    vis[adjNode] = true;
                    q.add(new int[]{adjNode, node});
                } else if (parent != adjNode) return true;
            }
        }
        return false;
    }
}', 'O(V + E)', 'O(V)', '2026-11-20T06:28:30.811Z', '2026-11-20T06:28:30.811Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2i016fo76vkm6jj4r6', 'cmwollk2i016do76vqjxnleud', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static boolean isCycle(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] vis = new boolean[V];
        for (int i = 0; i < V; i++) {
            if (!vis[i] && dfs(i, -1, vis, adj)) return true;
        }
        return false;
    }

    private static boolean dfs(int node, int parent, boolean[] vis, ArrayList<ArrayList<Integer>> adj) {
        vis[node] = true;
        for (int it : adj.get(node)) {
            if (!vis[it]) {
                if (dfs(it, node, vis, adj)) return true;
            } else if (it != parent) return true;
        }
        return false;
    }
}', 'O(V + E)', 'O(V)', '2026-11-20T06:28:30.811Z', '2026-11-20T06:28:30.811Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2j016io76vu793pjf6', 'cmwollk2j016ho76v1jeleoc1', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);
        for (int i = 0; i < n; i++) {
            if (color[i] == -1 && !check(i, graph, color)) return false;
        }
        return true;
    }

    private static boolean check(int start, int[][] graph, int[] color) {
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        color[start] = 0;
        while (!q.isEmpty()) {
            int node = q.poll();
            for (int it : graph[node]) {
                if (color[it] == -1) {
                    color[it] = 1 - color[node];
                    q.add(it);
                } else if (color[it] == color[node]) return false;
            }
        }
        return true;
    }
}', 'O(V + E)', 'O(V)', '2026-11-20T06:28:30.812Z', '2026-11-20T06:28:30.812Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4101cbo76vsvyby21p', 'cmwollk4101c9o76vfar3gq0i', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        if (n <= 1) return 0;
        int buy = -prices[0], sell = 0, rest = 0;
        for (int i = 1; i < n; i++) {
            int prevSell = sell;
            sell = buy + prices[i];
            buy = Math.max(buy, rest - prices[i]);
            rest = Math.max(rest, prevSell);
        }
        return Math.max(sell, rest);
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.866Z', '2026-11-20T06:28:30.866Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2k016mo76v6wc6ds48', 'cmwollk2k016lo76v9moj1yle', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[] topoSort(int V, ArrayList<ArrayList<Integer>> adj) {
        int[] indegree = new int[V];
        for (int i = 0; i < V; i++) {
            for (int it : adj.get(i)) indegree[it]++;
        }
        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < V; i++) if (indegree[i] == 0) q.add(i);
        int[] topo = new int[V];
        int ind = 0;
        while (!q.isEmpty()) {
            int node = q.poll();
            topo[ind++] = node;
            for (int it : adj.get(node)) {
                if (--indegree[it] == 0) q.add(it);
            }
        }
        return topo;
    }
}', 'O(V + E)', 'O(V)', '2026-11-20T06:28:30.813Z', '2026-11-20T06:28:30.813Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4d01djo76vuew6mpoh', 'cmwollk4d01dho76vz4u5jl69', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int cutRod(int price[], int n) {
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                dp[i] = Math.max(dp[i], price[j - 1] + dp[i - j]);
            }
        }
        return dp[n];
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.878Z', '2026-11-20T06:28:30.878Z') ON CONFLICT DO NOTHING;
