INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2l016qo76v2d37aiso', 'cmwollk2l016po76vn6ac1you', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static boolean isCyclic(int V, ArrayList<ArrayList<Integer>> adj) {
        int[] inDegree = new int[V];
        for (int u = 0; u < V; u++) {
            for (int v : adj.get(u)) inDegree[v]++;
        }
        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < V; i++) if (inDegree[i] == 0) q.add(i);
        int count = 0;
        while (!q.isEmpty()) {
            int node = q.poll();
            count++;
            for (int neighbor : adj.get(node)) {
                if (--inDegree[neighbor] == 0) q.add(neighbor);
            }
        }
        return count != V;
    }
}', 'O(V + E)', 'O(V)', '2026-11-20T06:28:30.814Z', '2026-11-20T06:28:30.814Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2l016ro76vo09io04e', 'cmwollk2l016po76vn6ac1you', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static boolean isCyclic(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] vis = new boolean[V];
        boolean[] pathVis = new boolean[V];
        for (int i = 0; i < V; i++) {
            if (!vis[i] && dfsCheck(i, adj, vis, pathVis)) return true;
        }
        return false;
    }

    private static boolean dfsCheck(int node, ArrayList<ArrayList<Integer>> adj, boolean[] vis, boolean[] pathVis) {
        vis[node] = true;
        pathVis[node] = true;
        for (int it : adj.get(node)) {
            if (!vis[it]) {
                if (dfsCheck(it, adj, vis, pathVis)) return true;
            } else if (pathVis[it]) return true;
        }
        pathVis[node] = false;
        return false;
    }
}', 'O(V + E)', 'O(V)', '2026-11-20T06:28:30.814Z', '2026-11-20T06:28:30.814Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2m016uo76v2b7lx5jp', 'cmwollk2m016to76v8ogkh14t', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<Integer> eventualSafeNodes(int[][] graph) {
        int V = graph.length;
        List<List<Integer>> adjRev = new ArrayList<>();
        for (int i = 0; i < V; i++) adjRev.add(new ArrayList<>());
        int[] indegree = new int[V];
        for (int i = 0; i < V; i++) {
            for (int it : graph[i]) {
                adjRev.get(it).add(i);
                indegree[i]++;
            }
        }
        Queue<Integer> q = new LinkedList<>();
        List<Integer> safeNodes = new ArrayList<>();
        for (int i = 0; i < V; i++) if (indegree[i] == 0) q.add(i);
        while (!q.isEmpty()) {
            int node = q.poll();
            safeNodes.add(node);
            for (int it : adjRev.get(node)) {
                if (--indegree[it] == 0) q.add(it);
            }
        }
        Collections.sort(safeNodes);
        return safeNodes;
    }
}', 'O(V + E + V log V)', 'O(V)', '2026-11-20T06:28:30.815Z', '2026-11-20T06:28:30.815Z') ON CONFLICT DO NOTHING;
