INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4201ceo76vw9dn8mz3', 'cmwollk4201cdo76vo9mjxfy5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static boolean subsetSumToK(int n, int k, int arr[]) {
        return solve(n - 1, k, arr);
    }
    private static boolean solve(int ind, int target, int[] arr) {
        if (target == 0) return true;
        if (ind == 0) return arr[0] == target;
        boolean notTaken = solve(ind - 1, target, arr);
        boolean taken = false;
        if (arr[ind] <= target) taken = solve(ind - 1, target - arr[ind], arr);
        return notTaken || taken;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.867Z', '2026-11-20T06:28:30.867Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4401cio76vk3ba69f0', 'cmwollk4301cho76vy4bzchx4', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public boolean canPartition(int[] nums) {
        int sum = 0;
        for (int x : nums) sum += x;
        if (sum % 2 != 0) return false;
        return solve(nums.length - 1, sum / 2, nums);
    }
    private boolean solve(int ind, int target, int[] nums) {
        if (target == 0) return true;
        if (ind == 0) return nums[0] == target;
        boolean notTake = solve(ind - 1, target, nums);
        boolean take = false;
        if (nums[ind] <= target) take = solve(ind - 1, target - nums[ind], nums);
        return take || notTake;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.868Z', '2026-11-20T06:28:30.868Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2p0172o76vavih1uue', 'cmwollk2p0171o76vusljb8v1', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        int[] indegree = new int[numCourses];
        for (int[] p : prerequisites) {
            adj.get(p[1]).add(p[0]);
            indegree[p[0]]++;
        }
        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < numCourses; i++) if (indegree[i] == 0) q.add(i);
        int[] topo = new int[numCourses];
        int idx = 0;
        while (!q.isEmpty()) {
            int node = q.poll();
            topo[idx++] = node;
            for (int it : adj.get(node)) {
                if (--indegree[it] == 0) q.add(it);
            }
        }
        return idx == numCourses ? topo : new int[0];
    }
}', 'O(V + E)', 'O(V + E)', '2026-11-20T06:28:30.817Z', '2026-11-20T06:28:30.817Z') ON CONFLICT DO NOTHING;
