INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2q0176o76vxeuje1d8', 'cmwollk2q0175o76vk95vocfv', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static String findOrder(String[] dict, int N, int K) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < K; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < N - 1; i++) {
            String s1 = dict[i], s2 = dict[i + 1];
            int len = Math.min(s1.length(), s2.length());
            for (int ptr = 0; ptr < len; ptr++) {
                if (s1.charAt(ptr) != s2.charAt(ptr)) {
                    adj.get(s1.charAt(ptr) - ''a'').add(s2.charAt(ptr) - ''a'');
                    break;
                }
            }
        }
        int[] indegree = new int[K];
        for (int i = 0; i < K; i++) for (int it : adj.get(i)) indegree[it]++;
        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < K; i++) if (indegree[i] == 0) q.add(i);
        StringBuilder ans = new StringBuilder();
        while (!q.isEmpty()) {
            int node = q.poll();
            ans.append((char) (node + ''a''));
            for (int it : adj.get(node)) {
                if (--indegree[it] == 0) q.add(it);
            }
        }
        return ans.length() == K ? ans.toString() : "";
    }
}', 'O(N * L + K)', 'O(K)', '2026-11-20T06:28:30.818Z', '2026-11-20T06:28:30.818Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2q0177o76vn7zxzg4k', 'cmwollk2q0175o76vk95vocfv', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

