INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4a01d7o76vr3twjr5g', 'cmwollk4a01d5o76v7819r33d', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int totSum = 0;
        for (int x : nums) totSum += x;
        if (totSum - target < 0 || (totSum - target) % 2 != 0) return 0;
        int s2 = (totSum - target) / 2;
        int[] dp = new int[s2 + 1];
        dp[0] = 1;
        for (int val : nums) {
            for (int t = s2; t >= val; t--) {
                dp[t] += dp[t - val];
            }
        }
        return dp[s2];
    }
}', 'O(N * Target)', 'O(Target)', '2026-11-20T06:28:30.875Z', '2026-11-20T06:28:30.875Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2s017eo76vsby6ntxf', 'cmwollk2s017do76vkvjky3i7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[] shortestPath(int[][] edges, int n, int m, int src) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[src] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(src);
        while (!q.isEmpty()) {
            int node = q.poll();
            for (int it : adj.get(node)) {
                if (dist[it] == -1) {
                    dist[it] = dist[node] + 1;
                    q.add(it);
                }
            }
        }
        return dist;
    }
}', 'O(V + 2E)', 'O(V + 2E)', '2026-11-20T06:28:30.820Z', '2026-11-20T06:28:30.820Z') ON CONFLICT DO NOTHING;
