INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2t017io76vj4cgl8tx', 'cmwollk2t017ho76v7lv5n5f1', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> set = new HashSet<>(wordList);
        if (!set.contains(endWord)) return 0;
        Queue<String> queue = new LinkedList<>();
        queue.add(beginWord);
        int level = 1;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String curr = queue.poll();
                char[] chars = curr.toCharArray();
                for (int j = 0; j < chars.length; j++) {
                    char orig = chars[j];
                    for (char c = ''a''; c <= ''z''; c++) {
                        chars[j] = c;
                        String next = new String(chars);
                        if (next.equals(endWord)) return level + 1;
                        if (set.contains(next)) {
                            queue.add(next);
                            set.remove(next);
                        }
                    }
                    chars[j] = orig;
                }
            }
            level++;
        }
        return 0;
    }
}', 'O(N * L * 26)', 'O(N)', '2026-11-20T06:28:30.822Z', '2026-11-20T06:28:30.822Z') ON CONFLICT DO NOTHING;
