INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2u017mo76vlppdq267', 'cmwollk2u017lo76vnf6lvrbz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        List<List<String>> ans = new ArrayList<>();
        Set<String> dict = new HashSet<>(wordList);
        if (!dict.contains(endWord)) return ans;
        Queue<List<String>> q = new LinkedList<>();
        q.add(new ArrayList<>(Arrays.asList(beginWord)));
        Set<String> visited = new HashSet<>();
        visited.add(beginWord);
        boolean found = false;
        while (!q.isEmpty() && !found) {
            int size = q.size();
            Set<String> subVisited = new HashSet<>();
            for (int k = 0; k < size; k++) {
                List<String> path = q.poll();
                String last = path.get(path.size() - 1);
                char[] chars = last.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char orig = chars[i];
                    for (char c = ''a''; c <= ''z''; c++) {
                        chars[i] = c;
                        String next = new String(chars);
                        if (dict.contains(next) && !visited.contains(next)) {
                            List<String> newPath = new ArrayList<>(path);
                            newPath.add(next);
                            if (next.equals(endWord)) {
                                found = true;
                                ans.add(newPath);
                            } else {
                                q.add(newPath);
                                subVisited.add(next);
                            }
                        }
                    }
                    chars[i] = orig;
                }
            }
            visited.addAll(subVisited);
        }
        return ans;
    }
}', 'O(N * L * 26)', 'O(N * L)', '2026-11-20T06:28:30.823Z', '2026-11-20T06:28:30.823Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2y017yo76ve35s29u8', 'cmwollk2y017xo76v47f023od', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int shortestDistance(int[][] grid, int[] source, int[] destination) {
        if (source[0] == destination[0] && source[1] == destination[1]) return 0;
        int n = grid.length, m = grid[0].length;
        int[][] dist = new int[n][m];
        for (int[] r : dist) Arrays.fill(r, (int) 1e9);
        dist[source[0]][source[1]] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{0, source[0], source[1]});
        int[] dr = {-1, 0, 1, 0}, dc = {0, 1, 0, -1};
        while (!q.isEmpty()) {
            int[] it = q.poll();
            int dis = it[0], r = it[1], c = it[2];
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == 1 && dis + 1 < dist[nr][nc]) {
                    dist[nr][nc] = 1 + dis;
                    if (nr == destination[0] && nc == destination[1]) return dis + 1;
                    q.add(new int[]{1 + dis, nr, nc});
                }
            }
        }
        return -1;
    }
}', 'O(N * M)', 'O(N * M)', '2026-11-20T06:28:30.826Z', '2026-11-20T06:28:30.826Z') ON CONFLICT DO NOTHING;
