INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2w017qo76vd7gic5ff', 'cmwollk2w017po76v0jk4ji62', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[] dijkstra(int V, ArrayList<ArrayList<ArrayList<Integer>>> adj, int S) {
        int[] dist = new int[V];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[S] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.add(new int[]{0, S});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], node = top[1];
            if (d > dist[node]) continue;
            for (ArrayList<Integer> it : adj.get(node)) {
                int adjNode = it.get(0), weight = it.get(1);
                if (d + weight < dist[adjNode]) {
                    dist[adjNode] = d + weight;
                    pq.add(new int[]{dist[adjNode], adjNode});
                }
            }
        }
        return dist;
    }
}', 'O(E log V)', 'O(V)', '2026-11-20T06:28:30.824Z', '2026-11-20T06:28:30.824Z') ON CONFLICT DO NOTHING;
