INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk2z0182o76vs3ruoyke', 'cmwollk2z0181o76vbjfed4u0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int minimumEffortPath(int[][] heights) {
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        int n = heights.length, m = heights[0].length;
        int[][] dist = new int[n][m];
        for (int[] r : dist) Arrays.fill(r, (int) 1e9);
        dist[0][0] = 0;
        pq.add(new int[]{0, 0, 0});
        int[] dr = {-1, 0, 1, 0}, dc = {0, 1, 0, -1};
        while (!pq.isEmpty()) {
            int[] it = pq.poll();
            int diff = it[0], r = it[1], c = it[2];
            if (r == n - 1 && c == m - 1) return diff;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int newEffort = Math.max(Math.abs(heights[r][c] - heights[nr][nc]), diff);
                    if (newEffort < dist[nr][nc]) {
                        dist[nr][nc] = newEffort;
                        pq.add(new int[]{dist[nr][nc], nr, nc});
                    }
                }
            }
        }
        return 0;
    }
}', 'O(N * M log(N * M))', 'O(N * M)', '2026-11-20T06:28:30.827Z', '2026-11-20T06:28:30.827Z') ON CONFLICT DO NOTHING;
