}', 'O(N * M log(N * M))', 'O(N * M)', '2026-11-20T06:28:30.827Z', '2026-11-20T06:28:30.827Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk300186o76vpqcm3osi', 'cmwollk300185o76vlwibzfv6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] f : flights) adj.get(f[0]).add(new int[]{f[1], f[2]});
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{0, src, 0});
        int[] dist = new int[n];
        Arrays.fill(dist, (int) 1e9);
        dist[src] = 0;
        while (!q.isEmpty()) {
            int[] it = q.poll();
            int stops = it[0], node = it[1], cost = it[2];
            if (stops > k) continue;
            for (int[] next : adj.get(node)) {
                int adjNode = next[0], edW = next[1];
                if (cost + edW < dist[adjNode] && stops <= k) {
                    dist[adjNode] = cost + edW;
                    q.add(new int[]{stops + 1, adjNode, cost + edW});
                }
            }
        }
        return dist[dst] == 1e9 ? -1 : dist[dst];
    }
}', 'O(E * K)', 'O(V + E)', '2026-11-20T06:28:30.828Z', '2026-11-20T06:28:30.828Z') ON CONFLICT DO NOTHING;
