INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk31018ao76v7tlupj70', 'cmwollk310189o76vb02ku8q3', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int minimumMultiplications(int[] arr, int start, int end) {
        if (start == end) return 0;
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{start, 0});
        int[] dist = new int[100000];
        Arrays.fill(dist, (int) 1e9);
        dist[start] = 0;
        int mod = 100000;
        while (!q.isEmpty()) {
            int[] it = q.poll();
            int node = it[0], steps = it[1];
            for (int num : arr) {
                int next = (node * num) % mod;
                if (steps + 1 < dist[next]) {
                    dist[next] = steps + 1;
                    if (next == end) return steps + 1;
                    q.add(new int[]{next, steps + 1});
                }
            }
        }
        return -1;
    }
}', 'O(100000 * N)', 'O(100000)', '2026-11-20T06:28:30.829Z', '2026-11-20T06:28:30.829Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3a0197o76vlngojm0j', 'cmwollk3a0195o76vhvly48vi', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    static class DisjointSet {
        int[] parent, size;
        DisjointSet(int n) {
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 0; i <= n; i++) { parent[i] = i; size[i] = 1; }
        }
        int findUPar(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findUPar(parent[node]);
        }
        void unionBySize(int u, int v) {
            int ulp_u = findUPar(u), ulp_v = findUPar(v);
            if (ulp_u == ulp_v) return;
            if (size[ulp_u] < size[ulp_v]) { parent[ulp_u] = ulp_v; size[ulp_v] += size[ulp_u]; }
            else { parent[ulp_v] = ulp_u; size[ulp_u] += size[ulp_v]; }
        }
    }
}', 'O(4 * alpha)', 'O(N)', '2026-11-20T06:28:30.838Z', '2026-11-20T06:28:30.838Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk32018eo76vna55wugu', 'cmwollk32018do76vv1e0pvfn', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int countPaths(int n, int[][] roads) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] r : roads) {
            adj.get(r[0]).add(new int[]{r[1], r[2]});
            adj.get(r[1]).add(new int[]{r[0], r[2]});
        }
        long[] dist = new long[n];
        int[] ways = new int[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        ways[0] = 1;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.add(new long[]{0, 0});
        int mod = (int) 1e9 + 7;
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0]; int node = (int) top[1];
            if (d > dist[node]) continue;
            for (int[] next : adj.get(node)) {
                int adjNode = next[0], w = next[1];
                if (d + w < dist[adjNode]) {
                    dist[adjNode] = d + w;
                    ways[adjNode] = ways[node];
                    pq.add(new long[]{dist[adjNode], adjNode});
                } else if (d + w == dist[adjNode]) {
                    ways[adjNode] = (ways[adjNode] + ways[node]) % mod;
                }
            }
        }
        return ways[n - 1];
    }
}', 'O(E log V)', 'O(V)', '2026-11-20T06:28:30.830Z', '2026-11-20T06:28:30.830Z') ON CONFLICT DO NOTHING;
