INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk33018io76viulmry09', 'cmwollk33018ho76v1g2f1tv7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int[] bellman_ford(int V, ArrayList<ArrayList<Integer>> edges, int S) {
        int[] dist = new int[V];
        Arrays.fill(dist, (int) 1e8);
        dist[S] = 0;
        for (int i = 0; i < V - 1; i++) {
            for (ArrayList<Integer> it : edges) {
                int u = it.get(0), v = it.get(1), wt = it.get(2);
                if (dist[u] != 1e8 && dist[u] + wt < dist[v]) {
                    dist[v] = dist[u] + wt;
                }
            }
        }
        for (ArrayList<Integer> it : edges) {
            int u = it.get(0), v = it.get(1), wt = it.get(2);
            if (dist[u] != 1e8 && dist[u] + wt < dist[v]) return new int[]{-1};
        }
        return dist;
    }
}', 'O(V * E)', 'O(V)', '2026-11-20T06:28:30.832Z', '2026-11-20T06:28:30.832Z') ON CONFLICT DO NOTHING;
