INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk34018mo76ve8e16hhe', 'cmwollk34018lo76vk06awcps', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static void shortest_distance(int[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == -1) matrix[i][j] = (int) 1e9;
                if (i == j) matrix[i][j] = 0;
            }
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    matrix[i][j] = Math.min(matrix[i][j], matrix[i][k] + matrix[k][j]);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1e9) matrix[i][j] = -1;
            }
        }
    }
}', 'O(V³)', 'O(1)', '2026-11-20T06:28:30.833Z', '2026-11-20T06:28:30.833Z') ON CONFLICT DO NOTHING;
