INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk38018yo76vmiyo5ubg', 'cmwollk38018xo76vmfqd098k', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int swimInWater(int[][] grid) {
        int n = grid.length;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        boolean[][] vis = new boolean[n][n];
        pq.add(new int[]{grid[0][0], 0, 0});
        vis[0][0] = true;
        int[] dr = {-1, 0, 1, 0}, dc = {0, 1, 0, -1};
        while (!pq.isEmpty()) {
            int[] it = pq.poll();
            int t = it[0], r = it[1], c = it[2];
            if (r == n - 1 && c == n - 1) return t;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !vis[nr][nc]) {
                    vis[nr][nc] = true;
                    pq.add(new int[]{Math.max(t, grid[nr][nc]), nr, nc});
                }
            }
        }
        return 0;
    }
}', 'O(N² log N)', 'O(N²)', '2026-11-20T06:28:30.836Z', '2026-11-20T06:28:30.836Z') ON CONFLICT DO NOTHING;
