INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3a0196o76vn71pl7ny', 'cmwollk3a0195o76vhvly48vi', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    static class DisjointSet {
        int[] parent, rank;
        DisjointSet(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 0; i <= n; i++) parent[i] = i;
        }
        int findUPar(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findUPar(parent[node]);
        }
        void unionByRank(int u, int v) {
            int ulp_u = findUPar(u), ulp_v = findUPar(v);
            if (ulp_u == ulp_v) return;
            if (rank[ulp_u] < rank[ulp_v]) parent[ulp_u] = ulp_v;
            else if (rank[ulp_v] < rank[ulp_u]) parent[ulp_v] = ulp_u;
            else { parent[ulp_v] = ulp_u; rank[ulp_u]++; }
        }
    }
}', 'O(4 * alpha)', 'O(N)', '2026-11-20T06:28:30.838Z', '2026-11-20T06:28:30.838Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4201cfo76va8xqxi7t', 'cmwollk4201cdo76vo9mjxfy5', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static boolean subsetSumToK(int n, int k, int arr[]) {
        boolean[] prev = new boolean[k + 1];
        prev[0] = true;
        if (arr[0] <= k) prev[arr[0]] = true;
        for (int ind = 1; ind < n; ind++) {
            boolean[] cur = new boolean[k + 1];
            cur[0] = true;
            for (int target = 1; target <= k; target++) {
                boolean notTaken = prev[target];
                boolean taken = false;
                if (arr[ind] <= target) taken = prev[target - arr[ind]];
                cur[target] = notTaken || taken;
            }
            prev = cur;
        }
        return prev[k];
    }
}', 'O(N * Target)', 'O(Target)', '2026-11-20T06:28:30.867Z', '2026-11-20T06:28:30.867Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3b019ao76vf0ed69dn', 'cmwollk3b0199o76vwfdb2kdn', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int spanningTree(int V, int E, int edges[][]) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        boolean[] vis = new boolean[V];
        pq.add(new int[]{0, 0});
        int sum = 0;
        while (!pq.isEmpty()) {
            int[] it = pq.poll();
            int wt = it[0], node = it[1];
            if (vis[node]) continue;
            vis[node] = true;
            sum += wt;
            for (int[] next : adj.get(node)) {
                if (!vis[next[0]]) pq.add(new int[]{next[1], next[0]});
            }
        }
        return sum;
    }
}', 'O(E log E)', 'O(E + V)', '2026-11-20T06:28:30.839Z', '2026-11-20T06:28:30.839Z') ON CONFLICT DO NOTHING;
