INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3k01a6o76vhi5rvo6y', 'cmwollk3k01a5o76voyoykqmo', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    private static int timer = 1;

    public static ArrayList<Integer> articulationPoints(int V, ArrayList<ArrayList<Integer>> adj) {
        int[] tin = new int[V], low = new int[V];
        boolean[] vis = new boolean[V];
        int[] mark = new int[V];
        timer = 1;
        for (int i = 0; i < V; i++) if (!vis[i]) dfs(i, -1, vis, tin, low, mark, adj);
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = 0; i < V; i++) if (mark[i] == 1) ans.add(i);
        if (ans.isEmpty()) ans.add(-1);
        return ans;
    }

    private static void dfs(int node, int parent, boolean[] vis, int[] tin, int[] low, int[] mark, ArrayList<ArrayList<Integer>> adj) {
        vis[node] = true;
        tin[node] = low[node] = timer++;
        int child = 0;
        for (int it : adj.get(node)) {
            if (it == parent) continue;
            if (!vis[it]) {
                dfs(it, node, vis, tin, low, mark, adj);
                low[node] = Math.min(low[node], low[it]);
                if (low[it] >= tin[node] && parent != -1) mark[node] = 1;
                child++;
            } else {
                low[node] = Math.min(low[node], tin[it]);
            }
        }
        if (child > 1 && parent == -1) mark[node] = 1;
    }
}', 'O(V + 2E)', 'O(V)', '2026-11-20T06:28:30.849Z', '2026-11-20T06:28:30.849Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3f019mo76v5baful0i', 'cmwollk3f019lo76vrdnsqv3d', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static List<Integer> numOfIslands(int rows, int cols, int[][] operators) {
        DisjointSet ds = new DisjointSet(rows * cols);
        boolean[][] vis = new boolean[rows][cols];
        List<Integer> ans = new ArrayList<>();
        int cnt = 0;
        int[] dr = {-1, 0, 1, 0}, dc = {0, 1, 0, -1};
        for (int[] op : operators) {
            int r = op[0], c = op[1];
            if (vis[r][c]) { ans.add(cnt); continue; }
            vis[r][c] = true;
            cnt++;
            int nodeNo = r * cols + c;
            for (int ind = 0; ind < 4; ind++) {
                int adjr = r + dr[ind], adjc = c + dc[ind];
                if (adjr >= 0 && adjr < rows && adjc >= 0 && adjc < cols && vis[adjr][adjc]) {
                    int adjNodeNo = adjr * cols + adjc;
                    if (ds.findUPar(nodeNo) != ds.findUPar(adjNodeNo)) {
                        cnt--;
                        ds.unionBySize(nodeNo, adjNodeNo);
                    }
                }
            }
            ans.add(cnt);
        }
        return ans;
    }

    static class DisjointSet {
        int[] parent, size;
        DisjointSet(int n) {
            parent = new int[n]; size = new int[n];
            for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        }
        int findUPar(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findUPar(parent[node]);
        }
        void unionBySize(int u, int v) {
            int ulp_u = findUPar(u), ulp_v = findUPar(v);
            if (ulp_u == ulp_v) return;
            if (size[ulp_u] < size[ulp_v]) { parent[ulp_u] = ulp_v; size[ulp_v] += size[ulp_u]; }
            else { parent[ulp_v] = ulp_u; size[ulp_u] += size[ulp_v]; }
        }
    }
}', 'O(K * 4*alpha)', 'O(R * C)', '2026-11-20T06:28:30.843Z', '2026-11-20T06:28:30.843Z') ON CONFLICT DO NOTHING;
