INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3g019qo76vll2xouov', 'cmwollk3g019po76v4br5x4y5', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int largestIsland(int[][] grid) {
        int n = grid.length;
        DisjointSet ds = new DisjointSet(n * n);
        int[] dr = {-1, 0, 1, 0}, dc = {0, 1, 0, -1};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    for (int ind = 0; ind < 4; ind++) {
                        int nr = r + dr[ind], nc = c + dc[ind];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            ds.unionBySize(r * n + c, nr * n + nc);
                        }
                    }
                }
            }
        }
        int mx = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> components = new HashSet<>();
                    for (int ind = 0; ind < 4; ind++) {
                        int nr = r + dr[ind], nc = c + dc[ind];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            components.add(ds.findUPar(nr * n + nc));
                        }
                    }
                    int totalSize = 1;
                    for (int root : components) totalSize += ds.size[root];
                    mx = Math.max(mx, totalSize);
                }
            }
        }
        for (int i = 0; i < n * n; i++) mx = Math.max(mx, ds.size[ds.findUPar(i)]);
        return mx;
    }

    static class DisjointSet {
        int[] parent, size;
        DisjointSet(int n) {
            parent = new int[n]; size = new int[n];
            for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        }
        int findUPar(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findUPar(parent[node]);
        }
        void unionBySize(int u, int v) {
            int ulp_u = findUPar(u), ulp_v = findUPar(v);
            if (ulp_u == ulp_v) return;
            if (size[ulp_u] < size[ulp_v]) { parent[ulp_u] = ulp_v; size[ulp_v] += size[ulp_u]; }
            else { parent[ulp_v] = ulp_u; size[ulp_u] += size[ulp_v]; }
