INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3g019ro76vnl691dxv', 'cmwollk3g019po76v4br5x4y5', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    public static int largestIsland(int[][] grid) {
        int n = grid.length;
        DisjointSet ds = new DisjointSet(n * n);
        int[] dr = {-1, 0, 1, 0}, dc = {0, 1, 0, -1};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    for (int ind = 0; ind < 4; ind++) {
                        int nr = r + dr[ind], nc = c + dc[ind];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            ds.unionBySize(r * n + c, nr * n + nc);
                        }
                    }
                }
            }
        }
        int mx = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> components = new HashSet<>();
                    for (int ind = 0; ind < 4; ind++) {
                        int nr = r + dr[ind], nc = c + dc[ind];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            components.add(ds.findUPar(nr * n + nc));
                        }
                    }
                    int totalSize = 1;
                    for (int root : components) totalSize += ds.size[root];
                    mx = Math.max(mx, totalSize);
                }
            }
        }
        for (int i = 0; i < n * n; i++) mx = Math.max(mx, ds.size[ds.findUPar(i)]);
        return mx;
    }

    static class DisjointSet {
        int[] parent, size;
        DisjointSet(int n) {
            parent = new int[n]; size = new int[n];
            for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        }
        int findUPar(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findUPar(parent[node]);
        }
        void unionBySize(int u, int v) {
            int ulp_u = findUPar(u), ulp_v = findUPar(v);
            if (ulp_u == ulp_v) return;
            if (size[ulp_u] < size[ulp_v]) { parent[ulp_u] = ulp_v; size[ulp_v] += size[ulp_u]; }
            else { parent[ulp_v] = ulp_u; size[ulp_u] += size[ulp_v]; }
        }
    }
}', 'O(N²)', 'O(N²)', '2026-11-20T06:28:30.844Z', '2026-11-20T06:28:30.844Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3h019uo76va054htb4', 'cmwollk3h019to76vr07xqcr1', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    public static int removeStones(int[][] stones) {
        int maxRow = 0, maxCol = 0;
        for (int[] s : stones) { maxRow = Math.max(maxRow, s[0]); maxCol = Math.max(maxCol, s[1]); }
        DisjointSet ds = new DisjointSet(maxRow + maxCol + 1);
        Map<Integer, Integer> stoneNodes = new HashMap<>();
        for (int[] s : stones) {
            int nodeRow = s[0], nodeCol = s[1] + maxRow + 1;
            ds.unionBySize(nodeRow, nodeCol);
            stoneNodes.put(nodeRow, 1);
            stoneNodes.put(nodeCol, 1);
        }
        int cnt = 0;
        for (int it : stoneNodes.keySet()) if (ds.findUPar(it) == it) cnt++;
        return stones.length - cnt;
    }

    static class DisjointSet {
        int[] parent, size;
        DisjointSet(int n) {
            parent = new int[n + 1]; size = new int[n + 1];
            for (int i = 0; i <= n; i++) { parent[i] = i; size[i] = 1; }
        }
        int findUPar(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findUPar(parent[node]);
        }
        void unionBySize(int u, int v) {
            int ulp_u = findUPar(u), ulp_v = findUPar(v);
            if (ulp_u == ulp_v) return;
            if (size[ulp_u] < size[ulp_v]) { parent[ulp_u] = ulp_v; size[ulp_v] += size[ulp_u]; }
            else { parent[ulp_v] = ulp_u; size[ulp_u] += size[ulp_v]; }
        }
    }
}', 'O(N * 4*alpha)', 'O(max(R, C))', '2026-11-20T06:28:30.846Z', '2026-11-20T06:28:30.846Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4a01d6o76v16dw5u18', 'cmwollk4a01d5o76v7819r33d', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        return solve(0, 0, target, nums);
    }
    private int solve(int ind, int curSum, int target, int[] nums) {
        if (ind == nums.length) return (curSum == target) ? 1 : 0;
        return solve(ind + 1, curSum + nums[ind], target, nums) + solve(ind + 1, curSum - nums[ind], target, nums);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.875Z', '2026-11-20T06:28:30.875Z') ON CONFLICT DO NOTHING;
