INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3k01a2o76vtzcwgiiu', 'cmwollk3k01a1o76vz5gab8tf', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;

public class Solution {
    private static int timer = 1;

    public static List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (List<Integer> it : connections) {
            adj.get(it.get(0)).add(it.get(1));
            adj.get(it.get(1)).add(it.get(0));
        }
        int[] tin = new int[n], low = new int[n];
        boolean[] vis = new boolean[n];
        List<List<Integer>> bridges = new ArrayList<>();
        timer = 1;
        dfs(0, -1, vis, adj, tin, low, bridges);
        return bridges;
    }

    private static void dfs(int node, int parent, boolean[] vis, List<List<Integer>> adj, int[] tin, int[] low, List<List<Integer>> bridges) {
        vis[node] = true;
        tin[node] = low[node] = timer++;
        for (int it : adj.get(node)) {
            if (it == parent) continue;
            if (!vis[it]) {
                dfs(it, node, vis, adj, tin, low, bridges);
                low[node] = Math.min(low[node], low[it]);
                if (low[it] > tin[node]) bridges.add(Arrays.asList(node, it));
            } else {
                low[node] = Math.min(low[node], tin[it]);
            }
        }
    }
}', 'O(V + 2E)', 'O(V + 2E)', '2026-11-20T06:28:30.848Z', '2026-11-20T06:28:30.848Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3k01a3o76vfqopx34p', 'cmwollk3k01a1o76vz5gab8tf', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

