INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3q01ayo76vfj8cos2v', 'cmwollk3q01axo76vnscctzln', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int ninjaTraining(int n, int points[][]) {
        return solve(n - 1, 3, points);
    }
    private static int solve(int day, int last, int[][] points) {
        if (day == 0) {
            int maxi = 0;
            for (int i = 0; i <= 2; i++) {
                if (i != last) maxi = Math.max(maxi, points[0][i]);
            }
            return maxi;
        }
        int maxi = 0;
        for (int i = 0; i <= 2; i++) {
            if (i != last) {
                int point = points[day][i] + solve(day - 1, i, points);
                maxi = Math.max(maxi, point);
            }
        }
        return maxi;
    }
}', 'O(3^N)', 'O(N)', '2026-11-20T06:28:30.855Z', '2026-11-20T06:28:30.855Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3k01a7o76vgbl7w7yf', 'cmwollk3k01a5o76voyoykqmo', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;

public class Solution {
    private static int timer = 1;

    public static ArrayList<Integer> articulationPoints(int V, ArrayList<ArrayList<Integer>> adj) {
        int[] tin = new int[V], low = new int[V];
        boolean[] vis = new boolean[V];
        int[] mark = new int[V];
        timer = 1;
        for (int i = 0; i < V; i++) if (!vis[i]) dfs(i, -1, vis, tin, low, mark, adj);
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = 0; i < V; i++) if (mark[i] == 1) ans.add(i);
        if (ans.isEmpty()) ans.add(-1);
        return ans;
    }

    private static void dfs(int node, int parent, boolean[] vis, int[] tin, int[] low, int[] mark, ArrayList<ArrayList<Integer>> adj) {
        vis[node] = true;
        tin[node] = low[node] = timer++;
        int child = 0;
        for (int it : adj.get(node)) {
            if (it == parent) continue;
            if (!vis[it]) {
                dfs(it, node, vis, tin, low, mark, adj);
                low[node] = Math.min(low[node], low[it]);
                if (low[it] >= tin[node] && parent != -1) mark[node] = 1;
                child++;
            } else {
                low[node] = Math.min(low[node], tin[it]);
            }
        }
        if (child > 1 && parent == -1) mark[node] = 1;
    }
}', 'O(V + 2E)', 'O(V)', '2026-11-20T06:28:30.849Z', '2026-11-20T06:28:30.849Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3l01aao76v2whisd9c', 'cmwollk3l01a9o76vpyqakn8h', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    // Memoization (Top-down)
    public static int fibMemo(int n, int[] dp) {
        if (n <= 1) return n;
        if (dp[n] != -1) return dp[n];
        return dp[n] = fibMemo(n - 1, dp) + fibMemo(n - 2, dp);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.850Z', '2026-11-20T06:28:30.850Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3l01abo76vdiis2kvz', 'cmwollk3l01a9o76vpyqakn8h', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    // Tabulation with Space Optimization (Bottom-up)
    public static int fib(int n) {
        if (n <= 1) return n;
        int prev2 = 0, prev = 1;
        for (int i = 2; i <= n; i++) {
            int cur = prev + prev2;
            prev2 = prev;
            prev = cur;
        }
        return prev;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.850Z', '2026-11-20T06:28:30.850Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3m01aeo76vmb8hgss3', 'cmwollk3m01ado76v9kohythj', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int climbStairs(int n) {
        if (n <= 1) return 1;
        return climbStairs(n - 1) + climbStairs(n - 2);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.851Z', '2026-11-20T06:28:30.851Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3m01afo76v2wbmk61d', 'cmwollk3m01ado76v9kohythj', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int climbStairs(int n) {
        if (n <= 1) return 1;
        int prev2 = 1, prev = 1;
        for (int i = 2; i <= n; i++) {
            int cur = prev + prev2;
            prev2 = prev;
            prev = cur;
        }
        return prev;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.851Z', '2026-11-20T06:28:30.851Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3n01aio76vdlcuofq7', 'cmwollk3n01aho76volypbjbk', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int frogJump(int n, int heights[]) {
        return solve(n - 1, heights);
    }
    private static int solve(int ind, int[] h) {
        if (ind == 0) return 0;
        int left = solve(ind - 1, h) + Math.abs(h[ind] - h[ind - 1]);
        int right = Integer.MAX_VALUE;
        if (ind > 1) right = solve(ind - 2, h) + Math.abs(h[ind] - h[ind - 2]);
        return Math.min(left, right);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.851Z', '2026-11-20T06:28:30.851Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3n01ajo76vo1jko94t', 'cmwollk3n01aho76volypbjbk', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int frogJump(int n, int heights[]) {
        int prev = 0, prev2 = 0;
        for (int i = 1; i < n; i++) {
            int fs = prev + Math.abs(heights[i] - heights[i - 1]);
            int ss = Integer.MAX_VALUE;
            if (i > 1) ss = prev2 + Math.abs(heights[i] - heights[i - 2]);
            int cur = Math.min(fs, ss);
            prev2 = prev;
            prev = cur;
        }
        return prev;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.851Z', '2026-11-20T06:28:30.851Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3o01amo76ven87ye67', 'cmwollk3o01alo76vzztvrt35', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int minimizeCost(int n, int k, int[] height) {
        return solve(n - 1, k, height);
    }
    private static int solve(int ind, int k, int[] h) {
        if (ind == 0) return 0;
        int minCost = Integer.MAX_VALUE;
        for (int j = 1; j <= k; j++) {
            if (ind - j >= 0) {
                int cost = solve(ind - j, k, h) + Math.abs(h[ind] - h[ind - j]);
                minCost = Math.min(minCost, cost);
            }
        }
        return minCost;
    }
}', 'O(K^N)', 'O(N)', '2026-11-20T06:28:30.852Z', '2026-11-20T06:28:30.852Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3o01ano76v3yjp1dyq', 'cmwollk3o01alo76vzztvrt35', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int minimizeCost(int n, int k, int[] height) {
        int[] dp = new int[n];
        dp[0] = 0;
        for (int i = 1; i < n; i++) {
            int minCost = Integer.MAX_VALUE;
            for (int j = 1; j <= k; j++) {
                if (i - j >= 0) {
                    int jump = dp[i - j] + Math.abs(height[i] - height[i - j]);
                    minCost = Math.min(minCost, jump);
                }
            }
            dp[i] = minCost;
        }
        return dp[n - 1];
    }
}', 'O(N * K)', 'O(N)', '2026-11-20T06:28:30.852Z', '2026-11-20T06:28:30.852Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3p01aqo76vf8h3yfn7', 'cmwollk3p01apo76v9t4fxmmg', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public static int maximumNonAdjacentSum(ArrayList<Integer> nums) {
        return solve(nums.size() - 1, nums);
    }
    private static int solve(int ind, ArrayList<Integer> nums) {
        if (ind == 0) return nums.get(0);
        if (ind < 0) return 0;
        int pick = nums.get(ind) + solve(ind - 2, nums);
        int notPick = solve(ind - 1, nums);
        return Math.max(pick, notPick);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.853Z', '2026-11-20T06:28:30.853Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3p01aro76vkvbsz5v3', 'cmwollk3p01apo76v9t4fxmmg', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public static int maximumNonAdjacentSum(ArrayList<Integer> nums) {
        int n = nums.size();
        int prev = nums.get(0), prev2 = 0;
        for (int i = 1; i < n; i++) {
            int take = nums.get(i) + (i > 1 ? prev2 : 0);
            int notTake = prev;
            int cur = Math.max(take, notTake);
            prev2 = prev;
            prev = cur;
        }
        return prev;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.853Z', '2026-11-20T06:28:30.853Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3p01auo76vparleh3j', 'cmwollk3p01ato76vf7y1hgfy', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int rob(int[] nums) {
        if (nums.length == 1) return nums[0];
        return Math.max(robRange(nums, 0, nums.length - 2), robRange(nums, 1, nums.length - 1));
    }
    private int robRange(int[] nums, int start, int end) {
        return solve(nums, end, start);
    }
    private int solve(int[] nums, int ind, int start) {
        if (ind < start) return 0;
        if (ind == start) return nums[start];
        return Math.max(nums[ind] + solve(nums, ind - 2, start), solve(nums, ind - 1, start));
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.854Z', '2026-11-20T06:28:30.854Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3p01avo76v2fqgzx1v', 'cmwollk3p01ato76vf7y1hgfy', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int rob(int[] nums) {
        if (nums.length == 1) return nums[0];
        return Math.max(robLinear(nums, 0, nums.length - 2), robLinear(nums, 1, nums.length - 1));
    }
    private int robLinear(int[] nums, int start, int end) {
        int prev = 0, prev2 = 0;
        for (int i = start; i <= end; i++) {
            int cur = Math.max(prev, prev2 + nums[i]);
            prev2 = prev;
            prev = cur;
        }
        return prev;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.854Z', '2026-11-20T06:28:30.854Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3q01azo76vrjo82ls4', 'cmwollk3q01axo76vnscctzln', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int ninjaTraining(int n, int points[][]) {
        int[] prev = new int[4];
        prev[0] = Math.max(points[0][1], points[0][2]);
        prev[1] = Math.max(points[0][0], points[0][2]);
        prev[2] = Math.max(points[0][0], points[0][1]);
        prev[3] = Math.max(points[0][0], Math.max(points[0][1], points[0][2]));

        for (int day = 1; day < n; day++) {
            int[] temp = new int[4];
            for (int last = 0; last < 4; last++) {
                temp[last] = 0;
                for (int task = 0; task <= 2; task++) {
                    if (task != last) {
                        temp[last] = Math.max(temp[last], points[day][task] + prev[task]);
                    }
                }
            }
            prev = temp;
        }
        return prev[3];
    }
}', 'O(N * 4 * 3)', 'O(1)', '2026-11-20T06:28:30.855Z', '2026-11-20T06:28:30.855Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3r01b2o76vxb0fddzb', 'cmwollk3r01b1o76vdvj1uhv0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int uniquePaths(int m, int n) {
        return solve(m - 1, n - 1);
    }
    private int solve(int i, int j) {
        if (i == 0 && j == 0) return 1;
        if (i < 0 || j < 0) return 0;
        return solve(i - 1, j) + solve(i, j - 1);
    }
}', 'O(2^(M+N))', 'O(M+N)', '2026-11-20T06:28:30.855Z', '2026-11-20T06:28:30.855Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3r01b3o76v5s2t9cjk', 'cmwollk3r01b1o76vdvj1uhv0', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int uniquePaths(int m, int n) {
        int N = m + n - 2;
        int r = Math.min(m - 1, n - 1);
        double res = 1;
        for (int i = 1; i <= r; i++) {
            res = res * (N - r + i) / i;
        }
        return (int) Math.round(res);
    }
}', 'O(min(M, N))', 'O(1)', '2026-11-20T06:28:30.855Z', '2026-11-20T06:28:30.855Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3s01b6o76vafszdtho', 'cmwollk3s01b5o76vspr71pfq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int uniquePathsWithObstacles(int[][] grid) {
        return solve(grid.length - 1, grid[0].length - 1, grid);
    }
    private int solve(int i, int j, int[][] grid) {
        if (i < 0 || j < 0 || grid[i][j] == 1) return 0;
        if (i == 0 && j == 0) return 1;
        return solve(i - 1, j, grid) + solve(i, j - 1, grid);
    }
}', 'O(2^(M+N))', 'O(M+N)', '2026-11-20T06:28:30.856Z', '2026-11-20T06:28:30.856Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3s01b7o76v1vms540i', 'cmwollk3s01b5o76vspr71pfq', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int uniquePathsWithObstacles(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] dp = new int[n];
        dp[0] = (grid[0][0] == 0) ? 1 : 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dp[j] = 0;
                } else if (j > 0) {
                    dp[j] += dp[j - 1];
                }
            }
        }
        return dp[n - 1];
    }
}', 'O(M * N)', 'O(N)', '2026-11-20T06:28:30.856Z', '2026-11-20T06:28:30.856Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3s01bao76vgqergei6', 'cmwollk3s01b9o76vi0mq677u', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int minFallingPathSum(int[][] matrix) {
        int n = matrix.length, ans = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            ans = Math.min(ans, solve(0, j, matrix));
        }
        return ans;
    }
    private int solve(int i, int j, int[][] mat) {
        if (j < 0 || j >= mat.length) return (int) 1e9;
        if (i == mat.length - 1) return mat[i][j];
        int down = mat[i][j] + solve(i + 1, j, mat);
        int ld = mat[i][j] + solve(i + 1, j - 1, mat);
        int rd = mat[i][j] + solve(i + 1, j + 1, mat);
        return Math.min(down, Math.min(ld, rd));
    }
}', 'O(3^N)', 'O(N)', '2026-11-20T06:28:30.857Z', '2026-11-20T06:28:30.857Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3s01bbo76vsicsyrlq', 'cmwollk3s01b9o76vi0mq677u', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int minFallingPathSum(int[][] matrix) {
        int n = matrix.length;
        int[] prev = matrix[0].clone();
        for (int i = 1; i < n; i++) {
            int[] cur = new int[n];
            for (int j = 0; j < n; j++) {
                int up = prev[j];
                int ld = (j > 0) ? prev[j - 1] : (int) 1e9;
                int rd = (j < n - 1) ? prev[j + 1] : (int) 1e9;
                cur[j] = matrix[i][j] + Math.min(up, Math.min(ld, rd));
            }
            prev = cur;
        }
        int min = Integer.MAX_VALUE;
        for (int val : prev) min = Math.min(min, val);
        return min;
    }
}', 'O(N * N)', 'O(N)', '2026-11-20T06:28:30.857Z', '2026-11-20T06:28:30.857Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3t01beo76vosmel3xl', 'cmwollk3t01bdo76ves05p6t3', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        return solve(0, 0, triangle);
    }
    private int solve(int i, int j, List<List<Integer>> tri) {
        if (i == tri.size() - 1) return tri.get(i).get(j);
        int down = tri.get(i).get(j) + solve(i + 1, j, tri);
        int diag = tri.get(i).get(j) + solve(i + 1, j + 1, tri);
        return Math.min(down, diag);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.858Z', '2026-11-20T06:28:30.858Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3t01bfo76vivzfbh9p', 'cmwollk3t01bdo76ves05p6t3', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        int n = triangle.size();
        int[] dp = new int[n];
        for (int j = 0; j < n; j++) dp[j] = triangle.get(n - 1).get(j);
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j <= i; j++) {
                dp[j] = triangle.get(i).get(j) + Math.min(dp[j], dp[j + 1]);
            }
        }
        return dp[0];
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.858Z', '2026-11-20T06:28:30.858Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3u01bio76vy8najniw', 'cmwollk3u01bho76vellie500', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int cherryPickup(int[][] grid) {
        return solve(0, 0, grid[0].length - 1, grid);
    }
    private int solve(int i, int j1, int j2, int[][] grid) {
        if (j1 < 0 || j1 >= grid[0].length || j2 < 0 || j2 >= grid[0].length) return (int) -1e9;
        if (i == grid.length - 1) {
            return (j1 == j2) ? grid[i][j1] : grid[i][j1] + grid[i][j2];
        }
        int max = (int) -1e9;
        for (int dj1 = -1; dj1 <= 1; dj1++) {
            for (int dj2 = -1; dj2 <= 1; dj2++) {
                int value = (j1 == j2) ? grid[i][j1] : grid[i][j1] + grid[i][j2];
                value += solve(i + 1, j1 + dj1, j2 + dj2, grid);
                max = Math.max(max, value);
            }
        }
        return max;
    }
}', 'O(3^N * 3^N)', 'O(N)', '2026-11-20T06:28:30.859Z', '2026-11-20T06:28:30.859Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3u01bjo76vi1x5xoru', 'cmwollk3u01bho76vellie500', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int cherryPickup(int[][] grid) {
        int r = grid.length, c = grid[0].length;
        int[][] front = new int[c][c];
        for (int j1 = 0; j1 < c; j1++) {
            for (int j2 = 0; j2 < c; j2++) {
                front[j1][j2] = (j1 == j2) ? grid[r - 1][j1] : grid[r - 1][j1] + grid[r - 1][j2];
            }
        }
        for (int i = r - 2; i >= 0; i--) {
            int[][] cur = new int[c][c];
            for (int j1 = 0; j1 < c; j1++) {
                for (int j2 = 0; j2 < c; j2++) {
                    int max = (int) -1e9;
                    for (int dj1 = -1; dj1 <= 1; dj1++) {
                        for (int dj2 = -1; dj2 <= 1; dj2++) {
                            int nj1 = j1 + dj1, nj2 = j2 + dj2;
                            if (nj1 >= 0 && nj1 < c && nj2 >= 0 && nj2 < c) {
                                int val = (j1 == j2) ? grid[i][j1] : grid[i][j1] + grid[i][j2];
                                max = Math.max(max, val + front[nj1][nj2]);
                            }
                        }
                    }
                    cur[j1][j2] = max;
                }
            }
            front = cur;
        }
        return front[0][c - 1];
    }
}', 'O(R * C * C * 9)', 'O(C * C)', '2026-11-20T06:28:30.859Z', '2026-11-20T06:28:30.859Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3v01bmo76v27m5m7uk', 'cmwollk3v01blo76vtn9s0vc2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int countSquares(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length, count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    count += countFrom(i, j, matrix);
                }
            }
        }
        return count;
    }
    private int countFrom(int r, int c, int[][] mat) {
        int maxL = Math.min(mat.length - r, mat[0].length - c), cnt = 0;
        for (int len = 1; len <= maxL; len++) {
            boolean valid = true;
            for (int i = r; i < r + len && valid; i++) {
                for (int j = c; j < c + len && valid; j++) {
                    if (mat[i][j] == 0) valid = false;
                }
            }
            if (valid) cnt++;
            else break;
        }
        return cnt;
    }
}', 'O((M * N)^2)', 'O(1)', '2026-11-20T06:28:30.859Z', '2026-11-20T06:28:30.859Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3v01bno76vetajsc2e', 'cmwollk3v01blo76vtn9s0vc2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int countSquares(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int[][] dp = new int[m][n];
        int total = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    if (i == 0 || j == 0) dp[i][j] = 1;
                    else dp[i][j] = 1 + Math.min(dp[i - 1][j], Math.min(dp[i][j - 1], dp[i - 1][j - 1]));
                    total += dp[i][j];
                }
            }
        }
        return total;
    }
}', 'O(M * N)', 'O(M * N)', '2026-11-20T06:28:30.859Z', '2026-11-20T06:28:30.859Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3w01bqo76ve30et0nx', 'cmwollk3w01bpo76vwaltrw29', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        int maxProfit = 0;
        for (int i = 0; i < prices.length; i++) {
            for (int j = i + 1; j < prices.length; j++) {
                maxProfit = Math.max(maxProfit, prices[j] - prices[i]);
            }
        }
        return maxProfit;
    }
}', 'O(N^2)', 'O(1)', '2026-11-20T06:28:30.860Z', '2026-11-20T06:28:30.860Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3w01bro76v12muh8kb', 'cmwollk3w01bpo76vwaltrw29', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = Integer.MAX_VALUE, maxProfit = 0;
        for (int p : prices) {
            minPrice = Math.min(minPrice, p);
            maxProfit = Math.max(maxProfit, p - minPrice);
        }
        return maxProfit;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.860Z', '2026-11-20T06:28:30.860Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3x01buo76vaqabflqz', 'cmwollk3x01bto76v5gargyfa', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        return solve(0, 1, prices);
    }
    private int solve(int ind, int buy, int[] p) {
        if (ind == p.length) return 0;
        if (buy == 1) {
            return Math.max(-p[ind] + solve(ind + 1, 0, p), solve(ind + 1, 1, p));
        } else {
            return Math.max(p[ind] + solve(ind + 1, 1, p), solve(ind + 1, 0, p));
        }
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.861Z', '2026-11-20T06:28:30.861Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3x01bvo76v6qx44lrm', 'cmwollk3x01bto76v5gargyfa', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        int profit = 0;
        for (int i = 1; i < prices.length; i++) {
            if (prices[i] > prices[i - 1]) profit += prices[i] - prices[i - 1];
        }
        return profit;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.861Z', '2026-11-20T06:28:30.861Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3y01byo76v1fgtn51e', 'cmwollk3y01bxo76vohab0id9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        return solve(0, 1, 2, prices);
    }
    private int solve(int ind, int buy, int cap, int[] p) {
        if (ind == p.length || cap == 0) return 0;
        if (buy == 1) {
            return Math.max(-p[ind] + solve(ind + 1, 0, cap, p), solve(ind + 1, 1, cap, p));
        } else {
            return Math.max(p[ind] + solve(ind + 1, 1, cap - 1, p), solve(ind + 1, 0, cap, p));
        }
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.863Z', '2026-11-20T06:28:30.863Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3y01bzo76v0rpw4xsq', 'cmwollk3y01bxo76vohab0id9', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        int buy1 = Integer.MIN_VALUE, sell1 = 0;
        int buy2 = Integer.MIN_VALUE, sell2 = 0;
        for (int p : prices) {
            buy1 = Math.max(buy1, -p);
            sell1 = Math.max(sell1, buy1 + p);
            buy2 = Math.max(buy2, sell1 - p);
            sell2 = Math.max(sell2, buy2 + p);
        }
        return sell2;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.863Z', '2026-11-20T06:28:30.863Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3z01c2o76v3n0a4j82', 'cmwollk3z01c1o76vk8dymdhi', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxProfit(int k, int[] prices) {
        return solve(0, 1, k, prices);
    }
    private int solve(int ind, int buy, int cap, int[] p) {
        if (ind == p.length || cap == 0) return 0;
        if (buy == 1) {
            return Math.max(-p[ind] + solve(ind + 1, 0, cap, p), solve(ind + 1, 1, cap, p));
        } else {
            return Math.max(p[ind] + solve(ind + 1, 1, cap - 1, p), solve(ind + 1, 0, cap, p));
        }
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.864Z', '2026-11-20T06:28:30.864Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk3z01c3o76v4jgw9h7m', 'cmwollk3z01c1o76vk8dymdhi', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (n == 0 || k == 0) return 0;
        if (k >= n / 2) {
            int maxP = 0;
            for (int i = 1; i < n; i++) if (prices[i] > prices[i - 1]) maxP += prices[i] - prices[i - 1];
            return maxP;
        }
        int[][] dp = new int[k + 1][n];
        for (int i = 1; i <= k; i++) {
            int maxDiff = -prices[0];
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i][j - 1], prices[j] + maxDiff);
                maxDiff = Math.max(maxDiff, dp[i - 1][j] - prices[j]);
            }
        }
        return dp[k][n - 1];
    }
}', 'O(K * N)', 'O(K * N)', '2026-11-20T06:28:30.864Z', '2026-11-20T06:28:30.864Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4001c6o76vlj4u0iuo', 'cmwollk4001c5o76vnljl1imx', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxProfit(int[] prices, int fee) {
        return solve(0, 1, prices, fee);
    }
    private int solve(int ind, int buy, int[] p, int fee) {
        if (ind == p.length) return 0;
        if (buy == 1) {
            return Math.max(-p[ind] + solve(ind + 1, 0, p, fee), solve(ind + 1, 1, p, fee));
        } else {
            return Math.max(p[ind] - fee + solve(ind + 1, 1, p, fee), solve(ind + 1, 0, p, fee));
        }
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.865Z', '2026-11-20T06:28:30.865Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4001c7o76vetaxr1rq', 'cmwollk4001c5o76vnljl1imx', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxProfit(int[] prices, int fee) {
        int hold = -prices[0], cash = 0;
        for (int i = 1; i < prices.length; i++) {
            cash = Math.max(cash, hold + prices[i] - fee);
            hold = Math.max(hold, cash - prices[i]);
        }
        return cash;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.865Z', '2026-11-20T06:28:30.865Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4101cao76vhfmc5ssh', 'cmwollk4101c9o76vfar3gq0i', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxProfit(int[] prices) {
        return solve(0, 1, prices);
    }
    private int solve(int ind, int buy, int[] p) {
        if (ind >= p.length) return 0;
        if (buy == 1) {
            return Math.max(-p[ind] + solve(ind + 1, 0, p), solve(ind + 1, 1, p));
        } else {
            return Math.max(p[ind] + solve(ind + 2, 1, p), solve(ind + 1, 0, p));
        }
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.866Z', '2026-11-20T06:28:30.866Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4501cno76vffk14j4p', 'cmwollk4501clo76vzx8wrb7w', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int minSubsetSumDifference(int[] arr, int n) {
        int totSum = 0;
        for (int x : arr) totSum += x;
        boolean[] dp = new boolean[totSum / 2 + 1];
        dp[0] = true;
        for (int num : arr) {
            for (int j = totSum / 2; j >= num; j--) {
                dp[j] = dp[j] || dp[j - num];
            }
        }
        int minDiff = Integer.MAX_VALUE;
        for (int s1 = 0; s1 <= totSum / 2; s1++) {
            if (dp[s1]) minDiff = Math.min(minDiff, Math.abs(totSum - 2 * s1));
        }
        return minDiff;
    }
}', 'O(N * TotSum)', 'O(TotSum)', '2026-11-20T06:28:30.869Z', '2026-11-20T06:28:30.869Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4601cqo76vtkewj30g', 'cmwollk4601cpo76vy6e7e752', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findWays(int num[], int tar) {
        return solve(num.length - 1, tar, num);
    }
    private static int solve(int ind, int target, int[] num) {
        if (ind == 0) {
            if (target == 0 && num[0] == 0) return 2;
            if (target == 0 || target == num[0]) return 1;
            return 0;
        }
        int notTake = solve(ind - 1, target, num);
        int take = 0;
        if (num[ind] <= target) take = solve(ind - 1, target - num[ind], num);
        return notTake + take;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.870Z', '2026-11-20T06:28:30.870Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4601cro76vo5ijasxs', 'cmwollk4601cpo76vy6e7e752', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int findWays(int num[], int tar) {
        int[] dp = new int[tar + 1];
        dp[0] = 1;
        for (int val : num) {
            for (int t = tar; t >= val; t--) {
                dp[t] = (dp[t] + dp[t - val]) % 1000000007;
            }
        }
        return dp[tar];
    }
}', 'O(N * Target)', 'O(Target)', '2026-11-20T06:28:30.870Z', '2026-11-20T06:28:30.870Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4701cuo76vnzok4ex9', 'cmwollk4701cto76v7hho9vrj', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int countPartitions(int n, int d, int[] arr) {
        int tot = 0;
        for (int x : arr) tot += x;
        if (tot - d < 0 || (tot - d) % 2 != 0) return 0;
        return countSubsets(arr, (tot - d) / 2);
    }
    private static int countSubsets(int[] arr, int target) {
        int[] dp = new int[target + 1];
        dp[0] = 1;
        for (int val : arr) {
            for (int t = target; t >= val; t--) {
                dp[t] = (dp[t] + dp[t - val]) % 1000000007;
            }
        }
        return dp[target];
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.871Z', '2026-11-20T06:28:30.871Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4701cvo76visydpqc0', 'cmwollk4701cto76v7hho9vrj', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countPartitions(int n, int d, int[] arr) {
        int tot = 0;
        for (int x : arr) tot += x;
        if (tot - d < 0 || (tot - d) % 2 != 0) return 0;
        int target = (tot - d) / 2;
        int[] dp = new int[target + 1];
        dp[0] = 1;
        for (int val : arr) {
            for (int t = target; t >= val; t--) {
                dp[t] = (dp[t] + dp[t - val]) % 1000000007;
            }
        }
        return dp[target];
    }
}', 'O(N * Target)', 'O(Target)', '2026-11-20T06:28:30.871Z', '2026-11-20T06:28:30.871Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4801cyo76vdsjigcsv', 'cmwollk4801cxo76vops6fra7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int knapsack(int[] weight, int[] value, int n, int maxWeight) {
        return solve(n - 1, maxWeight, weight, value);
    }
    private static int solve(int ind, int W, int[] wt, int[] val) {
        if (ind == 0) return (wt[0] <= W) ? val[0] : 0;
        int notTake = solve(ind - 1, W, wt, val);
        int take = Integer.MIN_VALUE;
        if (wt[ind] <= W) take = val[ind] + solve(ind - 1, W - wt[ind], wt, val);
        return Math.max(notTake, take);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.872Z', '2026-11-20T06:28:30.872Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4801czo76vht6y3sf5', 'cmwollk4801cxo76vops6fra7', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int knapsack(int[] weight, int[] value, int n, int maxWeight) {
        int[] dp = new int[maxWeight + 1];
        for (int i = 0; i < n; i++) {
            for (int w = maxWeight; w >= weight[i]; w--) {
                dp[w] = Math.max(dp[w], value[i] + dp[w - weight[i]]);
            }
        }
        return dp[maxWeight];
    }
}', 'O(N * W)', 'O(W)', '2026-11-20T06:28:30.872Z', '2026-11-20T06:28:30.872Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4901d2o76v3sbugbaf', 'cmwollk4901d1o76vyt880awx', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int coinChange(int[] coins, int amount) {
        int res = solve(coins.length - 1, amount, coins);
        return (res >= (int) 1e9) ? -1 : res;
    }
    private int solve(int ind, int T, int[] coins) {
        if (ind == 0) {
            return (T % coins[0] == 0) ? T / coins[0] : (int) 1e9;
        }
        int notTake = solve(ind - 1, T, coins);
        int take = (int) 1e9;
        if (coins[ind] <= T) take = 1 + solve(ind, T - coins[ind], coins);
        return Math.min(notTake, take);
    }
}', 'O(2^Amount)', 'O(Amount)', '2026-11-20T06:28:30.873Z', '2026-11-20T06:28:30.873Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4901d3o76von5yoh5z', 'cmwollk4901d1o76vyt880awx', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;
public class Solution {
    public int coinChange(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;
        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (coin <= i) dp[i] = Math.min(dp[i], dp[i - coin] + 1);
            }
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }
}', 'O(N * Amount)', 'O(Amount)', '2026-11-20T06:28:30.873Z', '2026-11-20T06:28:30.873Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4b01dao76vw5codbiy', 'cmwollk4b01d9o76vammzymwq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int change(int amount, int[] coins) {
        return solve(coins.length - 1, amount, coins);
    }
    private int solve(int ind, int T, int[] coins) {
        if (ind == 0) return (T % coins[0] == 0) ? 1 : 0;
        int notTake = solve(ind - 1, T, coins);
        int take = 0;
        if (coins[ind] <= T) take = solve(ind, T - coins[ind], coins);
        return notTake + take;
    }
}', 'O(2^Amount)', 'O(Amount)', '2026-11-20T06:28:30.876Z', '2026-11-20T06:28:30.876Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4b01dbo76vg6qbrjew', 'cmwollk4b01d9o76vammzymwq', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int change(int amount, int[] coins) {
        int[] dp = new int[amount + 1];
        dp[0] = 1;
        for (int coin : coins) {
            for (int t = coin; t <= amount; t++) {
                dp[t] += dp[t - coin];
            }
        }
        return dp[amount];
    }
}', 'O(N * Amount)', 'O(Amount)', '2026-11-20T06:28:30.876Z', '2026-11-20T06:28:30.876Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4c01deo76vuuplpiau', 'cmwollk4c01ddo76vendhmzsb', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int unboundedKnapsack(int n, int w, int[] val, int[] wt) {
        return solve(n - 1, w, val, wt);
    }
    private static int solve(int ind, int W, int[] val, int[] wt) {
        if (ind == 0) return (W / wt[0]) * val[0];
        int notTake = solve(ind - 1, W, val, wt);
        int take = 0;
        if (wt[ind] <= W) take = val[ind] + solve(ind, W - wt[ind], val, wt);
        return Math.max(notTake, take);
    }
}', 'O(2^W)', 'O(W)', '2026-11-20T06:28:30.877Z', '2026-11-20T06:28:30.877Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4c01dfo76vn9tqwjv4', 'cmwollk4c01ddo76vendhmzsb', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int unboundedKnapsack(int n, int w, int[] val, int[] wt) {
        int[] dp = new int[w + 1];
        for (int i = 0; i < n; i++) {
            for (int cap = wt[i]; cap <= w; cap++) {
                dp[cap] = Math.max(dp[cap], val[i] + dp[cap - wt[i]]);
            }
        }
        return dp[w];
    }
}', 'O(N * W)', 'O(W)', '2026-11-20T06:28:30.877Z', '2026-11-20T06:28:30.877Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4f01dmo76vgwv0ug30', 'cmwollk4f01dlo76vndbqw6hz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int lengthOfLIS(int[] nums) {
        return solve(0, -1, nums);
    }
    private int solve(int ind, int prevInd, int[] nums) {
        if (ind == nums.length) return 0;
        int notTake = solve(ind + 1, prevInd, nums);
        int take = 0;
        if (prevInd == -1 || nums[ind] > nums[prevInd]) {
            take = 1 + solve(ind + 1, ind, nums);
        }
        return Math.max(notTake, take);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.879Z', '2026-11-20T06:28:30.879Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4f01dno76v11mxkjbe', 'cmwollk4f01dlo76vndbqw6hz', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public int lengthOfLIS(int[] nums) {
        List<Integer> tails = new ArrayList<>();
        for (int x : nums) {
            int idx = Collections.binarySearch(tails, x);
            if (idx < 0) idx = -(idx + 1);
            if (idx == tails.size()) tails.add(x);
            else tails.set(idx, x);
        }
        return tails.size();
    }
}', 'O(N log N)', 'O(N)', '2026-11-20T06:28:30.879Z', '2026-11-20T06:28:30.879Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4g01dqo76vqk7ctic9', 'cmwollk4g01dpo76v0r4m0dne', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public static ArrayList<Integer> printingLongestIncreasingSubsequence(int[] arr, int x) {
        int n = arr.length;
        int[] dp = new int[n];
        int[] hash = new int[n];
        Arrays.fill(dp, 1);
        int maxL = 1, lastIndex = 0;
        for (int i = 0; i < n; i++) {
            hash[i] = i;
            for (int prev = 0; prev < i; prev++) {
                if (arr[prev] < arr[i] && 1 + dp[prev] > dp[i]) {
                    dp[i] = 1 + dp[prev];
                    hash[i] = prev;
                }
            }
            if (dp[i] > maxL) {
                maxL = dp[i];
                lastIndex = i;
            }
        }
        ArrayList<Integer> res = new ArrayList<>();
        res.add(arr[lastIndex]);
        while (hash[lastIndex] != lastIndex) {
            lastIndex = hash[lastIndex];
            res.add(arr[lastIndex]);
        }
        Collections.reverse(res);
        return res;
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.880Z', '2026-11-20T06:28:30.880Z') ON CONFLICT DO NOTHING;
