    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.881Z', '2026-11-20T06:28:30.881Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4h01dvo76vpwcxijnr', 'cmwollk4h01dto76vk8g1gmov', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public List<Integer> largestDivisibleSubset(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        int[] dp = new int[n];
        int[] hash = new int[n];
        Arrays.fill(dp, 1);
        int maxL = 1, lastIdx = 0;
        for (int i = 0; i < n; i++) {
            hash[i] = i;
            for (int prev = 0; prev < i; prev++) {
                if (nums[i] % nums[prev] == 0 && 1 + dp[prev] > dp[i]) {
                    dp[i] = 1 + dp[prev];
                    hash[i] = prev;
                }
            }
            if (dp[i] > maxL) {
                maxL = dp[i];
                lastIdx = i;
            }
        }
        List<Integer> res = new ArrayList<>();
        res.add(nums[lastIdx]);
        while (hash[lastIdx] != lastIdx) {
            lastIdx = hash[lastIdx];
            res.add(nums[lastIdx]);
        }
        return res;
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.881Z', '2026-11-20T06:28:30.881Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4i01dyo76vec4wdd2n', 'cmwollk4i01dxo76vncjbyd5q', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public int longestStrChain(String[] words) {
        Arrays.sort(words, (a, b) -> a.length() - b.length());
        int n = words.length, maxL = 1;
        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        for (int i = 0; i < n; i++) {
            for (int prev = 0; prev < i; prev++) {
                if (checkPossible(words[i], words[prev]) && 1 + dp[prev] > dp[i]) {
                    dp[i] = 1 + dp[prev];
                }
            }
            maxL = Math.max(maxL, dp[i]);
        }
        return maxL;
    }
    private boolean checkPossible(String s1, String s2) {
        if (s1.length() != s2.length() + 1) return false;
        int first = 0, second = 0;
        while (first < s1.length()) {
            if (second < s2.length() && s1.charAt(first) == s2.charAt(second)) {
                first++; second++;
            } else {
                first++;
            }
        }
        return first == s1.length() && second == s2.length();
    }
}', 'O(N^2 * L)', 'O(N)', '2026-11-20T06:28:30.882Z', '2026-11-20T06:28:30.882Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4i01dzo76vxcy34077', 'cmwollk4i01dxo76vncjbyd5q', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public int longestStrChain(String[] words) {
        Arrays.sort(words, (a, b) -> a.length() - b.length());
        Map<String, Integer> dp = new HashMap<>();
        int res = 1;
        for (String w : words) {
            int best = 1;
            for (int i = 0; i < w.length(); i++) {
                String prev = w.substring(0, i) + w.substring(i + 1);
                best = Math.max(best, dp.getOrDefault(prev, 0) + 1);
            }
            dp.put(w, best);
            res = Math.max(res, best);
        }
        return res;
    }
}', 'O(N * L^2)', 'O(N)', '2026-11-20T06:28:30.882Z', '2026-11-20T06:28:30.882Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4t01f2o76vlfeaeioa', 'cmwollk4t01f1o76vul2uie66', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int minDistance(String word1, String word2) {
        return solve(word1.length() - 1, word2.length() - 1, word1, word2);
    }
    private int solve(int i, int j, String s1, String s2) {
        if (i < 0) return j + 1;
        if (j < 0) return i + 1;
        if (s1.charAt(i) == s2.charAt(j)) return solve(i - 1, j - 1, s1, s2);
        return 1 + Math.min(solve(i, j - 1, s1, s2), Math.min(solve(i - 1, j, s1, s2), solve(i - 1, j - 1, s1, s2)));
    }
}', 'O(3^(N+M))', 'O(N+M)', '2026-11-20T06:28:30.893Z', '2026-11-20T06:28:30.893Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4k01e2o76v79ji7a0i', 'cmwollk4k01e1o76v9l1delic', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;
public class Solution {
    public static int longestBitonicSequence(int[] arr, int n) {
        int[] dp1 = new int[n];
