        Arrays.fill(dp1, 1);
        Arrays.fill(dp2, 1);
        for (int i = 0; i < n; i++) {
            for (int prev = 0; prev < i; prev++) {
                if (arr[prev] < arr[i] && 1 + dp1[prev] > dp1[i]) dp1[i] = 1 + dp1[prev];
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int prev = n - 1; prev > i; prev--) {
                if (arr[prev] < arr[i] && 1 + dp2[prev] > dp2[i]) dp2[i] = 1 + dp2[prev];
            }
        }
        int maxi = 0;
        for (int i = 0; i < n; i++) maxi = Math.max(maxi, dp1[i] + dp2[i] - 1);
        return maxi;
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.884Z', '2026-11-20T06:28:30.884Z') ON CONFLICT DO NOTHING;
