INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4l01e6o76v1y6bf6ri', 'cmwollk4l01e5o76v6rnoz6e9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;
public class Solution {
    public int findNumberOfLIS(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        int[] count = new int[n];
        Arrays.fill(dp, 1);
        Arrays.fill(count, 1);
        int maxL = 1;
        for (int i = 0; i < n; i++) {
            for (int prev = 0; prev < i; prev++) {
                if (nums[prev] < nums[i]) {
                    if (dp[prev] + 1 > dp[i]) {
                        dp[i] = dp[prev] + 1;
                        count[i] = count[prev];
                    } else if (dp[prev] + 1 == dp[i]) {
                        count[i] += count[prev];
                    }
                }
            }
            maxL = Math.max(maxL, dp[i]);
        }
        int nos = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == maxL) nos += count[i];
        }
        return nos;
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.885Z', '2026-11-20T06:28:30.885Z') ON CONFLICT DO NOTHING;
