INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4m01eao76vu2ffxli6', 'cmwollk4m01e9o76v88njjgyi', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
