INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5f01heo76vlxmi594p', 'cmwollk5f01hdo76vnpryd1bb', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> search(String pat, String txt) {
        List<Integer> res = new ArrayList<>();
        int m = pat.length(), n = txt.length();
        for (int i = 0; i <= n - m; i++) {
            if (txt.substring(i, i + m).equals(pat)) {
                res.add(i);
            }
        }
        return res;
    }
}', 'O(N * M)', 'O(1)', '2026-11-20T06:28:30.916Z', '2026-11-20T06:28:30.916Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4m01ebo76vq8s4a9mc', 'cmwollk4m01e9o76v88njjgyi', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
