}', 'O(N * M)', 'O(M)', '2026-11-20T06:28:30.886Z', '2026-11-20T06:28:30.886Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4n01eeo76vozvr5h2z', 'cmwollk4n01edo76vgdxyxg2p', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int lcs(String str1, String str2) {
        int maxL = 0;
        for (int i = 0; i < str1.length(); i++) {
            for (int j = 0; j < str2.length(); j++) {
                int len = 0;
                while (i + len < str1.length() && j + len < str2.length() && str1.charAt(i + len) == str2.charAt(j + len)) {
                    len++;
                }
                maxL = Math.max(maxL, len);
            }
        }
        return maxL;
    }
}', 'O(N * M * min(N, M))', 'O(1)', '2026-11-20T06:28:30.887Z', '2026-11-20T06:28:30.887Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4n01efo76v98dgxba3', 'cmwollk4n01edo76vgdxyxg2p', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int lcs(String str1, String str2) {
