        int[] prev = new int[m + 1];
        int maxL = 0;
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[m + 1];
            for (int j = 1; j <= m; j++) {
                if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                    cur[j] = 1 + prev[j - 1];
                    maxL = Math.max(maxL, cur[j]);
                } else {
                    cur[j] = 0;
                }
            }
            prev = cur;
        }
