}', 'O(N * M)', 'O(M)', '2026-11-20T06:28:30.887Z', '2026-11-20T06:28:30.887Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4o01eio76v6qoh20sv', 'cmwollk4o01eho76vqst0jiev', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int longestPalindromeSubseq(String s) {
        return solve(0, s.length() - 1, s);
    }
    private int solve(int i, int j, String s) {
        if (i == j) return 1;
        if (i > j) return 0;
        if (s.charAt(i) == s.charAt(j)) return 2 + solve(i + 1, j - 1, s);
        return Math.max(solve(i + 1, j, s), solve(i, j - 1, s));
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.888Z', '2026-11-20T06:28:30.888Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4o01ejo76v5ibjc34x', 'cmwollk4o01eho76vqst0jiev', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int longestPalindromeSubseq(String s) {
        int n = s.length();
        String rev = new StringBuilder(s).reverse().toString();
        int[] prev = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) == rev.charAt(j - 1)) {
                    cur[j] = 1 + prev[j - 1];
                } else {
                    cur[j] = Math.max(prev[j], cur[j - 1]);
                }
            }
            prev = cur;
        }
        return prev[n];
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.888Z', '2026-11-20T06:28:30.888Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4p01emo76vaynjlhqg', 'cmwollk4p01elo76vb97i11y0', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int minInsertions(String s) {
        return s.length() - lps(s);
    }
    private int lps(String s) {
        return solve(0, s.length() - 1, s);
    }
    private int solve(int i, int j, String s) {
        if (i >= j) return (i == j) ? 1 : 0;
        if (s.charAt(i) == s.charAt(j)) return 2 + solve(i + 1, j - 1, s);
        return Math.max(solve(i + 1, j, s), solve(i, j - 1, s));
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.889Z', '2026-11-20T06:28:30.889Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4p01eno76vqbt5xxcr', 'cmwollk4p01elo76vb97i11y0', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int minInsertions(String s) {
        int n = s.length();
        String rev = new StringBuilder(s).reverse().toString();
        int[] prev = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) == rev.charAt(j - 1)) cur[j] = 1 + prev[j - 1];
                else cur[j] = Math.max(prev[j], cur[j - 1]);
            }
            prev = cur;
        }
        return n - prev[n];
    }
}', 'O(N^2)', 'O(N)', '2026-11-20T06:28:30.889Z', '2026-11-20T06:28:30.889Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4q01eqo76vvsnxyzf0', 'cmwollk4q01epo76v5hp0k7v2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int minDistance(String word1, String word2) {
        int n = word1.length(), m = word2.length();
        int lcs = lcs(word1, word2);
        return (n - lcs) + (m - lcs);
    }
    private int lcs(String s1, String s2) {
        int n = s1.length(), m = s2.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) dp[i][j] = 1 + dp[i - 1][j - 1];
                else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
        return dp[n][m];
    }
}', 'O(N * M)', 'O(N * M)', '2026-11-20T06:28:30.891Z', '2026-11-20T06:28:30.891Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4q01ero76vwc3cq6mc', 'cmwollk4q01epo76v5hp0k7v2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int minDistance(String word1, String word2) {
        int n = word1.length(), m = word2.length();
        int[] prev = new int[m + 1];
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[m + 1];
            for (int j = 1; j <= m; j++) {
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) cur[j] = 1 + prev[j - 1];
                else cur[j] = Math.max(prev[j], cur[j - 1]);
            }
            prev = cur;
        }
        return (n + m) - 2 * prev[m];
    }
}', 'O(N * M)', 'O(M)', '2026-11-20T06:28:30.891Z', '2026-11-20T06:28:30.891Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4r01euo76vsc0l7jnk', 'cmwollk4r01eto76v4e9y0z8k', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public String shortestCommonSupersequence(String str1, String str2) {
        int n = str1.length(), m = str2.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (str1.charAt(i - 1) == str2.charAt(j - 1)) dp[i][j] = 1 + dp[i - 1][j - 1];
                else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
        int i = n, j = m;
        StringBuilder sb = new StringBuilder();
        while (i > 0 && j > 0) {
            if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                sb.append(str1.charAt(i - 1));
                i--; j--;
            } else if (dp[i - 1][j] > dp[i][j - 1]) {
                sb.append(str1.charAt(i - 1));
                i--;
            } else {
                sb.append(str2.charAt(j - 1));
                j--;
            }
        }
        while (i > 0) { sb.append(str1.charAt(i - 1)); i--; }
        while (j > 0) { sb.append(str2.charAt(j - 1)); j--; }
        return sb.reverse().toString();
    }
}', 'O(N * M)', 'O(N * M)', '2026-11-20T06:28:30.892Z', '2026-11-20T06:28:30.892Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5k01i3o76v42xotq1j', 'cmwollk5k01i1o76vb0lkvegf', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> primeFactors(int n) {
        List<Integer> factors = new ArrayList<>();
        for (int i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }
        if (n > 1) factors.add(n);
        return factors;
    }
}', 'O(sqrt(N))', 'O(1)', '2026-11-20T06:28:30.921Z', '2026-11-20T06:28:30.921Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4r01evo76vsu26a6tu', 'cmwollk4r01eto76v4e9y0z8k', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public String shortestCommonSupersequence(String str1, String str2) {
        int n = str1.length(), m = str2.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (str1.charAt(i - 1) == str2.charAt(j - 1)) dp[i][j] = 1 + dp[i - 1][j - 1];
                else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
        int i = n, j = m;
        StringBuilder sb = new StringBuilder();
        while (i > 0 && j > 0) {
            if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                sb.append(str1.charAt(i - 1));
                i--; j--;
            } else if (dp[i - 1][j] > dp[i][j - 1]) {
                sb.append(str1.charAt(i - 1));
                i--;
            } else {
                sb.append(str2.charAt(j - 1));
                j--;
            }
        }
        while (i > 0) { sb.append(str1.charAt(i - 1)); i--; }
        while (j > 0) { sb.append(str2.charAt(j - 1)); j--; }
        return sb.reverse().toString();
    }
}', 'O(N * M)', 'O(N * M)', '2026-11-20T06:28:30.892Z', '2026-11-20T06:28:30.892Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4s01eyo76v02xzx4lu', 'cmwollk4s01exo76v6rnibbgk', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int numDistinct(String s, String t) {
        return solve(s.length() - 1, t.length() - 1, s, t);
    }
    private int solve(int i, int j, String s, String t) {
        if (j < 0) return 1;
        if (i < 0) return 0;
        if (s.charAt(i) == t.charAt(j)) {
            return solve(i - 1, j - 1, s, t) + solve(i - 1, j, s, t);
        }
        return solve(i - 1, j, s, t);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.893Z', '2026-11-20T06:28:30.893Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4s01ezo76vmna6ah2t', 'cmwollk4s01exo76v6rnibbgk', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int numDistinct(String s, String t) {
        int n = s.length(), m = t.length();
        int[] dp = new int[m + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = m; j >= 1; j--) {
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[j] = dp[j] + dp[j - 1];
                }
            }
        }
        return dp[m];
    }
}', 'O(N * M)', 'O(M)', '2026-11-20T06:28:30.893Z', '2026-11-20T06:28:30.893Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5i01huo76vxsx5f83j', 'cmwollk5i01hto76v4wfvtc55', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String longestPrefix(String s) {
        int n = s.length();
        for (int len = n - 1; len >= 1; len--) {
            if (s.startsWith(s.substring(n - len))) {
                return s.substring(0, len);
            }
        }
        return "";
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.919Z', '2026-11-20T06:28:30.919Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4t01f3o76v4xrxn4rf', 'cmwollk4t01f1o76vul2uie66', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int minDistance(String word1, String word2) {
        int n = word1.length(), m = word2.length();
        int[] prev = new int[m + 1];
        for (int j = 0; j <= m; j++) prev[j] = j;
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[m + 1];
            cur[0] = i;
            for (int j = 1; j <= m; j++) {
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    cur[j] = prev[j - 1];
                } else {
                    cur[j] = 1 + Math.min(cur[j - 1], Math.min(prev[j], prev[j - 1]));
                }
            }
            prev = cur;
        }
        return prev[m];
    }
}', 'O(N * M)', 'O(M)', '2026-11-20T06:28:30.893Z', '2026-11-20T06:28:30.893Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4u01f6o76vsrctr80z', 'cmwollk4u01f5o76v4kz27yfo', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public boolean isMatch(String s, String p) {
        return solve(s.length() - 1, p.length() - 1, s, p);
    }
    private boolean solve(int i, int j, String s, String p) {
        if (i < 0 && j < 0) return true;
        if (j < 0 && i >= 0) return false;
        if (i < 0 && j >= 0) {
            for (int k = 0; k <= j; k++) if (p.charAt(k) != ''*'') return false;
            return true;
        }
        if (s.charAt(i) == p.charAt(j) || p.charAt(j) == ''?'') return solve(i - 1, j - 1, s, p);
        if (p.charAt(j) == ''*'') return solve(i - 1, j, s, p) || solve(i, j - 1, s, p);
        return false;
    }
}', 'O(2^(N+M))', 'O(N+M)', '2026-11-20T06:28:30.894Z', '2026-11-20T06:28:30.894Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4u01f7o76vxdxhjw5v', 'cmwollk4u01f5o76v4kz27yfo', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public boolean isMatch(String s, String p) {
        int m = s.length(), n = p.length();
        boolean[] prev = new boolean[n + 1];
        prev[0] = true;
        for (int j = 1; j <= n; j++) {
            if (p.charAt(j - 1) == ''*'') prev[j] = prev[j - 1];
        }
        for (int i = 1; i <= m; i++) {
            boolean[] cur = new boolean[n + 1];
            for (int j = 1; j <= n; j++) {
                if (p.charAt(j - 1) == ''*'') {
                    cur[j] = cur[j - 1] || prev[j];
                } else if (p.charAt(j - 1) == ''?'' || s.charAt(i - 1) == p.charAt(j - 1)) {
                    cur[j] = prev[j - 1];
                }
            }
            prev = cur;
        }
        return prev[n];
    }
}', 'O(M * N)', 'O(N)', '2026-11-20T06:28:30.894Z', '2026-11-20T06:28:30.894Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4v01fao76vypxw9n21', 'cmwollk4v01f9o76vfbyvf484', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        Set<String> set = new HashSet<>(wordDict);
        return solve(0, s, set);
    }
    private boolean solve(int start, String s, Set<String> set) {
        if (start == s.length()) return true;
        for (int end = start + 1; end <= s.length(); end++) {
            if (set.contains(s.substring(start, end)) && solve(end, s, set)) return true;
        }
        return false;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.895Z', '2026-11-20T06:28:30.895Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4v01fbo76v0i5lm099', 'cmwollk4v01f9o76vfbyvf484', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        Set<String> set = new HashSet<>(wordDict);
        int n = s.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] && set.contains(s.substring(j, i))) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n];
    }
}', 'O(N^2 * L)', 'O(N)', '2026-11-20T06:28:30.895Z', '2026-11-20T06:28:30.895Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4w01feo76vojogku2o', 'cmwollk4w01fdo76voxageb5j', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int countPalindromicSubsequences(String s) {
        return solve(0, s.length() - 1, s);
    }
    private static int solve(int i, int j, String s) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (s.charAt(i) == s.charAt(j)) {
            return solve(i + 1, j, s) + solve(i, j - 1, s) + 1;
        }
        return solve(i + 1, j, s) + solve(i, j - 1, s) - solve(i + 1, j - 1, s);
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.896Z', '2026-11-20T06:28:30.896Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5l01i6o76virafifmz', 'cmwollk5l01i5o76vz6w1gn44', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int countPrimesInRange(int L, int R) {
        int count = 0;
        for (int i = L; i <= R; i++) {
            if (i < 2) continue;
            boolean isPrime = true;
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) count++;
        }
        return count;
    }
}', 'O((R - L + 1) * sqrt(R))', 'O(1)', '2026-11-20T06:28:30.921Z', '2026-11-20T06:28:30.921Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4w01ffo76vug0i1mk7', 'cmwollk4w01fdo76voxageb5j', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int countPalindromicSubsequences(String s) {
        int n = s.length();
        long[][] dp = new long[n][n];
        long MOD = 1000000007;
        for (int i = 0; i < n; i++) dp[i][i] = 1;
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] + 1) % MOD;
                } else {
                    dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1] + MOD) % MOD;
                }
            }
        }
        return (int) dp[0][n - 1];
    }
}', 'O(N^2)', 'O(N^2)', '2026-11-20T06:28:30.896Z', '2026-11-20T06:28:30.896Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4x01fio76variw5th0', 'cmwollk4x01fho76vyp9jp1ec', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int matrixMultiplication(int[] arr, int N) {
        return solve(1, N - 1, arr);
    }
    private static int solve(int i, int j, int[] arr) {
        if (i == j) return 0;
        int mini = Integer.MAX_VALUE;
        for (int k = i; k < j; k++) {
            int steps = arr[i - 1] * arr[k] * arr[j] + solve(i, k, arr) + solve(k + 1, j, arr);
            mini = Math.min(mini, steps);
        }
        return mini;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.897Z', '2026-11-20T06:28:30.897Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4x01fjo76vnkvt773x', 'cmwollk4x01fho76vyp9jp1ec', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int matrixMultiplication(int[] arr, int N) {
        int[][] dp = new int[N][N];
        for (int len = 2; len < N; len++) {
            for (int i = 1; i < N - len + 1; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    int steps = arr[i - 1] * arr[k] * arr[j] + dp[i][k] + dp[k + 1][j];
                    dp[i][j] = Math.min(dp[i][j], steps);
                }
            }
        }
        return dp[1][N - 1];
    }
}', 'O(N^3)', 'O(N^2)', '2026-11-20T06:28:30.897Z', '2026-11-20T06:28:30.897Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4y01fmo76vq5wmhkkk', 'cmwollk4y01flo76v3h3eggmw', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxCoins(int[] nums) {
        int n = nums.length;
        int[] a = new int[n + 2];
        a[0] = 1; a[n + 1] = 1;
        for (int i = 0; i < n; i++) a[i + 1] = nums[i];
        return solve(1, n, a);
    }
    private int solve(int i, int j, int[] a) {
        if (i > j) return 0;
        int max = 0;
        for (int ind = i; ind <= j; ind++) {
            int cost = a[i - 1] * a[ind] * a[j + 1] + solve(i, ind - 1, a) + solve(ind + 1, j, a);
            max = Math.max(max, cost);
        }
        return max;
    }
}', 'O(N!)', 'O(N)', '2026-11-20T06:28:30.898Z', '2026-11-20T06:28:30.898Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4y01fno76vame3tt51', 'cmwollk4y01flo76v3h3eggmw', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxCoins(int[] nums) {
        int n = nums.length;
        int[] a = new int[n + 2];
        a[0] = 1; a[n + 1] = 1;
        for (int i = 0; i < n; i++) a[i + 1] = nums[i];
        int[][] dp = new int[n + 2][n + 2];
        for (int len = 1; len <= n; len++) {
            for (int i = 1; i <= n - len + 1; i++) {
                int j = i + len - 1;
                for (int ind = i; ind <= j; ind++) {
                    int cost = a[i - 1] * a[ind] * a[j + 1] + dp[i][ind - 1] + dp[ind + 1][j];
                    dp[i][j] = Math.max(dp[i][j], cost);
                }
            }
        }
        return dp[1][n];
    }
}', 'O(N^3)', 'O(N^2)', '2026-11-20T06:28:30.898Z', '2026-11-20T06:28:30.898Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4z01fqo76vzu42gw50', 'cmwollk4z01fpo76v9wfojg91', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int minCut(String s) {
        return solve(0, s) - 1;
    }
    private int solve(int i, String s) {
        if (i == s.length()) return 0;
        int minCost = Integer.MAX_VALUE;
        for (int j = i; j < s.length(); j++) {
            if (isPalindrome(i, j, s)) {
                int cost = 1 + solve(j + 1, s);
                minCost = Math.min(minCost, cost);
            }
        }
        return minCost;
    }
    private boolean isPalindrome(int i, int j, String s) {
        while (i < j) {
            if (s.charAt(i++) != s.charAt(j--)) return false;
        }
        return true;
    }
}', 'O(2^N)', 'O(N)', '2026-11-20T06:28:30.899Z', '2026-11-20T06:28:30.899Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk4z01fro76ve4b2wp3k', 'cmwollk4z01fpo76v9wfojg91', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int minCut(String s) {
        int n = s.length();
        boolean[][] isPal = new boolean[n][n];
        for (int len = 1; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    isPal[i][j] = (len <= 2) || isPal[i + 1][j - 1];
                }
            }
        }
        int[] dp = new int[n + 1];
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            int minCost = Integer.MAX_VALUE;
            for (int j = i; j < n; j++) {
                if (isPal[i][j]) {
                    minCost = Math.min(minCost, 1 + dp[j + 1]);
                }
            }
            dp[i] = minCost;
        }
        return dp[0] - 1;
    }
}', 'O(N^2)', 'O(N^2)', '2026-11-20T06:28:30.899Z', '2026-11-20T06:28:30.899Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5001fuo76v5dpr5d9a', 'cmwollk5001fto76vldu3vich', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public int maxSumAfterPartitioning(int[] arr, int k) {
        return solve(0, arr, k);
    }
    private int solve(int ind, int[] arr, int k) {
        if (ind == arr.length) return 0;
        int len = 0, maxi = Integer.MIN_VALUE, maxAns = Integer.MIN_VALUE;
        for (int j = ind; j < Math.min(arr.length, ind + k); j++) {
            len++;
            maxi = Math.max(maxi, arr[j]);
            int sum = len * maxi + solve(j + 1, arr, k);
            maxAns = Math.max(maxAns, sum);
        }
        return maxAns;
    }
}', 'O(K^N)', 'O(N)', '2026-11-20T06:28:30.900Z', '2026-11-20T06:28:30.900Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5001fvo76vwjl0bhbt', 'cmwollk5001fto76vldu3vich', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public int maxSumAfterPartitioning(int[] arr, int k) {
        int n = arr.length;
        int[] dp = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            int len = 0, maxi = Integer.MIN_VALUE, maxAns = Integer.MIN_VALUE;
            for (int j = i; j < Math.min(n, i + k); j++) {
                len++;
                maxi = Math.max(maxi, arr[j]);
                int sum = len * maxi + dp[j + 1];
                maxAns = Math.max(maxAns, sum);
            }
            dp[i] = maxAns;
        }
        return dp[0];
    }
}', 'O(N * K)', 'O(N)', '2026-11-20T06:28:30.900Z', '2026-11-20T06:28:30.900Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5101fyo76veel91n6n', 'cmwollk5101fxo76vgyrdsiik', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.*;
public class Solution {
    public int minCost(int n, int[] cuts) {
        List<Integer> list = new ArrayList<>();
        list.add(0);
        for (int c : cuts) list.add(c);
        list.add(n);
        Collections.sort(list);
        return solve(1, cuts.length, list);
    }
    private int solve(int i, int j, List<Integer> cuts) {
        if (i > j) return 0;
        int mini = Integer.MAX_VALUE;
        for (int ind = i; ind <= j; ind++) {
            int cost = cuts.get(j + 1) - cuts.get(i - 1) + solve(i, ind - 1, cuts) + solve(ind + 1, j, cuts);
            mini = Math.min(mini, cost);
        }
        return mini;
    }
}', 'O(C!)', 'O(C)', '2026-11-20T06:28:30.901Z', '2026-11-20T06:28:30.901Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5101fzo76vggs191co', 'cmwollk5101fxo76vgyrdsiik', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.*;
public class Solution {
    public int minCost(int n, int[] cuts) {
        int c = cuts.length;
        int[] arr = new int[c + 2];
        arr[0] = 0; arr[c + 1] = n;
        for (int i = 0; i < c; i++) arr[i + 1] = cuts[i];
        Arrays.sort(arr);
        int[][] dp = new int[c + 2][c + 2];
        for (int len = 1; len <= c; len++) {
            for (int i = 1; i <= c - len + 1; i++) {
                int j = i + len - 1;
                int mini = Integer.MAX_VALUE;
                for (int ind = i; ind <= j; ind++) {
                    int cost = arr[j + 1] - arr[i - 1] + dp[i][ind - 1] + dp[ind + 1][j];
                    mini = Math.min(mini, cost);
                }
                dp[i][j] = mini;
            }
        }
        return dp[1][c];
    }
}', 'O(C^3)', 'O(C^2)', '2026-11-20T06:28:30.901Z', '2026-11-20T06:28:30.901Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5201g2o76vo74csl1h', 'cmwollk5201g1o76vtr48o4y8', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int evaluateExp(String exp) {
        return (int) solve(0, exp.length() - 1, 1, exp);
    }
    private static long solve(int i, int j, int isTrue, String exp) {
        if (i > j) return 0;
        if (i == j) {
            if (isTrue == 1) return exp.charAt(i) == ''T'' ? 1 : 0;
            else return exp.charAt(i) == ''F'' ? 1 : 0;
        }
        long ways = 0;
        for (int ind = i + 1; ind <= j - 1; ind += 2) {
            long lT = solve(i, ind - 1, 1, exp);
            long lF = solve(i, ind - 1, 0, exp);
            long rT = solve(ind + 1, j, 1, exp);
            long rF = solve(ind + 1, j, 0, exp);
            char op = exp.charAt(ind);
            if (op == ''&'') {
                if (isTrue == 1) ways += lT * rT;
                else ways += lF * rT + lT * rF + lF * rF;
            } else if (op == ''|'') {
                if (isTrue == 1) ways += lT * rT + lF * rT + lT * rF;
                else ways += lF * rF;
            } else if (op == ''^'') {
                if (isTrue == 1) ways += lT * rF + lF * rT;
                else ways += lT * rT + lF * rF;
            }
        }
        return ways % 1000000007;
    }
}', 'O(3^N)', 'O(N)', '2026-11-20T06:28:30.902Z', '2026-11-20T06:28:30.902Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5601gio76vghbrd91e', 'cmwollk5601gho76vqwzaynwc', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static String completeString(int n, String[] a) {
        Arrays.sort(a);
        Set<String> set = new HashSet<>(Arrays.asList(a));
        String longest = "";
        for (String word : a) {
            boolean valid = true;
            for (int i = 1; i <= word.length(); i++) {
                if (!set.contains(word.substring(0, i))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                if (word.length() > longest.length()) longest = word;
            }
        }
        return longest.isEmpty() ? "None" : longest;
    }
}', 'O(N * L²)', 'O(N * L)', '2026-11-20T06:28:30.907Z', '2026-11-20T06:28:30.907Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5201g3o76v2qg4l2uz', 'cmwollk5201g1o76vtr48o4y8', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int evaluateExp(String exp) {
        int n = exp.length();
        long[][][] dp = new long[n][n][2];
        long MOD = 1000000007;
        for (int i = 0; i < n; i += 2) {
            dp[i][i][1] = (exp.charAt(i) == ''T'') ? 1 : 0;
            dp[i][i][0] = (exp.charAt(i) == ''F'') ? 1 : 0;
        }
        for (int len = 3; len <= n; len += 2) {
            for (int i = 0; i <= n - len; i += 2) {
                int j = i + len - 1;
                for (int ind = i + 1; ind < j; ind += 2) {
                    long lT = dp[i][ind - 1][1], lF = dp[i][ind - 1][0];
                    long rT = dp[ind + 1][j][1], rF = dp[ind + 1][j][0];
                    char op = exp.charAt(ind);
                    if (op == ''&'') {
                        dp[i][j][1] = (dp[i][j][1] + lT * rT) % MOD;
                        dp[i][j][0] = (dp[i][j][0] + lF * rT + lT * rF + lF * rF) % MOD;
                    } else if (op == ''|'') {
                        dp[i][j][1] = (dp[i][j][1] + lT * rT + lF * rT + lT * rF) % MOD;
                        dp[i][j][0] = (dp[i][j][0] + lF * rF) % MOD;
                    } else if (op == ''^'') {
                        dp[i][j][1] = (dp[i][j][1] + lT * rF + lF * rT) % MOD;
                        dp[i][j][0] = (dp[i][j][0] + lT * rT + lF * rF) % MOD;
                    }
                }
            }
        }
        return (int) dp[0][n - 1][1];
    }
}', 'O(N^3)', 'O(N^2)', '2026-11-20T06:28:30.902Z', '2026-11-20T06:28:30.902Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5301g6o76v4th3t4n5', 'cmwollk5301g5o76vrcbamu9p', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
