INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5401gao76vdadmbhnr', 'cmwollk5401g9o76vtv8a3tr9', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isEnd;
    }

    static class Trie {
        TrieNode root = new TrieNode();

        public void insert(String word) {
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                if (node.children[idx] == null) node.children[idx] = new TrieNode();
                node = node.children[idx];
            }
            node.isEnd = true;
        }

        public boolean search(String word) {
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                if (node.children[idx] == null) return false;
                node = node.children[idx];
            }
            return node.isEnd;
        }

        public boolean startsWith(String prefix) {
            TrieNode node = root;
            for (char c : prefix.toCharArray()) {
                int idx = c - ''a'';
                if (node.children[idx] == null) return false;
                node = node.children[idx];
            }
            return true;
        }
    }
}', 'O(L)', 'O(L * 26)', '2026-11-20T06:28:30.904Z', '2026-11-20T06:28:30.904Z') ON CONFLICT DO NOTHING;
