INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5501geo76v0qm7gwa1', 'cmwollk5501gdo76vw1mc3486', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    static class Node {
        Node[] links = new Node[26];
        int countPrefix = 0;
        int countEndsWith = 0;
    }

    static class Trie {
        Node root = new Node();

        public void insert(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                if (node.links[idx] == null) node.links[idx] = new Node();
                node = node.links[idx];
                node.countPrefix++;
            }
            node.countEndsWith++;
        }

        public int countWordsEqualTo(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                if (node.links[idx] == null) return 0;
                node = node.links[idx];
            }
            return node.countEndsWith;
        }

        public int countWordsStartingWith(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                if (node.links[idx] == null) return 0;
                node = node.links[idx];
            }
            return node.countPrefix;
        }

        public void erase(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                node = node.links[idx];
                node.countPrefix--;
            }
            node.countEndsWith--;
        }
    }
}', 'O(L)', 'O(L * 26)', '2026-11-20T06:28:30.905Z', '2026-11-20T06:28:30.905Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5501gfo76voly0dum6', 'cmwollk5501gdo76vw1mc3486', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
