INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5601gjo76v7cl5z0r3', 'cmwollk5601gho76vqwzaynwc', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    static class Node {
        Node[] links = new Node[26];
        boolean flag = false;
    }

    static class Trie {
        Node root = new Node();

        void insert(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                if (node.links[idx] == null) node.links[idx] = new Node();
                node = node.links[idx];
            }
            node.flag = true;
        }

        boolean checkIfAllPrefixExists(String word) {
            Node node = root;
            for (char c : word.toCharArray()) {
                int idx = c - ''a'';
                if (node.links[idx] != null) {
                    node = node.links[idx];
                    if (!node.flag) return false;
                } else return false;
            }
            return true;
        }
    }

    public static String completeString(int n, String[] a) {
        Trie trie = new Trie();
        for (String word : a) trie.insert(word);
        String longest = "";
        for (String word : a) {
            if (trie.checkIfAllPrefixExists(word)) {
                if (word.length() > longest.length() || (word.length() == longest.length() && word.compareTo(longest) < 0)) {
                    longest = word;
                }
            }
        }
        return longest.isEmpty() ? "None" : longest;
    }
}', 'O(N * L)', 'O(N * L)', '2026-11-20T06:28:30.907Z', '2026-11-20T06:28:30.907Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5701gmo76vkqw2xi5y', 'cmwollk5701glo76v1gjrdduy', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static int countDistinctSubstrings(String s) {
        Set<String> set = new HashSet<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                set.add(s.substring(i, j));
            }
        }
        return set.size() + 1;
    }
}', 'O(N³)', 'O(N³)', '2026-11-20T06:28:30.908Z', '2026-11-20T06:28:30.908Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5701gno76vxoeolxzx', 'cmwollk5701glo76v1gjrdduy', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    static class Node {
        Node[] links = new Node[26];
    }

    public static int countDistinctSubstrings(String s) {
        Node root = new Node();
        int count = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            Node node = root;
            for (int j = i; j < n; j++) {
                int idx = s.charAt(j) - ''a'';
                if (node.links[idx] == null) {
                    node.links[idx] = new Node();
                    count++;
                }
                node = node.links[idx];
            }
        }
        return count + 1;
    }
}', 'O(N²)', 'O(N² * 26)', '2026-11-20T06:28:30.908Z', '2026-11-20T06:28:30.908Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5801gqo76vtves70ws', 'cmwollk5801gpo76vhb7xuhi7', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int findMaximumXOR(int[] nums) {
        int max = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                max = Math.max(max, nums[i] ^ nums[j]);
            }
        }
        return max;
    }
}', 'O(N²)', 'O(1)', '2026-11-20T06:28:30.909Z', '2026-11-20T06:28:30.909Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5801gro76va7bhrstk', 'cmwollk5801gpo76vhb7xuhi7', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    static class Node {
        Node[] links = new Node[2];
    }

    static class Trie {
        Node root = new Node();

        void insert(int num) {
            Node node = root;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.links[bit] == null) node.links[bit] = new Node();
                node = node.links[bit];
            }
        }

        int getMax(int num) {
            Node node = root;
            int maxNum = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.links[1 - bit] != null) {
                    maxNum |= (1 << i);
                    node = node.links[1 - bit];
                } else {
                    node = node.links[bit];
                }
            }
            return maxNum;
        }
    }

    public static int findMaximumXOR(int[] nums) {
        Trie trie = new Trie();
        for (int num : nums) trie.insert(num);
        int max = 0;
        for (int num : nums) max = Math.max(max, trie.getMax(num));
        return max;
    }
}', 'O(32 * N)', 'O(32 * N)', '2026-11-20T06:28:30.909Z', '2026-11-20T06:28:30.909Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5901guo76v5urs5ze8', 'cmwollk5901gto76vhimk89aw', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] maximizeXor(int[] nums, int[][] queries) {
        int[] ans = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int x = queries[q][0], m = queries[q][1];
            int max = -1;
            for (int num : nums) {
                if (num <= m) max = Math.max(max, num ^ x);
            }
            ans[q] = max;
        }
        return ans;
    }
}', 'O(Q * N)', 'O(1)', '2026-11-20T06:28:30.910Z', '2026-11-20T06:28:30.910Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5901gvo76vjmoi1190', 'cmwollk5901gto76vhimk89aw', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    static class Node { Node[] links = new Node[2]; }
    static class Trie {
        Node root = new Node();
        void insert(int num) {
            Node node = root;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.links[bit] == null) node.links[bit] = new Node();
                node = node.links[bit];
            }
        }
        int getMax(int num) {
            Node node = root;
            if (node.links[0] == null && node.links[1] == null) return -1;
            int maxNum = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                if (node.links[1 - bit] != null) {
                    maxNum |= (1 << i);
                    node = node.links[1 - bit];
                } else {
                    node = node.links[bit];
                }
            }
            return maxNum;
        }
    }

    public static int[] maximizeXor(int[] nums, int[][] queries) {
        Arrays.sort(nums);
        int q = queries.length;
        int[][] offlineQueries = new int[q][3];
        for (int i = 0; i < q; i++) {
            offlineQueries[i][0] = queries[i][0];
            offlineQueries[i][1] = queries[i][1];
            offlineQueries[i][2] = i;
        }
        Arrays.sort(offlineQueries, Comparator.comparingInt(a -> a[1]));
        int[] ans = new int[q];
        Trie trie = new Trie();
        int idx = 0, n = nums.length;
        for (int i = 0; i < q; i++) {
            int x = offlineQueries[i][0], m = offlineQueries[i][1], queryIdx = offlineQueries[i][2];
            while (idx < n && nums[idx] <= m) {
                trie.insert(nums[idx++]);
            }
            ans[queryIdx] = trie.getMax(x);
        }
        return ans;
    }
}', 'O(N log N + Q log Q + (N + Q) * 32)', 'O(N * 32)', '2026-11-20T06:28:30.910Z', '2026-11-20T06:28:30.910Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5b01gyo76vsobjzcxc', 'cmwollk5b01gxo76v0xopvwjq', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String reverseWords(String s) {
        String[] words = s.trim().split("\\s+");
        StringBuilder sb = new StringBuilder();
        for (int i = words.length - 1; i >= 0; i--) {
            sb.append(words[i]);
            if (i > 0) sb.append(" ");
        }
        return sb.toString();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.911Z', '2026-11-20T06:28:30.911Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5b01gzo76v6ij5jg8w', 'cmwollk5b01gxo76v0xopvwjq', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static String reverseWords(String s) {
        StringBuilder sb = new StringBuilder();
        int n = s.length(), i = n - 1;
        while (i >= 0) {
            while (i >= 0 && s.charAt(i) == '' '') i--;
            if (i < 0) break;
            int j = i;
            while (i >= 0 && s.charAt(i) != '' '') i--;
            if (sb.length() > 0) sb.append(" ");
            sb.append(s, i + 1, j + 1);
        }
        return sb.toString();
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.911Z', '2026-11-20T06:28:30.911Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5c01h2o76v5cu82qqj', 'cmwollk5c01h1o76vfh4i1quo', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.Stack;

public class Solution {
    public static int countRev(String s) {
        if (s.length() % 2 != 0) return -1;
        Stack<Character> st = new Stack<>();
        for (char c : s.toCharArray()) {
            if (c == ''{'') st.push(c);
            else {
                if (!st.isEmpty() && st.peek() == ''{'') st.pop();
                else st.push(c);
            }
        }
        int open = 0, close = 0;
        while (!st.isEmpty()) {
            if (st.pop() == ''{'') open++;
            else close++;
        }
        return (open + 1) / 2 + (close + 1) / 2;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.912Z', '2026-11-20T06:28:30.912Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5d01h6o76vln1sd11m', 'cmwollk5d01h5o76v13qofa1l', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String countAndSay(int n) {
        if (n == 1) return "1";
        String s = "1";
        for (int i = 2; i <= n; i++) {
            StringBuilder sb = new StringBuilder();
            int count = 1;
            for (int j = 1; j < s.length(); j++) {
                if (s.charAt(j) == s.charAt(j - 1)) {
                    count++;
                } else {
                    sb.append(count).append(s.charAt(j - 1));
                    count = 1;
                }
            }
            sb.append(count).append(s.charAt(s.length() - 1));
            s = sb.toString();
        }
        return s;
    }
}', 'O(N * 2^N)', 'O(2^N)', '2026-11-20T06:28:30.914Z', '2026-11-20T06:28:30.914Z') ON CONFLICT DO NOTHING;
