INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5e01hao76v1m4qwznu', 'cmwollk5e01h9o76vdux1afz4', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static long computeHash(String s) {
        // Polynomial rolling hash baseline
        long hash = 0, p = 31, m = 1_000_000_007L;
        long p_pow = 1;
        for (char c : s.toCharArray()) {
            hash = (hash + (c - ''a'' + 1) * p_pow) % m;
            p_pow = (p_pow * p) % m;
        }
        return hash;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.915Z', '2026-11-20T06:28:30.915Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5e01hbo76vmif4a8um', 'cmwollk5e01h9o76vdux1afz4', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static long computeHash(String s) {
        long hash = 0, p = 31, m = 1_000_000_007L;
        long p_pow = 1;
        for (char c : s.toCharArray()) {
            hash = (hash + (c - ''a'' + 1) * p_pow) % m;
            p_pow = (p_pow * p) % m;
        }
        return hash;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.915Z', '2026-11-20T06:28:30.915Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5f01hfo76vncdq1rsg', 'cmwollk5f01hdo76vnpryd1bb', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> search(String pat, String txt) {
        List<Integer> res = new ArrayList<>();
        int d = 256, q = 101;
        int m = pat.length(), n = txt.length();
        int p = 0, t = 0, h = 1;
        for (int i = 0; i < m - 1; i++) h = (h * d) % q;
        for (int i = 0; i < m; i++) {
            p = (d * p + pat.charAt(i)) % q;
            t = (d * t + txt.charAt(i)) % q;
        }
        for (int i = 0; i <= n - m; i++) {
            if (p == t) {
                boolean match = true;
                for (int j = 0; j < m; j++) {
                    if (txt.charAt(i + j) != pat.charAt(j)) { match = false; break; }
                }
                if (match) res.add(i);
            }
            if (i < n - m) {
                t = (d * (t - txt.charAt(i) * h) + txt.charAt(i + m)) % q;
                if (t < 0) t += q;
            }
        }
        return res;
    }
}', 'O(N + M)', 'O(1)', '2026-11-20T06:28:30.916Z', '2026-11-20T06:28:30.916Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5g01hio76vfytrlf20', 'cmwollk5g01hho76v715fqxzz', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static int[] calculateZ(String s) {
        int n = s.length();
        int[] z = new int[n];
        for (int i = 1; i < n; i++) {
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) {
                z[i]++;
            }
        }
        return z;
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.916Z', '2026-11-20T06:28:30.916Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5g01hjo76vzkcv0ryu', 'cmwollk5g01hho76v715fqxzz', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static int[] calculateZ(String s) {
        int n = s.length();
        int[] z = new int[n];
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            if (i + z[i] - 1 > r) { l = i; r = i + z[i] - 1; }
        }
        return z;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.916Z', '2026-11-20T06:28:30.916Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5h01hmo76vvnhgas4q', 'cmwollk5h01hlo76vlg29mni6', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> search(String pat, String txt) {
        List<Integer> ans = new ArrayList<>();
        int m = pat.length(), n = txt.length();
        for (int i = 0; i <= n - m; i++) {
            if (txt.substring(i, i + m).equals(pat)) ans.add(i);
        }
        return ans;
    }
}', 'O(N * M)', 'O(1)', '2026-11-20T06:28:30.917Z', '2026-11-20T06:28:30.917Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5h01hno76v5r006stv', 'cmwollk5h01hlo76vlg29mni6', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> search(String pat, String txt) {
        List<Integer> ans = new ArrayList<>();
        int[] lps = computeLPS(pat);
        int i = 0, j = 0;
        while (i < txt.length()) {
            if (txt.charAt(i) == pat.charAt(j)) { i++; j++; }
            if (j == pat.length()) {
                ans.add(i - j);
                j = lps[j - 1];
            } else if (i < txt.length() && txt.charAt(i) != pat.charAt(j)) {
                if (j != 0) j = lps[j - 1];
                else i++;
            }
        }
        return ans;
    }

    private static int[] computeLPS(String pat) {
        int[] lps = new int[pat.length()];
        int len = 0, i = 1;
        while (i < pat.length()) {
            if (pat.charAt(i) == pat.charAt(len)) lps[i++] = ++len;
            else if (len != 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        return lps;
    }
}', 'O(N + M)', 'O(M)', '2026-11-20T06:28:30.917Z', '2026-11-20T06:28:30.917Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5h01hqo76v5mckt14i', 'cmwollk5h01hpo76vuu5wbfc2', 'BRUTE_FORCE', 'Brute Force Solution', '', 'public class Solution {
    public static String shortestPalindrome(String s) {
        int i = 0;
        for (int j = s.length() - 1; j >= 0; j--) {
            if (s.charAt(i) == s.charAt(j)) i++;
        }
        if (i == s.length()) return s;
        String suffix = s.substring(i);
        String prefix = new StringBuilder(suffix).reverse().toString();
        return prefix + shortestPalindrome(s.substring(0, i)) + suffix;
    }
}', 'O(N²)', 'O(N)', '2026-11-20T06:28:30.918Z', '2026-11-20T06:28:30.918Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5h01hro76vdj05f6tz', 'cmwollk5h01hpo76vuu5wbfc2', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static String shortestPalindrome(String s) {
        String temp = s + "#" + new StringBuilder(s).reverse().toString();
        int[] lps = new int[temp.length()];
        for (int i = 1; i < temp.length(); i++) {
            int len = lps[i - 1];
            while (len > 0 && temp.charAt(i) != temp.charAt(len)) len = lps[len - 1];
            if (temp.charAt(i) == temp.charAt(len)) len++;
            lps[i] = len;
        }
        int longestPrefix = lps[temp.length() - 1];
        String rem = s.substring(longestPrefix);
        return new StringBuilder(rem).reverse().toString() + s;
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.918Z', '2026-11-20T06:28:30.918Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5i01hvo76vlqj3e49a', 'cmwollk5i01hto76v4wfvtc55', 'OPTIMAL', 'Optimal Solution', '', 'public class Solution {
    public static String longestPrefix(String s) {
        int[] lps = new int[s.length()];
        int len = 0, i = 1;
        while (i < s.length()) {
            if (s.charAt(i) == s.charAt(len)) lps[i++] = ++len;
            else if (len != 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        return s.substring(0, lps[s.length() - 1]);
    }
}', 'O(N)', 'O(N)', '2026-11-20T06:28:30.919Z', '2026-11-20T06:28:30.919Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5j01hyo76v4xduiwe1', 'cmwollk5j01hxo76va4izqt2m', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> primesTillN(int n) {
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            boolean isPrime = true;
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) primes.add(i);
        }
        return primes;
    }
}', 'O(N * sqrt(N))', 'O(1)', '2026-11-20T06:28:30.920Z', '2026-11-20T06:28:30.920Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5j01hzo76v2pbbjdcs', 'cmwollk5j01hxo76va4izqt2m', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public static List<Integer> primesTillN(int n) {
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);
        List<Integer> primes = new ArrayList<>();
        for (int p = 2; p * p <= n; p++) {
            if (isPrime[p]) {
                for (int i = p * p; i <= n; i += p) {
                    isPrime[i] = false;
                }
            }
        }
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) primes.add(i);
        }
        return primes;
    }
}', 'O(N log(log N))', 'O(N)', '2026-11-20T06:28:30.920Z', '2026-11-20T06:28:30.920Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5k01i2o76v2uu7ydy5', 'cmwollk5k01i1o76vb0lkvegf', 'BRUTE_FORCE', 'Brute Force Solution', '', 'import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> primeFactors(int n) {
        List<Integer> factors = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }
        return factors;
    }
}', 'O(N)', 'O(1)', '2026-11-20T06:28:30.921Z', '2026-11-20T06:28:30.921Z') ON CONFLICT DO NOTHING;
INSERT INTO "problem_codes" ("id", "problemId", "approachType", "title", "explanation", "javaCode", "timeComplexity", "spaceComplexity", "createdAt", "updatedAt") VALUES ('cmwollk5l01i7o76vu7lprxke', 'cmwollk5l01i5o76vz6w1gn44', 'OPTIMAL', 'Optimal Solution', '', 'import java.util.Arrays;

public class Solution {
    public static int countPrimesInRange(int L, int R) {
        int limit = (int) Math.sqrt(R);
        boolean[] prime = new boolean[limit + 1];
        Arrays.fill(prime, true);
        for (int p = 2; p * p <= limit; p++) {
            if (prime[p]) {
                for (int i = p * p; i <= limit; i += p) {
                    prime[i] = false;
                }
            }
        }

        boolean[] isPrime = new boolean[R - L + 1];
        Arrays.fill(isPrime, true);
        for (int i = 2; i <= limit; i++) {
            if (prime[i]) {
                int base = (L / i) * i;
                if (base < L) base += i;
                for (int j = Math.max(base, i * i); j <= R; j += i) {
                    isPrime[j - L] = false;
                }
            }
        }

        int count = 0;
        for (int i = 0; i < R - L + 1; i++) {
            if (isPrime[i] && (i + L) >= 2) count++;
        }
        return count;
    }
}', 'O((R - L + 1) log(log R) + sqrt(R))', 'O(R - L + 1)', '2026-11-20T06:28:30.921Z', '2026-11-20T06:28:30.921Z') ON CONFLICT DO NOTHING;

