INSERT INTO "code_submissions" ("id", "userId", "problemId", "language", "code", "status", "executionTime", "memoryUsage", "passedTests", "totalTests", "errorOutput", "createdAt") VALUES ('cmwwa96q3000boq9jj91jquoa', 'cmww5zqrr000075eqbkj0s9l6', 'cmwollju800bho76v0ryu6e0s', 'javascript', 'class Solution {
    twoSum(nums, target) {
        const map = new Map();
        for (let i = 0; i < nums.length; i++) {
            const comp = target - nums[i];
            if (map.has(comp)) return [map.get(comp), i];
            map.set(nums[i], i);
        }
