INSERT INTO "code_submissions" ("id", "userId", "problemId", "language", "code", "status", "executionTime", "memoryUsage", "passedTests", "totalTests", "errorOutput", "createdAt") VALUES ('cmwx3yr49000512qglt5ws89y', 'cmwp4hkkq0001zsg4p4jmhn3e', 'cmwolljxa00odo76vta8olkll', 'java', '/**
 * Definition for singly-linked list.
 * class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
/**
 * Definition for singly-linked list.
 * class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode(int x) {
 *         val = x;
 *         next = null;
 *     }
 * }
 */
public class Solution {
    public boolean hasCycle(ListNode head) {
        if (head == null || head.next == null) {
            return false;
        }

        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;          // Moves 1 step
            fast = fast.next.next;     // Moves 2 steps

            if (slow == fast) {        // Cycle detected
                return true;
            }
        }

        return false;                  // Reached the end without a cycle
    }
}', 'ACCEPTED', 0.164, 214332, 6, 6, NULL, '2026-11-26T05:24:48.566Z') ON CONFLICT DO NOTHING;
INSERT INTO "code_submissions" ("id", "userId", "problemId", "language", "code", "status", "executionTime", "memoryUsage", "passedTests", "totalTests", "errorOutput", "createdAt") VALUES ('cmwx415ha000d12qg3empqo4o', 'cmwp4hkkq0001zsg4p4jmhn3e', 'cmwollk3m01ado76v9kohythj', 'java', 'class Solution {
    public int climbStairs(int n) {
        if (n <= 2) {
            return n;
        }

        int prev2 = 1; // Ways to reach step 1
        int prev1 = 2; // Ways to reach step 2

        for (int i = 3; i <= n; i++) {
            int current = prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }
}', 'ACCEPTED', 0.177, 214628, 6, 6, NULL, '2026-11-26T05:26:40.894Z') ON CONFLICT DO NOTHING;
