INSERT INTO "code_submissions" ("id", "userId", "problemId", "language", "code", "status", "executionTime", "memoryUsage", "passedTests", "totalTests", "errorOutput", "createdAt") VALUES ('cmwykokge000coscgb6ppxczq', 'cmwp4hkkq0001zsg4p4jmhn3e', 'cmwolljyp00spo76v4orolvl2', 'java', 'class Solution {
    public int jump(int[] nums) {
        int jumps = 0;
        int currentEnd = 0;
        int farthest = 0;

        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);

            if (i == currentEnd) {
                jumps++;
                currentEnd = farthest;
            }
        }

        return jumps;
    }
}', 'ACCEPTED', 0.192, 214040, 6, 6, NULL, '2026-11-27T06:00:33.422Z') ON CONFLICT DO NOTHING;
INSERT INTO "code_submissions" ("id", "userId", "problemId", "language", "code", "status", "executionTime", "memoryUsage", "passedTests", "totalTests", "errorOutput", "createdAt") VALUES ('cmwyl1azp000512ykx3udk7rm', 'cmwp4hkkm0000zsg4bkv3woni', 'cmwollk250151o76voiw9jdu6', 'java', 'class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();

        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }

        List<List<Integer>> bucket = new ArrayList<>();

        for (int i = 0; i <= nums.length; i++) {
            bucket.add(new ArrayList<>());
        }

        for (int num : map.keySet()) {
            bucket.get(map.get(num)).add(num);
        }

        int[] result = new int[k];
        int index = 0;

        for (int i = nums.length; i >= 1; i--) {
            for (int num : bucket.get(i)) {
                result[index++] = num;

                if (index == k) {
                    return result;
                }
            }
        }

        return result;
    }
}', 'ACCEPTED', 0.166, 214480, 6, 6, NULL, '2026-11-27T06:10:27.686Z') ON CONFLICT DO NOTHING;
INSERT INTO "code_submissions" ("id", "userId", "problemId", "language", "code", "status", "executionTime", "memoryUsage", "passedTests", "totalTests", "errorOutput", "createdAt") VALUES ('cmwyl394m000f12ykftc39zii', 'cmwp4hkkm0000zsg4bkv3woni', 'cmwollk2e015xo76vb2b9o1lc', 'java', 'class Solution {
    public int orangesRotting(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        Queue<int[]> queue = new LinkedList<>();
        int fresh = 0;
        int minutes = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) {
                    queue.offer(new int[]{i, j});
                } else if (grid[i][j] == 1) {
                    fresh++;
                }
            }
        }

        int[][] directions = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        while (!queue.isEmpty() && fresh > 0) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                int[] cell = queue.poll();

                for (int[] dir : directions) {
                    int r = cell[0] + dir[0];
                    int c = cell[1] + dir[1];

                    if (r >= 0 && r < m && c >= 0 && c < n
                            && grid[r][c] == 1) {

                        grid[r][c] = 2;
                        fresh--;
                        queue.offer(new int[]{r, c});
                    }
                }
            }

            minutes++;
        }

        return fresh == 0 ? minutes : -1;
    }
}', 'ACCEPTED', 0.174, 214544, 6, 6, NULL, '2026-11-27T06:11:58.582Z') ON CONFLICT DO NOTHING;

